window.__ARXIV_DATA__ = {"papers":[{"id":"2608.31159v1","title":"BRF-GS: Hyperspectral Bidirectional Reflectance Factor Modeling and Image Generation Based on 3D Gaussian Splatting","abstract":"The bidirectional reflectance factor (BRF) characterizes the directional radiative properties of terrestrial surfaces. However, existing three-dimensional (3D) radiative transfer models require complex scene construction and computationally intensive radiative transfer solvers, limiting efficient generation of multi-angle hyperspectral reflectance imagery. 3D Gaussian Splatting (3DGS) offers an efficient framework for neural scene representation and novel view synthesis, but its low-order spherical harmonics representation is insufficient for complex directional reflectance, while the high dimensionality and inter-band quality differences of hyperspectral data introduce additional challenges. To address these challenges, we propose BRF-GS, a 3DGS-based framework for BRF modeling and hyperspectral reflectance image generation. BRF-GS introduces a hybrid BRDF-driven kernel to represent complex directional reflectance, selects geometry-reliable spectral bands for robust 3D scene initialization, and adopts a two-stage training strategy that decouples geometry optimization from spectral modeling. We further construct the AIR-BRF dataset, a multi-angle hyperspectral directional reflectance dataset comprising three scenes with diverse natural and artificial targets. Experiments demonstrate that BRF-GS achieves superior spatial and spectral fidelity and accurately reproduces characteristic view-dependent BRF responses. The proposed framework provides an efficient data-driven approach for BRF modeling and multi-angle hyperspectral reflectance image generation in remote sensing scenes.","authors":["Yiling Yao","Wenjuan Zhang","Bowen Wang","Bocheng Li","Wentao Song","Bing Zhang"],"published":"2026-08-31T17:56:57Z","updated":"2026-08-31T17:56:57Z","abstract_url":"https://arxiv.org/abs/2608.31159v1","html_url":"https://arxiv.org/html/2608.31159v1","pdf_url":"https://arxiv.org/pdf/2608.31159v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":1719,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d, representation 相关；摘要显示其主要贡献为：The bidirectional reflectance factor (BRF) characterizes the directional radiative properties of terrestrial surfaces. However, existing three-dimensional (3D) radiative transfer models require complex scene construction and computationally intensive radiativ...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"abstract","created_at":"2026-09-01T05:58:31+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.31113v1","title":"BLARM: Animating 3D Objects from Video via Blending Latent Rigid Motion Primitives","abstract":"We introduce BLARM, a feed-forward method for video-driven 3D mesh animation. Given a monocular video and a static object mesh, BLARM predicts a temporally coherent animated mesh whose motion follows the video. Rather than relying on explicit rigs or directly regressing high-dimensional vertex motion, we represent animation using a compact set of learned, time-varying rigid motion components and time-invariant vertex-to-component skinning weights. This yields a low-dimensional deformation space without requiring skeletons, cages, skinning weights, or rig annotations. Our architecture conditions geometry-derived deformation latents on video features through factorized spatial-temporal attention, then decodes rigid transformations blended by predicted skinning weights. Trained with trajectory reconstruction, entropy regularization, and motion-aware contrastive learning, BLARM produces accurate and temporally stable animations while recovering compact, interpretable motion structure from monocular video.","authors":["Pradyumn Goyal","Yizhak Ben-Shabat","Hsueh-Ti Derek Liu","Haomiao Jiang","Snehasish Mukherjee","Kyle Spence","Mark Stauber","Evangelos Kalogerakis","Yunze Zeng"],"published":"2026-08-31T17:21:54Z","updated":"2026-08-31T17:21:54Z","abstract_url":"https://arxiv.org/abs/2608.31113v1","html_url":"https://arxiv.org/html/2608.31113v1","pdf_url":"https://arxiv.org/pdf/2608.31113v1.pdf","matched_keywords":["video","3d"],"source_used":"html","source_text_chars":74879,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d 相关；摘要显示其主要贡献为：We introduce BLARM, a feed-forward method for video-driven 3D mesh animation. Given a monocular video and a static object mesh, BLARM predicts a temporally coherent animated mesh whose motion follows the video. Rather than relying on explicit rigs or directly...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:31+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.31107v1","title":"VeriCam: A Verification Baseline for the Classification of Unknown Data","abstract":"The advent of foundation models have enabled a new era in zero-shot classification. Yet, key challenges persist. Despite their impressive generalization power that leverages the immense pre-training knowledge, both foundation models for image and text as well as vision-text hybrids lack the representational power needed for fine-grained, minutiae-based class separation that some real-world tasks require. To address the current gaps in the literature, we propose VeriCam, a pipeline designed to learn highly specialized features that enable classification of unknown classes in unseen data. VeriCam works by leveraging the representation power of image models trained for the verification task, where the model develops an intricate feature space that incorporates fine-grained details. By training a model to discriminate between pairs of images from the same and different classes, a relational graph is constructed, representing the class relationships between data points. We then present two approaches for graph clustering: a naive algorithm and a specific setup for the Leiden graph clustering algorithm. The pipeline is validated on the LPLCv2 dataset, which comprises real-world traffic surveillance images. We show that the dataset carries an inherent capture device bias that is posed as a generalization challenge for downstream License Plate recognition tasks such as OCR. As such, we dynamically identify capture devices with a label-agnostic approach, enabling the construction of a fair and unbiased benchmark. In the cross-device scenario, our pipeline reaches an F1-Score of 93.45 in the verification baseline and a V-Measure score of 80.13 in the clustering step. All code is publicly available at https://github.com/lmlwojcik/VeriCam","authors":["Lucas Wojcik","Gabriel E. Lima","Sergio M. Silva","Eduil Nascimento","David Menotti"],"published":"2026-08-31T17:12:59Z","updated":"2026-08-31T17:12:59Z","abstract_url":"https://arxiv.org/abs/2608.31107v1","html_url":"https://arxiv.org/html/2608.31107v1","pdf_url":"https://arxiv.org/pdf/2608.31107v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":34861,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：The advent of foundation models have enabled a new era in zero-shot classification. Yet, key challenges persist. Despite their impressive generalization power that leverages the immense pre-training knowledge, both foundation models for image and text as well...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:31+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.31106v1","title":"DreamX-Creator: Democratizing Native Audio-Video Generation at 2K Resolution","abstract":"Recent video generators often omit audio or synthesize it in a separate stage, limiting reciprocal modeling of visual dynamics and acoustic events. We present DreamX-Creator 1.0, a compact native joint audio-video generation system centered on a 7B generator. Conditioned on a first frame and a text prompt, the generator jointly denoises modality-specialized audio and video streams. The streams are processed independently in the first half of the network and coupled in the latter half through Gated Cross-Modal Attention, whose token- and head-wise output gates modulate each active cross-modal attention-head output. A unified Audio-Video Data System constructs and filters temporally coherent clips, produces structured multimodal annotations, and organizes clips into capability-oriented data pools. Progressive Joint Training comprises two audio-video pre-training stages followed by High-Quality Finetuning. Audio-Video Reinforcement Learning further post-trains the generator with Modality-Aware Multimodal Feedback that routes video-, audio-, and cross-modal feedback to the corresponding streams. For high-resolution output, our Autoregressive 1-Step 2K Refinement pipeline adapts a bidirectional multi-step teacher into an autoregressive multi-step refiner and distills it into a student requiring one denoising evaluation per temporal chunk. Overall, DreamX-Creator 1.0 achieves native, synchronized audio-video generation with performance competitive with state-of-the-art open-source systems. By releasing our compact 7B generator and 2K Refiner, we seek to democratize native audio-video generation and provide an accessible foundation for future research in unified audio-video generative modeling.","authors":["Jiashu Zhu","Yanhao Zheng","Ruitian Tian","Rujing Dang","Shen Zhang","Bingze Song","Jiachen Lei","Ruimin Lin","Jiahong Wu","Xiangxiang Chu"],"published":"2026-08-31T17:11:05Z","updated":"2026-08-31T17:11:05Z","abstract_url":"https://arxiv.org/abs/2608.31106v1","html_url":"https://arxiv.org/html/2608.31106v1","pdf_url":"https://arxiv.org/pdf/2608.31106v1.pdf","matched_keywords":["video","multimodal"],"source_used":"html","source_text_chars":85869,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, multimodal 相关；摘要显示其主要贡献为：Recent video generators often omit audio or synthesize it in a separate stage, limiting reciprocal modeling of visual dynamics and acoustic events. We present DreamX-Creator 1.0, a compact native joint audio-video generation system centered on a 7B generator....","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:31+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.31096v1","title":"One Adapter, Many Tasks: Task-Conditioned Feature Transformations for Continual Learning","abstract":"Class-incremental learning (CIL) requires a model to incrementally learn tasks that contain new classes without accessing earlier training data while preserving the ability to recognize all seen classes. Recently, pretrained-model-based approaches have become prevalent by adapting a frozen backbone with additional lightweight trainable modules. Existing methods, however, exhibit limitations: task-specific adapters learn explicit per-task representations but are parameter- and computation-inefficient, while LoRA-based merging methods combine per-task LoRA parameters into a single model whose static aggregated weights cause representation interference during inference. To address these problems, we present \\textbf{FACET}: task-conditioned \\textbf{F}e\\textbf{A}ture transformation with \\textbf{C}ondition\\textbf{E}d feature consis\\textbf{T}ency, achieving excellent parameter efficiency while producing highly discriminative features during inference. When continually trained on a task sequence, FACET learns a single shared adapter that employs a dynamic task-conditioned feature transformation, shaping the overall feature distribution of the adapter into a mixture of overlap-reduced task-specific components. On the other hand, we propose an efficient replay-free task-conditioned feature consistency loss, aiming to mitigate catastrophic forgetting of the learned mixture distribution in the adapter's feature space. Even when maintaining only a single adapter, FACET demonstrates robust scalability. On both very long task sequences (e.g., 200 tasks) and standard short task sequences (e.g., 20 tasks), our method achieves superior performance while using significantly fewer trainable parameters and GFLOPs. The code will be made open source upon acceptance.","authors":["Yunxiang Fu","Meng Lou","Yizhou Yu"],"published":"2026-08-31T17:03:45Z","updated":"2026-08-31T17:03:45Z","abstract_url":"https://arxiv.org/abs/2608.31096v1","html_url":"https://arxiv.org/html/2608.31096v1","pdf_url":"https://arxiv.org/pdf/2608.31096v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":74787,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：Class-incremental learning (CIL) requires a model to incrementally learn tasks that contain new classes without accessing earlier training data while preserving the ability to recognize all seen classes. Recently, pretrained-model-based approaches have become...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:31+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.31094v1","title":"Robust retinal biometrics for patient identity verification and retrieval across age and imaging devices","abstract":"Patient identity errors can compromise longitudinal medical records, research databases, and downstream clinical decisions. We present a retinal biometric system for verifying claimed identities and retrieving the correct identity from color fundus images. We trained a 512-dimensional metric-learning encoder combining a ConvNeXtV2 backbone with ArcFace and triplet losses on 227,004 images from 21,851 patient-eye identities in the Rotterdam Study, spanning multiple imaging devices and up to 32.6 years of follow-up. The system was evaluated on held-out Rotterdam Study data and externally on the UK Biobank and Age-Related Eye Disease Study (AREDS). Before evaluation, we used the model to screen for identity inconsistencies and manually adjudicated flagged images, identifying incorrect assignments in 0.588% of Rotterdam Study images, 0.259% of UK Biobank images, and 0.164% of AREDS images. In retrospective-only verification after removing near-duplicate images, the system achieved AUROCs of 0.9998, 0.9997, and 0.9998 in the Rotterdam Study, UK Biobank, and AREDS, respectively. For identity retrieval using only previously acquired images, Recall@1 was 99.7%, 97.2%, and 97.6%, respectively, from galleries averaging 4436-8510 identities; the correct identity appeared among the top five results in at least 98.6% of cases. Performance remained robust across imaging devices and long follow-up intervals, while lower image quality and inconsistent retinal fields accounted for most failures. These findings establish retinal anatomy as a durable biometric signal, useful for safeguarding the integrity of longitudinal imaging records.","authors":["Jose D. Vargas-Quiros","Dennis Bontempi","Jeroen Vermeulen","Bart Liefers","Sven Bergmann","Caroline C. W. Klaver"],"published":"2026-08-31T17:02:39Z","updated":"2026-08-31T17:02:39Z","abstract_url":"https://arxiv.org/abs/2608.31094v1","html_url":"https://arxiv.org/html/2608.31094v1","pdf_url":"https://arxiv.org/pdf/2608.31094v1.pdf","matched_keywords":["retrieval"],"source_used":"abstract","source_text_chars":1752,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 retrieval 相关；摘要显示其主要贡献为：Patient identity errors can compromise longitudinal medical records, research databases, and downstream clinical decisions. We present a retinal biometric system for verifying claimed identities and retrieving the correct identity from color fundus images. We...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"abstract","created_at":"2026-09-01T05:58:31+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.31074v1","title":"Real-Time Video Anomaly Detection Using YOLO Pose Estimation and CLIP-Based Semantic Scoring","abstract":"We propose a lightweight two-stage framework for real-time video anomaly detection. The first stage employs YOLO v11n-pose to detect persons and extract seventeen skeletal keypoints in a single forward pass. The second stage encodes each cropped person region through CLIP ViT-B/32 and computes cosine similarity against predefined textual descriptions of anomalous behaviors. This architecture eliminates the need for optical flow, standalone pose estimators, and density-based scoring modules. Experiments on CUHK Avenue, ShanghaiTech Campus, and a custom indoor dataset collected at Chulalongkorn University demonstrate an end-to-end throughput of approximately 51 FPS on an NVIDIA Titan XP GPU, a 3.36x speedup over the multi-feature baseline, while maintaining frame-level AUROC values of 89.26%, 70.26%, and 84.13%, respectively.","authors":["Vanodhya G. Warnasooriya","Amir Hajian","Watchara Ruangsang","Supavadee Aramvith"],"published":"2026-08-31T16:47:29Z","updated":"2026-08-31T16:47:29Z","abstract_url":"https://arxiv.org/abs/2608.31074v1","html_url":"https://arxiv.org/html/2608.31074v1","pdf_url":"https://arxiv.org/pdf/2608.31074v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":26069,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：We propose a lightweight two-stage framework for real-time video anomaly detection. The first stage employs YOLO v11n-pose to detect persons and extract seventeen skeletal keypoints in a single forward pass. The second stage encodes each cropped person region...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:31+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.31065v1","title":"Multimodal Shared Latent Representation of Narration, Microscope and iOCT Images for Phase Recognition in Vitreoretinal Surgery","abstract":"Surgical phase recognition is key to context-aware computer-assisted feedback in vitreoretinal procedures, yet the scarcity of synchronized multimodal intraoperative data, particularly microscope views and intraoperative OCT, limits approaches that aim to replicate the multimodal integration surgeons perform naturally. Surgical narration, by contrast, is abundantly available online and offers rich semantic supervision. Prior work has mainly explored pairwise contrastive learning (e.g., intraoperative OCT-microscope or microscope-narration), leaving the joint modeling of all three modalities largely unexplored. We introduce a framework that uses microscope views as a shared anchor to bridge surgical narrations and intraoperative OCT (iOCT) without requiring a fully synchronized tri-modal dataset, leveraging real microscope-narration videos and a synthetic dataset of synchronized microscope video and tool-aligned iOCT pairs. Contrastive alignment transfers structural priors from the synthetic domain to real videos lacking iOCT, and a dual-head MS-TCN++ integrates the resulting embeddings for joint macro- and micro-phase prediction. Evaluated on real vitreoretinal surgeries, our framework improves macro-phase recognition over a zero-shot baseline (mean F1 0.38 to 0.53) and provides an exploratory route to estimating fine-grained instrument-tissue measurements that are not directly observable in real microscope video alone; these micro-phase estimates are validated quantitatively on synthetic data and shown only qualitatively on real surgery. To our knowledge, this is the first work to unify microscope view, iOCT B-scans, and surgical narrations in a shared latent space for surgical phase recognition.","authors":["Onur Izmitlioglu","Shervin Dehghani","Tarek Ghannoum","Benedikt Schworm","Nassir Navab"],"published":"2026-08-31T16:41:07Z","updated":"2026-08-31T16:41:07Z","abstract_url":"https://arxiv.org/abs/2608.31065v1","html_url":"https://arxiv.org/html/2608.31065v1","pdf_url":"https://arxiv.org/pdf/2608.31065v1.pdf","matched_keywords":["video","representation","multimodal"],"source_used":"html","source_text_chars":34775,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, representation, multimodal 相关；摘要显示其主要贡献为：Surgical phase recognition is key to context-aware computer-assisted feedback in vitreoretinal procedures, yet the scarcity of synchronized multimodal intraoperative data, particularly microscope views and intraoperative OCT, limits approaches that aim to rep...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:31+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.31053v1","title":"Identity-Conditioned Latent Consistency Distillation for Face Synthesis","abstract":"Diffusion models have achieved strong results in high-fidelity image synthesis, but their iterative sampling process makes large-scale generation computationally expensive. This limitation is especially relevant when generating synthetic face datasets for face recognition, where a large number of subjects with many samples in different poses, expressions, ages, etc., are required. In this work, we show that identity-conditioned face synthesis can be performed at a substantially lower computational cost by a latent Consistency Model with few iterations, without compromising image quality. For training, we distill knowledge from the foundation Diffusion Model Arc2Face (teacher) by adapting its original text-to-image pipeline to an embedding-to-face setting, replacing textual prompts with ArcFace identity embeddings. Our distilled model (student) generates identity-conditioned face images with an average inference time of 0.4819 seconds per image, compared with 2.102 seconds for Arc2Face, resulting in a 4.36$\\times$ speed-up. Quantitative results, based on FID scores, show that the distilled model remains competitive with Arc2Face across all evaluation protocols. On 100k generated images, it achieves near-parity on CelebA (13.921 vs. 12.928) and outperforms the teacher on WebFace42M (9.317 vs. 9.802). Further evaluations on Synth-500 and AgeDB show a moderate performance gap for the former but comparable results for the latter. These results indicate that Arc2Face can be accelerated through task-specific latent consistency distillation while preserving high image quality for large-scale synthetic face generation. Our proposal is publicly available at https://github.com/UFPR-IPASP-PR/FaceRec-IdentityConsistency.","authors":["Tiago Kienen Chaves","Bernardo Biesseck","David Menotti"],"published":"2026-08-31T16:32:40Z","updated":"2026-08-31T16:32:40Z","abstract_url":"https://arxiv.org/abs/2608.31053v1","html_url":"https://arxiv.org/html/2608.31053v1","pdf_url":"https://arxiv.org/pdf/2608.31053v1.pdf","matched_keywords":["diffusion"],"source_used":"html","source_text_chars":37566,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 diffusion 相关；摘要显示其主要贡献为：Diffusion models have achieved strong results in high-fidelity image synthesis, but their iterative sampling process makes large-scale generation computationally expensive. This limitation is especially relevant when generating synthetic face datasets for fac...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:31+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.31033v1","title":"FaceSnap: Real-Time Personalized Lightstage Facial Performance Capture","abstract":"Lightstage facial capture produces production-quality digital humans, but it is resource and labor-intensive. Multi-camera setups, hours of computation, and massive data storage create bottlenecks that hinder iterative workflows. This paper introduces FaceSnap, an end-to-end framework that streamlines capture via a two-stage approach. First, a one-time multi-view optimization from a range-of-motion sequence builds a personalized model encoding both geometry and expression-dependent appearance. This model then enables high-fidelity real-time facial performance capture from a single monocular lightstage camera, with no further multi-view capture required. FaceSnap jointly estimates geometry and dynamic 4K texture at 83 fps. The 4K texture is produced by a novel personalized residual upscaler that recovers subject-specific high-frequency detail, which generic upscalers fail to capture. FaceSnap achieves geometric accuracy competitive with full per-frame multi-view optimization while outperforming feed-forward methods trained on production-quality 3D data, all from a single camera view. Finally, we introduce Multi4D, a public benchmark for evaluating 4D facial reconstruction methods in lightstage environments, enabling topology-invariant geometric comparison across methods.","authors":["Rukhshanda Hussain","Noé Artru","Emeline Got","Luiz Gustavo Hafemann","Alexandre Messier","Brandon Dearlove","Rafael M. O. Cruz","Abdallah Dib","Eric Granger"],"published":"2026-08-31T16:14:21Z","updated":"2026-08-31T16:14:21Z","abstract_url":"https://arxiv.org/abs/2608.31033v1","html_url":"https://arxiv.org/html/2608.31033v1","pdf_url":"https://arxiv.org/pdf/2608.31033v1.pdf","matched_keywords":["3d"],"source_used":"html","source_text_chars":78045,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d 相关；摘要显示其主要贡献为：Lightstage facial capture produces production-quality digital humans, but it is resource and labor-intensive. Multi-camera setups, hours of computation, and massive data storage create bottlenecks that hinder iterative workflows. This paper introduces FaceSna...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:31+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.31025v1","title":"Analytic Dynamics: Learning Physics-Grounded Representation for Fast Intrinsic Dynamics Inference from Monocular Videos","abstract":"Inferring object dynamics from visual observations is essential for intelligent agents to reason about and interact with the physical world, yet remains challenging due to the fundamental gap between visual evidence and intrinsic dynamics. Existing methods either rely on costly per-scene optimization, limiting efficiency and scalability, or directly map visual evidence to intrinsic dynamics without intermediate physical abstractions, making them prone to appearance and geometry shortcuts. To bridge this gap, we propose Analytic Dynamics, a feed-forward dynamics inference framework that introduces an intermediate physics-grounded dynamics representation between visual observations and intrinsic dynamics. Specifically, we leverage privileged physical states, including position, displacement, and deformation gradient fields, which are available in simulation, to learn a structured dynamics representation that is difficult to discover from visual observations alone. By aligning visual representations with this space, we equip visual models with a physics-grounded inductive bias, guiding them to capture dynamics-relevant patterns for material model classification and parameter regression. To facilitate this research, we develop a dynamics data generation pipeline and benchmark containing paired physical state trajectories, rendered videos, and ground-truth material models and parameters. Extensive experiments demonstrate that Analytic Dynamics achieves efficient, accurate, and generalizable dynamics inference from monocular videos.","authors":["Jailing Lin","Jikuan Zhang","Jianhua Sun"],"published":"2026-08-31T16:08:04Z","updated":"2026-08-31T16:08:04Z","abstract_url":"https://arxiv.org/abs/2608.31025v1","html_url":"https://arxiv.org/html/2608.31025v1","pdf_url":"https://arxiv.org/pdf/2608.31025v1.pdf","matched_keywords":["video","agent","representation"],"source_used":"html","source_text_chars":78137,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, agent, representation 相关；摘要显示其主要贡献为：Inferring object dynamics from visual observations is essential for intelligent agents to reason about and interact with the physical world, yet remains challenging due to the fundamental gap between visual evidence and intrinsic dynamics. Existing methods ei...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:31+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.31023v1","title":"SMG: Semantic Motion Graph for Monocular Dynamic Gaussian Splatting","abstract":"We study dynamic Gaussian Splatting from monocular videos. While recent advancements in dynamic Gaussian splatting offer a promising foundation for modeling dynamic scenes, they often overfit to the training views and fail under occlusion or complex scene motion due to the lack of reliable regularization signals in under-constrained regions. We propose Semantic Motion Graph (SMG), a novel approach models the Gaussian motion as the low-rank semantic motion. Our key insight is that the real-world scene motion is often structured by semantic coherence: regions that are spatially close and semantically related tend to exhibit consistent dynamics. To leverage this prior, we construct SMG to model structured motion of the scene. The Gaussian motion is driven by the motion of SMG nodes. We further observe that the uncertainty of Gaussian motion arises from both unreliable off-the-shelf priors and weakly constrained regions during optimization. SMG addresses this by using reliable graph nodes to guide the motion of nearby unreliable nodes. To evaluate dynamic Gaussian splatting under challenging real-world scenarios, we introduce a new multiview dataset collected under an ego-exo setup. Extensive experiments demonstrate that SMG achieves state-of-the-art performance on monocular dynamic Gaussian splatting across challenging real-world benchmarks. Project page: https://smg-gaussian.github.io/.","authors":["Haozheng Yu","Xinyu Yang","Rundong Luo","Jennifer J. Sun","Bharath Hariharan"],"published":"2026-08-31T16:06:18Z","updated":"2026-08-31T16:06:18Z","abstract_url":"https://arxiv.org/abs/2608.31023v1","html_url":"https://arxiv.org/html/2608.31023v1","pdf_url":"https://arxiv.org/pdf/2608.31023v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":61466,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：We study dynamic Gaussian Splatting from monocular videos. While recent advancements in dynamic Gaussian splatting offer a promising foundation for modeling dynamic scenes, they often overfit to the training views and fail under occlusion or complex scene mot...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:31+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.31022v1","title":"MNIST-PRO: MNIST is Back as a Partially Observable World for AI Agents","abstract":"AI agents in partially observable environments need to coordinate active sensing with working memory to maintain an evolving perceptual state. However, existing benchmarks struggle to isolate this perceptual-state construction and interpretation capability because they introduce physical and control complexities. We address this with MNIST-PRO, a benchmark that isolates agentic perception by converting MNIST digit recognition into a sequential, glimpse-based search task with lookback constraints. We evaluate ten multimodal models across four memory representations, including raw visual history, textual states, structured metric grid maps, and a consolidated visual canvas. While models excel under full observability, partial observability exposes a clear performance gap. We identify three distinct bottlenecks. First, perceptual-state construction and interpretation present a challenge, as agents struggle to integrate fragmented glimpses. Second, agents often stop exploring before they see the full sequence. Third, models often fail to revise early, incorrect beliefs even when faced with subsequent contradictory evidence. These results show that simply acquiring visual evidence is not enough. Agents must also be able to build and update a reliable perceptual state.","authors":["Vernon Toh","Navonil Majumder","Zhengyuan Liu","Nancy F. Chen","Soujanya Poria"],"published":"2026-08-31T16:05:39Z","updated":"2026-08-31T16:05:39Z","abstract_url":"https://arxiv.org/abs/2608.31022v1","html_url":"https://arxiv.org/html/2608.31022v1","pdf_url":"https://arxiv.org/pdf/2608.31022v1.pdf","matched_keywords":["agent","representation","multimodal"],"source_used":"html","source_text_chars":102541,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 agent, representation, multimodal 相关；摘要显示其主要贡献为：AI agents in partially observable environments need to coordinate active sensing with working memory to maintain an evolving perceptual state. However, existing benchmarks struggle to isolate this perceptual-state construction and interpretation capability be...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:31+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.31013v1","title":"TSPFN: A Temporal Tabular Foundation Model for Physiological Time Series Classification","abstract":"Designing models that generalize effectively in low- to medium-data regimes remains a primary challenge in medical machine learning, particularly for physiological time-series classification. While tabular foundation models such as TabPFN offer an attractive alternative to conventional fine-tuning through in-context learning, they are not designed to capture the temporal dependencies inherent to physiological signals. ~In this paper, we introduce TSPFN, a foundation model that redesigns TabPFN's architecture for time series data. TSPFN integrates structured temporal representations and positional embeddings to capture intra-sample temporal and channel dependencies. To fully leverage its spatio-temporal design, the model is pretrained on 140,000 real-world physiological time series across multiple medical domains. This yields a unified, generalizable framework capable of learning the specificities of medical time series. Experiments across diverse physiological benchmarks demonstrate that TSPFN consistently outperforms standard tabular baselines and TabPFN, and achieves superior cross-domain generalization compared to specialized deep time-series models. All our experiments, ablation studies, and pre-processing scheme are publicly available at https://github.com/Jeremstym/TSPFN","authors":["Jérémie Stym-Popper","Clément Rambour","Federica Granese","Nicolas Thome","Olivier Bernard"],"published":"2026-08-31T15:58:22Z","updated":"2026-08-31T15:58:22Z","abstract_url":"https://arxiv.org/abs/2608.31013v1","html_url":"https://arxiv.org/html/2608.31013v1","pdf_url":"https://arxiv.org/pdf/2608.31013v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":37053,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：Designing models that generalize effectively in low- to medium-data regimes remains a primary challenge in medical machine learning, particularly for physiological time-series classification. While tabular foundation models such as TabPFN offer an attractive...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:32+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.31005v1","title":"From Intent to Evidence: Policy-Steered Multi-Strategy Retrieval for Long-Video Agents","abstract":"Existing long-video agents acquire evidence through one uniform behavior, ignoring whether the required evidence is concentrated, requires broad occurrence coverage, or must discriminate competing hypotheses---which can cause failure before substantive reasoning begins. Prescribing a fine-grained solution procedure for every question is not a satisfactory remedy, as it restricts autonomous exploration. We propose VESTA, a training-free long-video agent organized as a route-conditioned acquire--verify--consolidate loop. Before exploration, an intent router infers an evidence-acquisition policy---focused, recall, or contrastive retrieval over a shared visual--speech scene index---together with an evidence-accounting policy that configures the evidence view maintained during exploration. Policy-steered retrieval yields provisional references that multimodal evidence operations convert into observations, while the Reasoner remains free to verify them, re-query using intermediate findings, or inspect regions outside the retrieved set. A temporal evidence ledger consolidates observations into an adaptive, compressed view of temporal location, provenance, coverage, conflicts, verification outcomes, and hypothesis support, exposing missing and unresolved evidence to guide subsequent acquisition; finalization prioritizes verified observations. On Video-MME-v2, VESTA improves average accuracy by 2.7 points over VideoARM and gains across all six reported metrics. On LongVideoBench, EgoSchema, and LVBench under shared query-time models, it improves by 6.9 points on the LongVideoBench long subset and 1.5 on LVBench, and matches VideoARM on EgoSchema.","authors":["Can Zhang","Baofeng Zhang","Xiaotian Han","Junyuan Shang","Yuchen Ding","Shuohuan Wang","Dianhai Yu","Ruirui Li"],"published":"2026-08-31T15:55:48Z","updated":"2026-08-31T15:55:48Z","abstract_url":"https://arxiv.org/abs/2608.31005v1","html_url":"https://arxiv.org/html/2608.31005v1","pdf_url":"https://arxiv.org/pdf/2608.31005v1.pdf","matched_keywords":["video","retrieval","agent","multimodal"],"source_used":"html","source_text_chars":78847,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, retrieval, agent, multimodal 相关；摘要显示其主要贡献为：Existing long-video agents acquire evidence through one uniform behavior, ignoring whether the required evidence is concentrated, requires broad occurrence coverage, or must discriminate competing hypotheses---which can cause failure before substantive reason...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:32+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.31002v1","title":"DARP: A Calibrated Dual-Arm RGB-D-IR Dataset for Multi-View Robotic Perception","abstract":"Robotic perception from a single viewpoint is often limited by self-occlusion and incomplete surface visibility. This paper presents DARP(Dual-Arm Robotic Perception) https://doi.org/10.21227/rmv3-be47, a calibrated dual-arm RGB-D-IR dataset for object-centered robotic perception using two independently moving eye-in-hand manipulators positioned on opposite sides of a shared tabletop workspace. Each arm carries an Intel RealSense sensor that continuously records RGB, depth, and stereo infrared data while synchronized robot joint states are logged for pose recovery. Objects are placed without fixed poses or marked locations, and the acquisition procedure performs automatic localization, cross-arm confirmation, adaptive viewpoint generation, and continuous multimodal recording. DARP contains ten unique tabletop objects and preserves the original sensor recordings, robot-state logs, object-level metadata, and calibration information required to reconstruct camera trajectories in a shared metric frame. To evaluate the geometric consistency of the acquisition, we implement a deterministic multi-view fusion pipeline that converts calibrated RGB-D observations into complementary partial point clouds and measured surface meshes without using learned or generative completion methods. Evaluation on 224 held-out RGB-D keyframes comprising 1,563,466 three-dimensional query points yields a median point-to-mesh distance of 2.13~mm and an RMSE of 4.04~mm, with 96.56\\% of points within 10~mm of the measured-surface mesh. DARP is intended as a reusable resource for multi-view reconstruction, collaborative robotic perception, multimodal fusion, active perception, and future learning-based reasoning over partial object observations.","authors":["Manish Kansana","Mohammed Yusuf Mujawar","Sudip Mittal","Shahram Rahimi","Noorbakhsh Amiri Golilarz"],"published":"2026-08-31T15:53:41Z","updated":"2026-08-31T15:53:41Z","abstract_url":"https://arxiv.org/abs/2608.31002v1","html_url":"https://arxiv.org/html/2608.31002v1","pdf_url":"https://arxiv.org/pdf/2608.31002v1.pdf","matched_keywords":["multimodal"],"source_used":"html","source_text_chars":50256,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 multimodal 相关；摘要显示其主要贡献为：Robotic perception from a single viewpoint is often limited by self-occlusion and incomplete surface visibility. This paper presents DARP(Dual-Arm Robotic Perception) https://doi.org/10.21227/rmv3-be47, a calibrated dual-arm RGB-D-IR dataset for object-center...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:32+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30975v1","title":"MR-JEPA: A General Purpose Video Foundation Model for Cardiac MRI","abstract":"Cardiac magnetic resonance imaging (CMR) produces rich sequential data such as temporal cine videos and spatial LGE/mapping stacks, yet most deep learning approaches process individual 2D slices, discarding this context. We present MR-JEPA, a self-supervised video foundation model for CMR that extends LeJEPA to 3D spatiotemporal inputs through tubelet tokenization, spatiotemporal masking augmentation, and initialization from a 2D CMR foundation model. Unlike prior CMR video models limited to cine data, MR-JEPA is pretrained on multi-sequence data (cine, LGE, mapping) from 10,505 patients across two centers without annotations. We evaluate the frozen encoder on six downstream tasks using a unified multi-view gated attention architecture: LV ejection fraction, RV ejection fraction, three myocardial strains (GLS, GCS, GRS), and four-class disease detection. MR-JEPA outperforms other compared methods on all five regression tasks, including both a domain-specific CMR model pretrained on more data with text supervision and a natural-video foundation model, achieving an LV EF MAE of 4.79% (r =0.764) and a GLS MAE of 1.87 (r=0.805), with 21-27% MAE reductions over baselines on strain tasks. For disease detection, MR-JEPA achieved a macro AUG of 0.868, remaining competitive with the domain-specific baseline despite using a fully self-supervised pretraining objective. These results demonstrate the potential of a unified video encoder for robust, multi-view utilization of diverse CMR sequences in clinical cardiac quantification and diagnosis.","authors":["Athira J. Jacob","Puneet Sharma","Dorin Comaniciu","Daniel Rueckert"],"published":"2026-08-31T15:36:24Z","updated":"2026-08-31T15:36:24Z","abstract_url":"https://arxiv.org/abs/2608.30975v1","html_url":"https://arxiv.org/html/2608.30975v1","pdf_url":"https://arxiv.org/pdf/2608.30975v1.pdf","matched_keywords":["video","3d"],"source_used":"abstract","source_text_chars":1624,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d 相关；摘要显示其主要贡献为：Cardiac magnetic resonance imaging (CMR) produces rich sequential data such as temporal cine videos and spatial LGE/mapping stacks, yet most deep learning approaches process individual 2D slices, discarding this context. We present MR-JEPA, a self-supervised...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"abstract","created_at":"2026-09-01T05:58:32+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30964v1","title":"Vision Models Predict Urban Scene Appraisal with Limited Neural Alignment","abstract":"Pretrained vision embeddings are increasingly used as general-purpose representations for modelling how people appraise urban scenes, and are validated almost entirely by how well they predict human ratings. High predictive accuracy does not establish that these embeddings organise scenes as human perception does. We test the two properties separately against brain data. Using openly released EEG from 63 adults who viewed and rated 56 Berlin street scenes, we estimate the representational geometry of the scenes over time, the proportion of that geometry that is explainable at all, and its correspondence with seventeen feature spaces spanning language-supervised, self-supervised, category-supervised and dense-prediction training, two orders of magnitude of scale, and interpretable controls. Correspondence is low throughout: the best representation, DINOv2 ViT-B, reaches 29.6% of the lower bound of the noise ceiling, the panel spans 11.0% to 29.6%, and a Gabor energy descriptor is indistinguishable from the best model while outperforming every language-supervised model tested. Within a model, deeper layers still match later neural responses, so the hierarchical correspondence found for object recognition survives even at this low overall level. The same embeddings predict held-out appraisal ratings well, up to r = 0.87, and the two measures do not track each other across models; reweighting features towards the neural geometry lowers appraisal prediction for every model tested, against a control of matched dimensionality. Predicting how a street is appraised is therefore weak evidence that a model represents the street as the brain does. The benchmark uses only public data and requires no training, so evaluating a new representation needs only its embeddings for 55 images.","authors":["Kaizhen Tan","Yuantao Deng"],"published":"2026-08-31T15:28:39Z","updated":"2026-08-31T15:28:39Z","abstract_url":"https://arxiv.org/abs/2608.30964v1","html_url":"https://arxiv.org/html/2608.30964v1","pdf_url":"https://arxiv.org/pdf/2608.30964v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":61727,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：Pretrained vision embeddings are increasingly used as general-purpose representations for modelling how people appraise urban scenes, and are validated almost entirely by how well they predict human ratings. High predictive accuracy does not establish that th...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:32+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30959v1","title":"LOCI: A Locator-Critic with Refinement Loop","abstract":"Vision-Language Models (VLMs) still struggle on tasks requiring complex visual understanding. We argue that the core issue is not high-level reasoning, but instead failing to locate critical details in the image. Due to this shortcoming, VLMs generate often plausible but incorrect reasoning based on flawed perceptual grounding. To address this, we propose Locator-Critic (LOCI), a training-free framework that decouples visual search from evidence verification. LOCI employs a Locator agent to propose candidate visual evidence and a separate Critic agent to evaluate its relevance and sufficiency. These agents engage in an iterative refinement loop, progressively improving the evidence until it is adequate to answer the given question. This decoupled, self-correcting process yields substantial performance gains, achieving state-of-the-art results on multiple complex visual benchmarks. LOCI improves accuracy for both open-weight models like Qwen3-VL (+12.1 on V*, +5.8 on HR-Bench and +11.2 on VisualProbe-Hard) and proprietary models like Gemini 2.5 Pro (+8.9 on V*, +4.3 on HR-Bench, +4.8 on VisualProbe-Hard).","authors":["Walid Bousselham","Mathilde Caron","Arsha Nagrani","Cordelia Schmid"],"published":"2026-08-31T15:26:00Z","updated":"2026-08-31T15:26:00Z","abstract_url":"https://arxiv.org/abs/2608.30959v1","html_url":"https://arxiv.org/html/2608.30959v1","pdf_url":"https://arxiv.org/pdf/2608.30959v1.pdf","matched_keywords":["agent"],"source_used":"html","source_text_chars":82084,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 agent 相关；摘要显示其主要贡献为：Vision-Language Models (VLMs) still struggle on tasks requiring complex visual understanding. We argue that the core issue is not high-level reasoning, but instead failing to locate critical details in the image. Due to this shortcoming, VLMs generate often p...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:32+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30951v1","title":"Audio-Driven Adversarial Defense for 3D Talking Face Generation with totally Visual Fidelity Preservation","abstract":"The rapid development of generative portrait models has raised growing concerns about privacy leakage and identity misuse. In particular, audio-driven 3D talking face generation can reconstruct a reusable 3D portrait of a target person from a monocular video and animate it with arbitrary speech, making realistic identity impersonation alarmingly practical. Existing proactive defenses mainly operate in the visual domain by injecting subtle perturbations into acial regions to disrupt identity acquisition. However, such perturbations often compromise visual quality due to the strong structural priors and social sensitivity of human faces, and are easily weakened by common real-world transformations such as resizing. To overcome these limitations, we propose an imperceptible audio defense for audio-driven 3D talking face generation by shifting protection from the visual modality to the audio modality. Specifically,we exploit psychoacoustic masking to hide protective perturbations within perceptually masked frequency regions of the speech signal, thereby reducing perceptual distortion while suppressing reliable facial animation. Extensive experiments demonstrate that the proposed method effectively degrades 3D talking face generation while preserving favorable perceptual quality. These findings highlight psychoacoustically guided audio perturbations as a practical and promising direction for privacy-preserving portrait protection.","authors":["Rui-Qing Sun","Chen-Hao Cui","Hui-Yang Zhao","Tian Lan","Zhijing Wu","Xian-Ling Mao"],"published":"2026-08-31T15:22:05Z","updated":"2026-08-31T15:22:05Z","abstract_url":"https://arxiv.org/abs/2608.30951v1","html_url":"https://arxiv.org/html/2608.30951v1","pdf_url":"https://arxiv.org/pdf/2608.30951v1.pdf","matched_keywords":["video","3d"],"source_used":"html","source_text_chars":57381,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d 相关；摘要显示其主要贡献为：The rapid development of generative portrait models has raised growing concerns about privacy leakage and identity misuse. In particular, audio-driven 3D talking face generation can reconstruct a reusable 3D portrait of a target person from a monocular video...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:32+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30899v1","title":"Uncertainty-Aware Trajectory Forecasting from Imperfect Tracking","abstract":"Most trajectory forecasting models are trained on clean annotated histories, and are often evaluated under the same idealized assumption, although practical deployments rely on trajectories produced by imperfect multi-object trackers. The real-world observations exhibit localization jitter, missed or unstable detections, and data-association ambiguity, which are usually either ignored or removed through denoising. This paper instead treats tracking-derived reliability cues as an informative signal to be propagated to the predictor. We propose a plug-in uncertainty-aware formulation in which each observed state is encoded as an uncertain state representation, modeled by a Gaussian distribution whose covariance combines detection-level localization uncertainty and association-level ambiguity through the law of total variance. Existing backbones are adapted with minimal architectural changes: input trajectories are represented as Gaussian observations, and predicted trajectories are produced as Gaussian forecasts rather than deterministic coordinates. To train predictors that remain robust under structured observation noise, we combine temporally correlated Ornstein-Uhlenbeck perturbations with response-based knowledge distillation from a teacher trained on clean trajectories. Experiments on Oxford Town Centre and VIRAT using real tracker outputs, together with a complementary ETH/UCY pseudo-detection protocol, show that the proposed formulation improves displacement accuracy and the reliability-sharpness trade-off of probabilistic forecasts.","authors":["Stephane Da Silva Martins","Victor Petrovic","Emanuel Aldea","Sylvie Le Hégarat-Mascle"],"published":"2026-08-31T14:50:38Z","updated":"2026-08-31T14:50:38Z","abstract_url":"https://arxiv.org/abs/2608.30899v1","html_url":"https://arxiv.org/html/2608.30899v1","pdf_url":"https://arxiv.org/pdf/2608.30899v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30872v1","title":"SurgSkill-Bench: A Benchmark for Multimodal Surgical Skill Assessment","abstract":"Objective assessment of surgical technical skill is important for surgical training and structured feedback, but current workflows remain dependent on labor-intensive expert review. Existing automated approaches primarily focus on visual inputs and provide limited support for jointly studying operative performance, structured skill scores, and evaluator feedback. We introduce SurgSkill-Bench, an initial video-score-text benchmark-style dataset containing 214 surgical training simulation videos, six-dimensional OSATS scores, and expert free-text comments. We define two evaluation settings: video-only OSATS prediction for automated assessment and post hoc expert-comment-assisted prediction, where evaluator comments are available as auxiliary information. We provide controlled baseline experiments using representative frozen visual backbones, content-adaptive key-frame sampling, and a simple video-text co-attention fusion module. Under internal video-level validation, content-adaptive sampling improves video-only performance in this dataset, while evaluator comments provide additional score-related signal in the assisted setting. The best mean AUROC reaches 0.88 under dataset-specific median dichotomization. We further discuss evaluation constraints related to dataset scale, metadata completeness, and the interpretation of comment-assisted prediction. Code will be released publicly at a later date.","authors":["Chaohui Dang","Zheheng Jiang","James Glasbey","David Luke","Theodoros Arvanitis","Le Zhang"],"published":"2026-08-31T14:32:45Z","updated":"2026-08-31T14:32:45Z","abstract_url":"https://arxiv.org/abs/2608.30872v1","html_url":"https://arxiv.org/html/2608.30872v1","pdf_url":"https://arxiv.org/pdf/2608.30872v1.pdf","matched_keywords":["video","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30870v1","title":"VCAR: Training-Free 3DGS Segmentation via View Completeness and Axis-Aware Boundary Refinement","abstract":"Semantic segmentation in 3D Gaussian Splatting (3DGS) is crucial for advancing 3D scene understanding. Existing methods predominantly rely on feature distillation, which incurs substantial per-scene training overhead and often yields blurred segmentation boundaries. We identify that these boundary artifacts are driven in part by insufficient viewpoint coverage and boundary overflow of anisotropic Gaussian primitives. To address these challenges, we propose VCAR, a training-free coarse-to-fine segmentation strategy based on View Completeness and Axis-aware Boundary Refinement. In the coarse stage, a visibility-based weighted multi-view voting scheme rapidly localizes the target. In the fine stage, an object-centric sphere derived from the coarse result generates supplementary viewpoints via Spherical Spiral Sampling (SSS), allowing multi-view voting on the augmented views to precisely refine object boundaries and suppress irrelevant 3D Gaussians. Moreover, we introduce Axis-aware Boundary Refinement (ABR) to mitigate artifacts from anisotropic primitives. By decomposing the projected 2D covariance into per-axis contributions, ABR identifies the dominant axis responsible for boundary leakage and applies targeted anisotropic compression exclusively along that axis. Extensive experiments on NVOS and LERF demonstrate that VCAR achieves state-of-the-art segmentation accuracy and efficiency without training. Our code is available at https://github.com/DDKK0526/VCAR.","authors":["Kun Cao","Di Wang","Haibin Zhu","Haozhi Huang","Xu Wang","Zheng Shi","Guanghua Yang"],"published":"2026-08-31T14:32:26Z","updated":"2026-08-31T14:32:26Z","abstract_url":"https://arxiv.org/abs/2608.30870v1","html_url":"https://arxiv.org/html/2608.30870v1","pdf_url":"https://arxiv.org/pdf/2608.30870v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30858v1","title":"GAFT: Geo-Anchored Fine-Tuning for Hazard Identification from Rare Failures","abstract":"Off-road navigation can fail when physical structures induce irrecoverable states such as high-centering or entrapment, requiring human interventions. Identifying these structures is crucial, yet challenging. Such failure events are rare and costly to collect, resulting in limited training data. Moreover, the collected data associate frames with outcomes, but do not indicate the visual cues responsible for the failure. Learning directly from these data can therefore exploit scenario-specific visual cues, leading to poor generalization. We propose \\textbf{Geo-Anchored Fine-Tuning (GAFT)}, a parameter-efficient method that adapts a vision foundation model with a geometry-derived prior. It guides LoRA adaptation by aligning a spatial attention-rollout map with the geometry prior, while preserving pretrained representations. On an intervention-verified forest hazard benchmark, across ten independently trained adaptations, GAFT consistently outperforms frozen DINOv2 and supervised PEFT baselines, improving the repeated leave-one-scenario-out mean $F_2$ from 0.0607 to 0.3757 with statistical significance under paired analysis. Within these independently trained models, the best-performing GAFT model achieves a repeated-LOSO $F_2$ of 0.570. Code and benchmark: https://github.com/Xu-Yanran/geo_anchored_fine_tuning","authors":["Yanran Xu","Chuanhang Qiu","Yue Wang","Wenbo Wu","Zhaoxing Li"],"published":"2026-08-31T14:20:59Z","updated":"2026-08-31T14:20:59Z","abstract_url":"https://arxiv.org/abs/2608.30858v1","html_url":"https://arxiv.org/html/2608.30858v1","pdf_url":"https://arxiv.org/pdf/2608.30858v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30857v1","title":"TAMI: Temporally Aligned, Missingness-Aware, and Interpretable Multimodal Fusion for Mental Health Assessment in Older Adults with Mild Cognitive Impairment","abstract":"Depression and anxiety in older adults with Mild Cognitive Impairment (MCI) are frequently underdiagnosed due to limited access to care. Multimodal analysis of remote clinical interviews is a scalable screening approach, but existing methods have three limitations. First, they do not correct temporal misalignment across multimodal features extracted at different resolutions, inducing spurious cross-modal associations. Second, remote recordings exhibit uneven modality dropout, but missing values are often zero-filled, making them indistinguishable from valid near-zero measurements. Finally, they do not jointly attribute predictions to modalities, questions, and interview moments, limiting fine-grained clinical interpretation. We propose a Temporally-Aligned, Missingness-Aware, Interpretable (TAMI) multimodal fusion framework. TAMI aligns speech, language, facial, and physiological features within question-answer segments on a shared timeline, encodes modality-level missingness over time, and conditions fusion on question context. In interviews with 49 older adults with MCI, TAMI achieved area under the receiver operating characteristic curve (AUROC) scores of 0.68 (depression) and 0.69 (anxiety). Fine-grained temporal alignment of multimodal features produced the largest performance gain ($Δ{\\geq}0.1$). Multi-level interpretability analysis revealed that depression classification relied on eyegaze and open-ended questions, while anxiety classification depended on eyegaze and head pose, with attribution uniformly distributed across questions. Using only responses to the open-ended questions (5.1min), the depression model achieved an AUROC score of 0.67, which was not significantly different from using the full interview (19min) ($p>0.05$). Our findings support designing interview protocols centered on open-ended questions for depression screening in older adults with MCI.","authors":["Merna Bibars","Bolaji Omofojoye","Allan I. Levey","Rachel Hershenberg","Gari D. Clifford","Hyeokhyen Kwon"],"published":"2026-08-31T14:19:32Z","updated":"2026-08-31T14:19:32Z","abstract_url":"https://arxiv.org/abs/2608.30857v1","html_url":"https://arxiv.org/html/2608.30857v1","pdf_url":"https://arxiv.org/pdf/2608.30857v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30844v1","title":"Pretrained, Curriculum-Tuned, and Ensembled: A Tracer-Aware Interactive Segmentation Pipeline for AutoPET V","abstract":"Interactive lesion segmentation in whole-body PET/CT requires a model to provide a strong initial prediction while also responding efficiently to sparse corrective scribbles during inference. This setting is particularly challenging because tracer distributions, physiological uptake patterns, lesion appearance, and acquisition characteristics differ substantially between FDG and PSMA studies. We present TRIAGE, Tracer-aware Refinement via Interactive Anatomy-Guided sEgmentation. The core backbone is a 3D STU-Net initialized through masked autoencoding pre-training with an asynchronous masking strategy, aiming to learn transferable anatomical and cross-modal representations before task-specific fine-tuning. In parallel, we train an auxiliary organ segmentation model whose predictions provide explicit anatomical context and help distinguish physiological uptake from malignant lesions. A dedicated tracer classifier first routes each study to an FDG- or PSMA-specific branch. Within each branch, a first-stage segmentation model consumes CT, PET, and organ context to generate an initial lesion mask. The initial prediction is then combined with cumulative foreground/background scribbles and refined by a second interactive segmentation network. The FDG and PSMA branches share the same overall processing pipeline but are trained independently to account for tracer-specific appearance and error modes. We additionally employ curriculum-style training and model ensembling to improve robustness across interaction steps and heterogeneous cohorts. Experiments are conducted using the official AutoPET V data and ten-fold split; quantitative results, ablations, and final test-set performance are left as placeholders to be completed after the challenge evaluation. Code: https://github.com/Liiiii2101/AUTOPET2026-MEDAI.","authors":["Xinglong Liang","Chunyao Lu","Tianyu Zhang","Jiaju Huang","Tao Tan","Yunchao Yin","Lishan Cai"],"published":"2026-08-31T14:13:09Z","updated":"2026-08-31T14:13:09Z","abstract_url":"https://arxiv.org/abs/2608.30844v1","html_url":"https://arxiv.org/html/2608.30844v1","pdf_url":"https://arxiv.org/pdf/2608.30844v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30839v1","title":"Physical Adversarial Examples for Person Detectors in Thermal Images Based on 3D Modeling","abstract":"Thermal Infrared detection is widely used in autonomous driving, medical AI, etc., but its security has only attracted attention recently. We propose infrared adversarial clothing designed to evade thermal person detectors in real-world scenarios. The design of the adversarial clothing is based on 3D modeling, which makes it easier to simulate multiangle scenes near the real world compared to 2D modeling. We optimized the black patch layout pattern of 3D clothing based on the adversarial example technique and made physical adversarial clothing using the aerogel. The idea is to paste a set of square aerogel patches, which display black squares in thermal images, in the inner side of clothing at specific locations with specific orientations. To enhance realism, we propose a method to build infrared 3D models with real infrared photos and develop texture maps for 3D models to simulate varied infrared characteristics over time and location. In physical attacks, we achieved an attack success rate of 80.11\\% indoors and 76.85\\% outdoors against YOLOv9. In contrast, randomly placed patches yielded much lower success rates (26.53\\% indoors and 23.03\\% outdoors). The adversarial clothing also showed good transferability to unknown detectors with an ensemble attack method, demonstrating the effectiveness of our approach.","authors":["Xiaopei Zhu","Siyuan Huang","Zhanhao Hu","Jianmin Li","Jun Zhu","Xiaolin Hu"],"published":"2026-08-31T14:09:41Z","updated":"2026-08-31T14:09:41Z","abstract_url":"https://arxiv.org/abs/2608.30839v1","html_url":"https://arxiv.org/html/2608.30839v1","pdf_url":"https://arxiv.org/pdf/2608.30839v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30835v1","title":"Reliable Benchmarking of Artifact Detection in Computational Pathology: A Reproducibility and Uncertainty Analysis","abstract":"Background and Objective: Quality control is a prerequisite for whole-slide image analysis, yet the benchmarks on which quality-control methods are compared share four properties that make their reported differences hard to interpret: few independent slides, annotation concentrated in a minority of them, pooled ratio metrics with no closed-form standard error, and a single inherited train/test partition. We propose a reliability protocol for such benchmarks. Methods: The protocol quantifies four sources of variability - test-set sampling, training stochasticity, partition composition, and undocumented preprocessing - a claim is reportable only if it survives all four; three of the four cost minutes of compute. We apply it to an independent reconstruction of a published diffusion-based artifact detector, evaluated on the original 24-slide partition and against a supervised baseline. Results: The method's central mechanism reproduces: the auxiliary contrastive term improves pooled F1 from 0.673 to 0.688 and replicates under a second seed (+0.0156, p = 0.031; +0.0190, p = 0.005), although it acts on pen marking rather than the artifact types cited to motivate it. Its comparative claims do not: differences between design variants, and against the supervised baseline, fall inside the uncertainty of the evaluation. Four of 24 slides carry 70% of scored annotated pixels, giving an effective sample size of 6.2, and the inherited partition sits at the 7th percentile. An unreported tissue-restriction step excludes 41.4% of out-of-focus annotation against 2.6% of air bubble; such a gate is confounded with blur by construction. Conclusions: Small-cohort benchmarks support far weaker conclusions than current reporting implies. The four checks are cheap enough to accompany any evaluation on such a resource and separate reproducible effects from differences the evaluation cannot resolve.","authors":["Konstantinos Moutselos","Ilias Maglogiannis"],"published":"2026-08-31T14:07:15Z","updated":"2026-08-31T14:07:15Z","abstract_url":"https://arxiv.org/abs/2608.30835v1","html_url":"https://arxiv.org/html/2608.30835v1","pdf_url":"https://arxiv.org/pdf/2608.30835v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30824v1","title":"Whole-Body MRI Classification via Prompt-Based Clinical Conditioning","abstract":"Combining whole-body magnetic resonance imaging (WB-MRI) with clinical variables has the potential to improve systemic disease diagnosis by leveraging complementary sources of patient information. However, structured clinical variables are often incomplete or missing, limiting the applicability of conventional multimodal fusion methods that assume fixed inputs. In this work, we propose TACTIC (Tabular-Attribute Conditioned Transformer for Image Classification), a prompt-based multimodal framework that integrates WB-MRI and structured clinical data through conditional visual feature learning. By encoding clinical attributes as prompts, TACTIC supports an arbitrary number of tabular inputs and naturally handles missing data without requiring imputation or fixed input structures. We evaluate TACTIC on five WB-MRI classification tasks spanning systemic and oncologic applications, including diabetes, chronic obstructive pulmonary disease (COPD), breast cancer, prostate cancer, and metastasis diagnosis. Across all tasks, TACTIC consistently improves performance over image-only baselines when clinical information is available while maintaining strong predictive capability under incomplete tabular inputs. Our results demonstrate the effectiveness of prompt-based models as a flexible approach for improving WB-MRI analysis using clinical context. The model weights and code are available at https://github.com/lauradaza/TACTIC","authors":["Laura Daza","Marta Hasny","Cristina González","Julia A. Schnabel"],"published":"2026-08-31T14:03:41Z","updated":"2026-08-31T14:03:41Z","abstract_url":"https://arxiv.org/abs/2608.30824v1","html_url":"https://arxiv.org/html/2608.30824v1","pdf_url":"https://arxiv.org/pdf/2608.30824v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30821v1","title":"Lucida: Parse, Generate, and Place for Composable Real-to-Sim Scene Modeling","abstract":"Composable scene modeling aims to recover a real indoor scene as complete, editable object assets arranged as observed, giving robot simulation and embodied AI a simulation-ready replica of the real environment whose objects can be manipulated individually. Existing pipelines decompose the task into three steps---parse the observations into instances, generate an asset for each, and place each asset back---but every step presumes an input that a cluttered capture rarely provides: accurate instance geometry, unoccluded views, and assets that accurately match the observations. We propose Lucida, which keeps this order but redistributes the requirements, so each step consumes only what a real capture reliably provides and precision is reached at the end of the pipeline rather than demanded at its start. Lucida parses the video into a scene graph whose nodes carry per-instance multi-view evidence, generates a complete asset for each instance from its evidence, and places assets with GizmoAct, a VLM policy that casts placement as multi-turn GUI interaction, manipulating the object's gizmo in a closed loop and deciding itself when alignment is reached. Across scene-level 3D object detection, object pose estimation, and scene reconstruction, Lucida improves mAP over Boxer by 69% on R2S-Scene, raises ADD-SB@0.05 from 57.8% to 83.4% on CA-1M, and increases scene F-Score from 0.794 for SAM3D to 0.924.","authors":["Minghan Qin","Yuang Wang","Xiuyu Yang","Yushi Long","Yujian Zhang","Ruihuan Wang","Kai Ye","Yangang Zhang","Hang Li"],"published":"2026-08-31T14:03:20Z","updated":"2026-08-31T14:03:20Z","abstract_url":"https://arxiv.org/abs/2608.30821v1","html_url":"https://arxiv.org/html/2608.30821v1","pdf_url":"https://arxiv.org/pdf/2608.30821v1.pdf","matched_keywords":["video","3d","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30817v1","title":"A Composition-Aware Pretraining Framework for Geospatial Foundation Models","abstract":"Geospatial foundation models have emerged as state-of-the-art methods for downstream Earth observation tasks. However, existing pretraining methodologies process imagery through a single-concept lens, failing to capture the highly compositional nature of complex satellite scenes. We propose a composition-aware pretraining framework that explicitly encodes fractional land-cover mixtures. Each satellite image cell is mapped to a histogram representing its fractional land-cover distribution, which we term the \"composition target\". These targets serve as the primary prediction objective and are distilled into the backbone using Earth Mover's Distance. Experimental evaluation shows that composition-aware pretraining yields substantial gains on region-level understanding tasks requiring semantic similarity judgment, including zero-shot image retrieval and scene classification, while remaining competitive on tasks requiring fine-grained spatial precision, such as segmentation and object detection. With a 36.8M-parameter backbone, our framework outperforms SatMAE and Prithvi-EO-2.0, which contain 303M and 600M parameters, respectively, in most retrieval and scene classification settings. On the fine-grained ForestNet-12 dataset, a rigorous testbed for compositional discrimination, our method boosts baseline mAP@10 from 0.279 to 0.434, a 55.6% relative improvement, providing direct evidence for the effectiveness of explicit composition modeling. The code implementation can be found at https://github.com/05kashyap/GFM_Composition_Pretraining","authors":["Aryan Kashyap Naveen","Abhishek Srinivas","Pranav Moothedath","Shrutilipi Bhattacharjee"],"published":"2026-08-31T14:00:12Z","updated":"2026-08-31T14:00:12Z","abstract_url":"https://arxiv.org/abs/2608.30817v1","html_url":"https://arxiv.org/html/2608.30817v1","pdf_url":"https://arxiv.org/pdf/2608.30817v1.pdf","matched_keywords":["retrieval"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30758v1","title":"CheXGround: Anatomical Region Tokens for Grounded Longitudinal Chest X-ray Interpretation","abstract":"Recent radiology multi-modal language models have made substantial progress in chest X-ray report generation, visual question answering, and temporal reasoning. While longitudinal chest X-ray interpretation compares sequential examinations to describe change, visual grounding aims to connect clinical language with localized image evidence. Although longitudinal modeling and visual grounding have each advanced radiology language models, how localized visual evidence can support longitudinal interpretation remains under-explored. We introduce CheXGround, a region-grounded longitudinal chest X-ray language model that represents paired studies through corresponding anatomical regions. CheXGround extracts anatomical regions from current and prior radiographs, encodes them as temporally enhanced Region-of-Interest (ROI) tokens, and combines them with global temporal image context during generation. To connect these region tokens with clinical text, we propose Temporal Region--Phrase Alignment, a pretraining objective that aligns temporal anatomical representations with localized report phrases. We evaluate CheXGround on single-study and longitudinal Visual Question Answering (VQA), longitudinal findings generation, temporal grounded VQA, and anatomical grounding. Across these tasks, CheXGround improves clinical language quality, temporal reasoning, and localization accuracy over recent baselines. Our results suggest that organizing longitudinal evidence at the anatomical level is a strong representation for grounded radiology language modeling. Project page: https://adonaydem.github.io/chexground-website","authors":["Adonay Demewez Gebremedhin","Wessam Shehieb","Sara Alansari","Mohamad Alansari","Muzammal Naseer","Sajid Javed","Naoufel Werghi"],"published":"2026-08-31T13:25:40Z","updated":"2026-08-31T13:25:40Z","abstract_url":"https://arxiv.org/abs/2608.30758v1","html_url":"https://arxiv.org/html/2608.30758v1","pdf_url":"https://arxiv.org/pdf/2608.30758v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30751v1","title":"Autoregressive Mosaics: Probing 2D Spatial Reasoning in Text-Only Language Models","abstract":"Large language models (LLMs) trained only on text and code can sometimes generate programs that draw recognizable images. However, it is unclear whether this reflects an internal representation of 2D spatial layout or simply the ability to translate spatial descriptions into code. We introduce Autoregressive Mosaics (AM-Bench), a benchmark that separates these factors: First, a translation task gives a model a fully specified geometry of a picture in words as a prompt and asks for the code that produces it. Second, a layout task requires the model to compose an image from an underspecified prompt. Across eight open-weight text-and-code-only models, all models reliably translate specified geometry into code, but their open-ended layout performance differs substantially, indicating that these differences are not explained by code-generation ability alone. An output-medium ablation further shows that the interface or medium of expression that the model uses matters: replacing procedural code with raw SVG improves layout scores across all models. Finally, probing model activations shows that a coarse layout plan is present before generation, but reflects only the layout implied by the prompt. During generation, models track the evolving geometric state instead of executing an initially fixed plan. Overall, these results show that 2D spatial performance in text-only LLMs depends on both the model and the output medium, and is not explained by code-generation ability alone.","authors":["Ashwin Nedungadi","Stefan Oehmcke","Stefan Lüdtke"],"published":"2026-08-31T13:18:03Z","updated":"2026-08-31T13:18:03Z","abstract_url":"https://arxiv.org/abs/2608.30751v1","html_url":"https://arxiv.org/html/2608.30751v1","pdf_url":"https://arxiv.org/pdf/2608.30751v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30727v1","title":"RailGen: Improving Railway Intrusion Detection via Agent-Guided Small-Scale Foreign Object Generation","abstract":"Small-object detection under long-tailed data distributions is a fundamental yet challenging problem in multimedia. Railway Foreign Object Detection (RFOD) epitomizes this challenge with easily confused small intrusions and scarce samples. To address these issues, we propose a generative-augmented detection paradigm that leverages multimodal image generation to enrich the feature space of rare and small objects. We first construct RailGen, a multimodal image generation agent based on large models. Under semantic constraints, RailGen automatically invokes tools to generate railway scenes, calibrate intrusion positions, extract foreign objects, and fuse them into realistic intrusion effects. This process produces high-quality synthetic samples that effectively densify the feature representations of tail classes and complete the small-object feature space. Within this paradigm, we further propose FocalDEIM, a detection framework designed to enhance training with generated data. FocalDEIM improves dense matching with Focal Modulation for better small-object discrimination and adopts Focal Loss to emphasize hard samples, thereby alleviating blurred inter-class boundaries in complex railway scenes. Experimental results demonstrate that RailGen can generate high-quality small-scale foreign objects, reducing the object pixel area by up to 58x and 13.85x on average. Equipped with these challenging samples, our paradigm surpasses the baseline DEIM by 5.6% and 7.5% in mAP@50 and mAP@(50-95), respectively, and outperforms existing state-of-the-art methods. Ablation studies verify RailGen's feature-space enrichment and FocalDEIM's boundary discrimination. The paradigm provides an effective multimodal generative solution for long-tailed small-object detection in safety-critical applications.","authors":["Quan Hao","Ziyang Tao","Chenxi Zhang","Yudong Wang","Rui Shi","Liguo Zhang"],"published":"2026-08-31T13:01:12Z","updated":"2026-08-31T13:01:12Z","abstract_url":"https://arxiv.org/abs/2608.30727v1","html_url":"https://arxiv.org/html/2608.30727v1","pdf_url":"https://arxiv.org/pdf/2608.30727v1.pdf","matched_keywords":["agent","representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30716v1","title":"SocialReasonBench: A Video-QA Benchmark for Social Reasoning with Counterfactual Narrative Videos","abstract":"Recent advances in Large Multimodal Models (LMMs) have greatly improved video understanding, yet their ability to reason about human-centered social situations remains limited. Existing benchmarks typically rely on videos with a single observed trajectory, making it difficult to determine whether models truly understand social dynamics or merely exploit recurring narrative patterns. We introduce SocialReasonBench, a video multiple-choice QA benchmark for evaluating socially grounded reasoning in scenarios derived from interactive narratives. Built from gameplay videos of Detroit: Become Human, the benchmark leverages branching storylines where player decisions lead to alternative social outcomes that can be checked against the game's own script, flowchart, and recorded branches. We develop a multi-agent curation pipeline that localizes socially meaningful clips, grounds answer labels in game-state signals, and generates theory-guided questions with diagnostic distractors. SocialReasonBench covers seven reasoning dimensions, including intent recognition, emotional empathy, moral dilemma, counterfactual reasoning, and causal antecedent. Experiments on contemporary LMMs show that models perform reasonably well on basic social understanding but struggle with counterfactual and causal reasoning. Further ablation and diagnostic error analyses reveal that models often depend on incomplete modality cues and fall into reasoning traps such as visual shortcuts, highlighting a gap between observable event recognition and deeper reasoning over latent social states.","authors":["Zheyu Huang","Zijing Shi","Haozhe Luo","Huadong Tang","Mingyu Liu","Meng Fang","Ling Chen"],"published":"2026-08-31T12:55:52Z","updated":"2026-08-31T12:55:52Z","abstract_url":"https://arxiv.org/abs/2608.30716v1","html_url":"https://arxiv.org/html/2608.30716v1","pdf_url":"https://arxiv.org/pdf/2608.30716v1.pdf","matched_keywords":["video","agent","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30709v1","title":"RailSyn: Diagnosis-Guided Image Generation for Traceable Data Completion in Railway Foreign Object Detection","abstract":"Railway foreign object detection (RFOD) is critical to safe railway operation, yet scarce real positive samples incompletely represent task-relevant variations in object scale, intrusion relation, railway scene, illumination, and adverse weather. Existing synthetic augmentation can improve RFOD detection, but its gains lack an explicit account of the task-relevant deficiencies complemented by the generated data. We therefore introduce RailSyn, a diagnosis-guided framework comprising a real-referenced Inspector and a requirement-aligned Generator. The Inspector constructs a variable-radius empirical cover from finite real observations to localize candidate completion regions and profile synthetic pools. The resulting audit identifies railway-context, intrusion-semantic, and visual-consistency requirements; the Generator addresses them through domain adaptation, agent-planned placement and physical contact relations, and plan-consistent conditional refinement. Using the Inspector, we further trace representation-space changes across generation variants; the complete system attains a local-shell occupation of $C_{gap}$ to 13.64%, which measures generated coverage of real-derived completion regions. Extensive experiments show AP50--95 gains of up to 4.9 points and consistent improvements across nine mainstream detectors, demonstrating broad cross-architecture utility.","authors":["Quan Hao","Chenxi Zhang","Ziyang Tao","Yuyuan Zhou","Yudong Wang","Rui Shi","Lechuan Xu","Changhao Liu","Liguo Zhang"],"published":"2026-08-31T12:47:28Z","updated":"2026-08-31T12:47:28Z","abstract_url":"https://arxiv.org/abs/2608.30709v1","html_url":"https://arxiv.org/html/2608.30709v1","pdf_url":"https://arxiv.org/pdf/2608.30709v1.pdf","matched_keywords":["agent","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30705v1","title":"VisLens: Single-Pass Interpretable Visual Search for Multimodal LLMs","abstract":"Multimodal large language models (MLLMs) struggle with fine-grained Visual Search, the task of locating small or rare objects in high-resolution images. Existing remedies fall into two families: (1) Training-free methods based on attention or confidence scores are accurate but slow, since they require multiple MLLM queries per example. (2) Reinforcement Learning (RL) trained tool-use models are faster at inference but opaque, since their tool calls remain uncontrollable and hard to interpret. To overcome this, we propose \\emph{VisLens} (Visual Focus via Logit Lens), a Visual Search method built on the logit lens, which decodes the semantics held in a hidden state by projecting it through the LLM head. VisLens further uses a lightweight tuned-lens that maps early hidden states into the final hidden state space, so visual tokens can be read out from early layers. These tokens are matched to target words in the query to generate a crop of the relevant region, which is fed back in alongside the original image to produce the final answer. The whole process, from decoding to the final answer, completes in a single forward pass without repeated queries. VisLens matches or exceeds prior baselines while delivering a substantial latency advantage, running $8.5$--$9.9\\times$ faster than Thyme and up to $22.2\\times$ faster than training-free multi-pass search methods.","authors":["Jingyi He","Sanghwan Kim","Zeynep Akata"],"published":"2026-08-31T12:43:42Z","updated":"2026-08-31T12:43:42Z","abstract_url":"https://arxiv.org/abs/2608.30705v1","html_url":"https://arxiv.org/html/2608.30705v1","pdf_url":"https://arxiv.org/pdf/2608.30705v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30704v1","title":"TUE-Detector: A Tool-Using Expert MLLM-Based Detector for AI-Generated Videos","abstract":"AI-generated video detection, which aims to distinguish AI-generated videos from real ones, has recently received increasing research attention. To perform this task reliably, a key challenge lies in accurately identifying subtle-yet-measurable unnatural artifacts. In this work, we address this challenge from a novel perspective of tool-mediated evidence discovery and propose Tool-Using Expert MLLM-based AI-generated Video Detector (TUE-Detector), a novel framework for AI-generated video detection. TUE-Detector trains a general MLLM into a task-tailored tool-using expert detector that learns to invoke suitable tools, collect concrete evidence of unnaturalness, and reason over the evidence for reliable detection. Meanwhile, TUE-Detector further introduces novel designs to equip the expert detector with high-quality and suitable tools. Extensive experiments demonstrate the effectiveness of our framework.","authors":["Yichen Wu","Haoxuan Qu","Yongxing Dai","Yan Bai","Yihang Lou","Yuqi Lin","Hossein Rahmani","Jun Liu"],"published":"2026-08-31T12:42:38Z","updated":"2026-08-31T12:42:38Z","abstract_url":"https://arxiv.org/abs/2608.30704v1","html_url":"https://arxiv.org/html/2608.30704v1","pdf_url":"https://arxiv.org/pdf/2608.30704v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30692v1","title":"Can Video World Models Track Unobserved World States?","abstract":"Video world models are increasingly used as simulators, yet visual fidelity alone does not show that a model maintains the hidden state of the world. We examine this gap with an action-conditioned video Shell Game, a visual analog of $S_5$ state tracking that decouples visual rendering from compositing the hidden state underneath. Bidirectional and autoregressive Transformers, Mamba, and linear attention restricted to nonnegative transition eigenvalues all fit the training horizon of 5 swaps and then fall toward chance on longer swap chains (extrapolation) while still rendering plausible video with additional denoising steps providing no benefit. The pixel-based diffusion target never supervises the unseen hidden state, so the generated frames cannot carry it and the state has to live inside the architecture rather than in the tokens. For a Transformer, that architectural state is only an append-only KV cache, so the model has to re-derive the hidden arrangement from the whole history at every chunk. We find two mechanisms that do extrapolate, and both carry a state across chunks and revise it in place. Linear attention succeeds once its transition eigenvalues may be negative, and TTT with a nonlinear fast weight succeeds by updating the feature map through which it reads its own state. We further examine harder cases in dynamic world exploration tasks, and discuss the broader implications for building stateful video world models.","authors":["Joonghyuk Shin","Yicong Hong","Jaesik Park","Xun Huang"],"published":"2026-08-31T12:29:24Z","updated":"2026-08-31T12:29:24Z","abstract_url":"https://arxiv.org/abs/2608.30692v1","html_url":"https://arxiv.org/html/2608.30692v1","pdf_url":"https://arxiv.org/pdf/2608.30692v1.pdf","matched_keywords":["video","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30688v1","title":"UFPR-PEs: A Brazilian Face Recognition Benchmark with Self-Declared Race/Color Labels","abstract":"While face recognition systems are widely deployed, ensuring their demographic reliability and robustness under uncontrolled visual conditions remains a critical challenge. To bridge this gap, we present UFPR-PEs, a benchmark for face recognition bias evaluation using public videos of elected Brazilian politicians annotated with official self-declared race/color categories. The dataset adopts the Brazilian census taxonomy, including the parda category, which has no direct equivalent in the U.S.- or Europe-centric schemas commonly used in prior benchmarks. Our benchmark is built from compressed public video and preserves difficult samples so that performance can be analyzed under realistic conditions. We describe the construction pipeline, report dataset statistics, and evaluate face recognition performance across verification and (closed- and open-set) identification settings, including subgroup analysis by race/color and difficulty level. The results show that recognition performance varies substantially with image quality, and that subgroup gaps must be interpreted jointly with visual difficulty rather than in isolation. Overall, UFPR-PEs provides a reproducible and demographically grounded setting for studying face recognition bias under challenging public video conditions.","authors":["Alexandre Diano","Bernardo Biesseck","Gabriel Polo","Vinicius Gregorio","Laura Lopes","Diego Addan","David Menotti"],"published":"2026-08-31T12:27:15Z","updated":"2026-08-31T12:27:15Z","abstract_url":"https://arxiv.org/abs/2608.30688v1","html_url":"https://arxiv.org/html/2608.30688v1","pdf_url":"https://arxiv.org/pdf/2608.30688v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30657v1","title":"InfraOcc: An Infrastructure Occupancy Benchmark with Static-to-Dynamic Reasoning","abstract":"Fixed-viewpoint infrastructure sensors repeatedly observe the same traffic space, making roadside 3D occupancy structurally different from ego-vehicle perception: a near-persistent static scaffold is overlaid with sparse, short-lived dynamic events. Existing occupancy benchmarks and methods, however, are built around moving ego vehicles and neither measure nor exploit this structure, instead treating occupancy as flat one-shot voxel classification. We address this gap from both data and model perspectives. We build InfraOcc, to our knowledge, the first real-world infrastructure-side semantic occupancy benchmark, with dense voxel annotations for 290 multi-modal sequences in a fixed roadside frame, a static-dynamic decoupled annotation pipeline, unified camera-only, LiDAR-only, and multi-modal evaluation, and diagnostics for static and dynamic occupancy. InfraOcc shows that static infrastructure fills 97.3% of occupied voxels and persists across frames, whereas dynamic participants have a median occupied-frame ratio of only 1.8% per location, revealing a structural static-dynamic asymmetry beyond semantic long-tailedness. We further propose ProSD-Occ, which reformulates occupancy as progressive static-to-dynamic evidence reasoning: it explains persistent layout, exposes residual dynamic evidence under static-confidence guidance, and recomposes static, dynamic, and free-space evidence into a unified field. ProSD-Occ ranks first in overall, dynamic, static, and geometric occupancy on every track, e.g., a 23.5% relative camera-only dynamic-mIoU gain over the strongest baseline and 65.87 multi-modal overall mIoU, establishing fixed-viewpoint roadside occupancy as a distinct problem with its own reasoning paradigm. The benchmark and code will be publicly available at https://github.com/yanglei18/InfraOcc","authors":["Lei Yang","Xiaokai Bai","Boqi Li","Chunmian Lin","Li Wang","Ziying Song","Jiahuan Zhang","Enhui Ma","Haibao Yu","Jiaqi Ma","Kaicheng Yu"],"published":"2026-08-31T11:56:50Z","updated":"2026-08-31T11:56:50Z","abstract_url":"https://arxiv.org/abs/2608.30657v1","html_url":"https://arxiv.org/html/2608.30657v1","pdf_url":"https://arxiv.org/pdf/2608.30657v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30656v1","title":"APT: Anchor-aligned Perturbations for Tamper Localization in Fully Regenerated Images","abstract":"Proactive tamper localization embeds an imperceptible signal into an image prior to distribution, enabling pixel-level manipulation detection. Existing methods assume a spliced (SP) setting, where synthesized regions are composited onto the original background, leaving embedded signals intact. However, real-world diffusion-based inpainting operates in a fully regenerated (FR) setting, where the entire image undergoes denoising, disrupting background signals and rendering existing frameworks ineffective. We propose APT, a semi-fragile latent-space perturbation that embeds a dense, vector-wise localization signal. By aligning each spatial feature vector toward a fixed anchor direction, APT localizes tampering via the alignment disparity between synthesized foreground and anchor-aligned background features after inpainting. The proposed hard negative mining loss and noisy perturbation branch further enforce uniform alignment. Experiments on COCO demonstrate that APT achieves an FR IoU of 0.92, outperforming the strongest baseline (WAM, 0.84), while existing methods collapse to near-random performance (AUC 0.5), establishing APT as a practical forensic framework generalizable across tampering types unknown at test time.","authors":["Suhyeon Ha","Woo Jae Kim","Joonsung Jeon","Sooel Son","Sung-eui Yoon"],"published":"2026-08-31T11:56:39Z","updated":"2026-08-31T11:56:39Z","abstract_url":"https://arxiv.org/abs/2608.30656v1","html_url":"https://arxiv.org/html/2608.30656v1","pdf_url":"https://arxiv.org/pdf/2608.30656v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30653v1","title":"Fine-Grained Multi Image Object Hallucination Benchmark","abstract":"Multimodal Large Language Models (MLLMs) are increasingly deployed in multi-image scenarios requiring complex reasoning across visual contexts. However, current MLLMs remain fundamentally limited by object hallucination-generating plausible yet factually inconsistent descriptions about objects. Existing benchmarks, designed primarily for single-image settings or providing only high-level multi-image assessments, cannot systematically diagnose how visual complexity and reasoning demands trigger hallucination. To address this gap, we introduce MIOH, a fine-grained multi-image object hallucination benchmark that systematically evaluates object hallucination across four foundational tasks (existence, counting, attribute, position) through three multi-image reasoning patterns (comprehensive, comparative, selective) under three controlled adversarial pressures (visual context scale, perceptual difficulty, contextual bias). Through evaluation of 29 models, we reveal that even state-of-the-art systems like GPT-5 and Gemini-2.5-Pro exhibit distinct failure patterns across different reasoning patterns and tasks. Our evaluation reveals that hallucination stems not merely from perceptual failures but from integration-stage limitations when maintaining object representations across multiple images. MIOH provides a controlled framework for analyzing multi-image object hallucination and serves as a critical evaluation tool for developing more reliable multimodal AI systems.","authors":["Joonki Min","Chaeyun Kim","Hyungwook Choi","Yejin Kim","Kihyun Kim","Yohan Jo","Joonseok Lee"],"published":"2026-08-31T11:53:03Z","updated":"2026-08-31T11:53:03Z","abstract_url":"https://arxiv.org/abs/2608.30653v1","html_url":"https://arxiv.org/html/2608.30653v1","pdf_url":"https://arxiv.org/pdf/2608.30653v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30649v1","title":"Where Identity Lives: Localized, Retain-Free Identity Unlearning in Multimodal Large Language Models","abstract":"Removing a specific individual's information from multimodal large language models (MLLMs) is often needed after deployment, but existing methods rely on a retain set, which is hardest to obtain at that point, and rebuilding it recreates the privacy exposure that unlearning aims to remove. Forgetting from the forget set alone instead damages the shared visual-language computation, harming perception. We cast retain-free unlearning as a localization problem: causal tracing, weight transplant, and Fisher overlap all point to early-to-mid decoder MLPs as the layers where identity information is stored and, unlike other module families, can be modified without substantially disrupting vision. We turn this into Pathway-Aware Visual-attribute Anchoring (PAVA), which confines updates to these layers and pairs a forget loss with a visual-attribute anchor that preserves image-grounded behavior by distilling the model's own pre-unlearning answers from the forget images alone. On MLLMU-Bench and ReMem, PAVA gives the strongest forget-retain trade-off among forget-set-only methods and remains competitive with retain-based baselines.","authors":["Kangwook Ko","Jaehyuk Jang","Wonjun Lee","Hee-Seon Kim","Changick Kim"],"published":"2026-08-31T11:51:05Z","updated":"2026-08-31T11:51:05Z","abstract_url":"https://arxiv.org/abs/2608.30649v1","html_url":"https://arxiv.org/html/2608.30649v1","pdf_url":"https://arxiv.org/pdf/2608.30649v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30633v1","title":"Quantum-Grassmann-Plucker Token Mixing for Deep Learning-Based Post-Disaster Damage Assessment","abstract":"Timely post-disaster building damage assessment from satellite imagery is a critical engineering decision support task, yet it remains constrained by class imbalance, ambiguous intermediate damage states, and limited cross-event transferability. This study presents, to our knowledge, the first application of Grassmann-Plucker (GP) token mixing to computer vision and introduces two extensions for image classification: the Quantum-inspired Grassmann-Plucker (QGP) head and the Hybrid Quantum Machine Learning Grassmann-Plucker (HQML-GP) head. The GP head represents multiscale relationships among image patch tokens by encoding subspaces formed by token pairs with Plucker coordinates; QGP enriches these coordinates with amplitude-derived probability features, whereas HQML-GP incorporates expectation values generated by a simulated quantum circuit into the geometric token representation. Paired pre- and post-event image patches from the xBD tornado dataset were processed using a frozen six-channel Vision Transformer base encoder with 16 x 16-pixel patches. The three GP-based heads were compared with multilayer perceptron and Transformer baselines under identical training, checkpoint selection, and evaluation protocols. Joplin and Moore tornado samples were used for model development and seen-event testing, while Tuscaloosa was reserved for unseen-event evaluation. QGP led both test sets in accuracy and macro-F1: 83.46% and 64.50% for the seen events, and 66.45% and 52.70% for the unseen event. Although HQML-GP obtained the highest validation macro-F1 of 65.63%, it did not surpass QGP on either test set and required substantially more training time per epoch. These results establish GP token mixing as a competitive attention-free alternative to conventional Transformer-based token mixing for paired satellite image damage classification.","authors":["Kooroush Farahkhah","Umut Lagap","Taha Rezaei","Saman Ghaffarian"],"published":"2026-08-31T11:42:27Z","updated":"2026-08-31T11:42:27Z","abstract_url":"https://arxiv.org/abs/2608.30633v1","html_url":"https://arxiv.org/html/2608.30633v1","pdf_url":"https://arxiv.org/pdf/2608.30633v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30618v1","title":"AQ3D: Adaptive Query Transformer for 3D Instance Segmentation","abstract":"Transformer-based decoders for 3D instance segmentation typically commit to a fixed number of queries and positional modeling calibrated on the training distribution rather than on the scene at hand. Indoor scans vary widely in spatial extent and object count, so a fixed query set over-initializes small scenes and under-initializes large ones, while learned absolute and relative encodings are bound to the training scenes' extents and can saturate. We present AQ3D, which is designed to handle scenes of various sizes during training and inference. Queries are instantiated at a fixed ratio of the scene's superpoints, forming an overcomplete set whose background rejection is entirely left to the decoder. Positional information is encoded using 3D RoPE over quantized metric coordinates, replacing learned bounded lookup tables of prior decoders. Further, we improve the decoder itself by using attribution-based superpoint pooling, a mask refinement branch, and a cosine classifier for background rejection. Experiments show our method sets a new state-of-the-art on validation and hidden test splits across the datasets ScanNetV2, ScanNet200, and ScanNet++V2 among decoder methods trained without additional data augmentation. Code is available at \\href{https://github.com/kenomo/aq3d}{github.com/kenomo/aq3d}.","authors":["Keno Moenck","Thorsten Schüppstuhl"],"published":"2026-08-31T11:27:42Z","updated":"2026-08-31T11:27:42Z","abstract_url":"https://arxiv.org/abs/2608.30618v1","html_url":"https://arxiv.org/html/2608.30618v1","pdf_url":"https://arxiv.org/pdf/2608.30618v1.pdf","matched_keywords":["3d","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30617v1","title":"RealCAD: Towards Real-World Image-to-CAD Reconstruction under Domain Shift and Parameter Bias","abstract":"Reconstructing editable Computer-Aided Design (CAD) models from images is essential for downstream modification, manufacturing, and design reuse. However, existing image-to-CAD methods are developed predominantly on synthetic renderings and face two coupled obstacles: a substantial appearance domain gap between synthetic and real images, and a previously overlooked parameter bias in widely used CAD data. We show that the local normalization adopted by DeepCAD concentrates several geometric parameters around a few discrete values while encoding substantial information in a single scale factor. Consequently, a model can achieve deceptively high parameter accuracy by exploiting these frequent values rather than inferring geometry from the input image. In this paper, we propose RealCAD, a unified framework that addresses these limitations at the representation, image, and feature levels. At the representation level, we redistribute scale information to the corresponding geometric parameters, producing less concentrated parameter distributions in a shared scale space. At the image level, geometry-constrained translation converts synthetic renderings toward the real-image domain while conditioning on object contours. At the feature level, a multi-positive contrastive objective aligns representations of the same CAD model across viewpoints and image domains, enabling CAD sequence prediction from each individual view. We further introduce OpenRealCAD, comprising four-view photographs of 392 3D-printed objects paired with ground-truth command sequences. Experiments show that the revised representation substantially reduces the accuracy attainable from parameter-frequency priors, making parameter accuracy a more reliable measure of image-conditioned geometric inference. RealCAD further improves real-domain command and parameter accuracy, while retaining competitive synthetic-domain performance.","authors":["Yihe Sun","Ziyu Lu","Kaihua Tang","Xian-Sheng Hua"],"published":"2026-08-31T11:27:22Z","updated":"2026-08-31T11:27:22Z","abstract_url":"https://arxiv.org/abs/2608.30617v1","html_url":"https://arxiv.org/html/2608.30617v1","pdf_url":"https://arxiv.org/pdf/2608.30617v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30603v1","title":"DiffSAC: Diffusion-guided Sampling for Consensus-based Robust Estimation","abstract":"Robust estimation is a core computer vision task frequently tackled using sample consensus. However, traditional methods suffer from inefficient sampling as they struggle to identify effective minimum sets before hypothesis evaluation. To address these challenges, we propose a novel Diffusion-guided Sampling for Consensus-based Robust Estimation (DiffSAC) framework. DiffSAC introduces a diffusion model to learn the distribution of effective minimum sets. It refines the confidence for each data point, indicating whether it belongs to a good minimum set, rather than ranking the data points as in previous work. This significantly reduces the need to process numerous bad sets. To constrain the refinement direction, geometric features are incorporated as conditions within our diffusion model. Consequently, DiffSAC outputs a small number of high-quality minimum sets, enabling identification of the best hypothesis via consensus evaluation. Notably, compared to previous works requiring evaluating over ten thousand hypotheses, DiffSAC achieves state-of-the-art performance with only dozens, significantly boosting efficiency. Extensive experiments across five classic computer vision tasks demonstrate the superiority of DiffSAC. The diffusion model's sampling accelerators enable real-time operation, and DiffSAC can be used as a plug-and-play module to improve existing sample consensus methods.","authors":["Chang Nie","Guangming Wang","Zhe Liu","Hesheng Wang"],"published":"2026-08-31T11:15:11Z","updated":"2026-08-31T11:15:11Z","abstract_url":"https://arxiv.org/abs/2608.30603v1","html_url":"https://arxiv.org/html/2608.30603v1","pdf_url":"https://arxiv.org/pdf/2608.30603v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30584v1","title":"Learning Compositional Spatio-Temporal Video Grounding with Synthetic Curriculum","abstract":"Despite the impressive progress of recent MLLMs on spatio-temporal video grounding (STVG), existing evaluations and training data focus primarily on simple queries. They largely overlook the compositional queries prevalent in real-world scenarios, where a target must be disambiguated by jointly reasoning about its attributes and relations to other entities. To bridge this gap, we propose Compositional Spatio-Temporal Video Grounding (CompSTVG), a task that requires models to process complex textual queries where every intertwined attribute and relational cue is essential for disambiguation. To facilitate this task at scale, we build a synthetic data engine that leverages a spatio-temporal scene graph as a difficulty measure and casts difficulty-controlled query synthesis as a constraint programming problem, producing difficulty-graded data for both evaluation and training. Built on this engine, we introduce STVG-CompBench, a benchmark stratified by explicit difficulty levels that jointly capture temporal complexity and spatial interference. Evaluating 11 representative STVG models on STVG-CompBench reveals that current models perform poorly on compositional queries, exhibiting a sharp performance drop that is typically obscured by overall dataset-level averages. We further construct synthetic training data and propose CurrSTVG, a curriculum reinforcement learning framework that delivers consistent gains, with the largest improvements observed on the most challenging compositional queries.","authors":["Xingjian Wang","Shijian Wang","Yibo Wang","Zihao Yu","Runhao Fu","Xuelian Cheng","Zongyuan Ge"],"published":"2026-08-31T11:01:31Z","updated":"2026-08-31T11:01:31Z","abstract_url":"https://arxiv.org/abs/2608.30584v1","html_url":"https://arxiv.org/html/2608.30584v1","pdf_url":"https://arxiv.org/pdf/2608.30584v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30563v1","title":"Modality Disentangled Learning for Incomplete Multimodal Emotion Recognition: A Primitive Memory Distillation Perspective","abstract":"Multimodal Emotion Recognition (MER) systems often suffer from missing modalities in real-world scenarios. Existing methods usually generate, align, or distill missing modalities as a whole, overlooking the heterogeneous nature of the information carried by each modality. Such holistic treatment mixes inferable shared semantics with uncertain modality-specific details, yielding unstable representations and degrading robustness. To address this issue, we propose the Primitive Memory Distillation (PriMD) framework. Unlike existing methods, PriMD takes an intra-modal perspective and focuses on how different types of information within a modality differ in recoverability within each modality. PriMD first disentangles cross-modal shared semantics from modality-specific representations, and then discretizes the latter into learnable semantic primitives to construct modality-specific memory banks. When modalities are missing, PriMD is a teacher-student framework that the student model uses the shared semantics of available modalities as queries to dynamically retrieve primitives. It compensates for missing modality-specific information within a constrained memory space and aligns with the teacher model. Extensive experiments on IEMOCAP, CMU-MOSI, and CMU-MOSEI demonstrate that PriMD achieves state-of-the-art performance and consistently stronger robustness across a wide range of missing-modality settings, while mitigating the instability caused by holistic feature inference. Our code and project website are available at https://github.com/JiaqiZhang-Sengoku/PriMD and https://jiaqizhang-sengoku.github.io/PriMD/, respectively.","authors":["Jiaqi Zhang","Zheng Pang","Mengting Li","Yiqi Wang","Guangyuan Dong","Chao Xue","Yusen Wu","Zihao Li","Huy Phan","Sicheng Zhao","Björn W. Schuller","Jiachen Luo"],"published":"2026-08-31T10:38:47Z","updated":"2026-08-31T10:38:47Z","abstract_url":"https://arxiv.org/abs/2608.30563v1","html_url":"https://arxiv.org/html/2608.30563v1","pdf_url":"https://arxiv.org/pdf/2608.30563v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30550v1","title":"GarmentWeaver: Schema-Aware Structured Synthesis for Multimodal Sewing Patterns","abstract":"Multimodal Sewing pattern generation aims to infer executable sewing patterns from design cues such as sketches and textual descriptions. As an interpretable and simulation-compatible representation, sewing patterns are particularly valuable for digital garment creation. However, existing methods often model garment specifications as flat long sequences, which entangles garment structure with detailed parameters and leads to redundant components, inaccurate local details, and poor simulation compatibility. In this paper, we present GarmentWeaver, a schema-aware framework for multimodal Sewing pattern generation. GarmentWeaver constructs compact hierarchical targets by activating garment-relevant structural branches and predicts executable Sewing patterns in a structured manner. Specifically, we introduce a schema-aware target construction strategy, build the generator on top of a pretrained vision-language model for multimodal garment understanding, and impose feasibility-aware regularization to encourage structurally valid and simulation-compatible outputs. Extensive experiments show that GarmentWeaver produces more accurate and more executable sewing patterns than strong baselines, while also yielding better simulation results. These findings demonstrate the effectiveness of schema-aware structured generation for reliable multimodal Sewing pattern prediction.","authors":["Yinwen Lu","Weihao Luo","Yueqi Zhong"],"published":"2026-08-31T10:25:00Z","updated":"2026-08-31T10:25:00Z","abstract_url":"https://arxiv.org/abs/2608.30550v1","html_url":"https://arxiv.org/html/2608.30550v1","pdf_url":"https://arxiv.org/pdf/2608.30550v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30521v1","title":"MEOM: Multi-View Expected-OKS Maximization for Human Pose Triangulation","abstract":"Conventional algebraic triangulation solves 3D human pose estimation (HPE) from multi-view 2D keypoints. The typical approach, decoding 2D keypoints from predicted heatmaps, is unreliable as heatmaps can be multimodal under occlusion, and collapsing them into single peaks discards their spatial distribution. We seek to use the entire heatmap to estimate 3D poses more accurately, which requires solving two problems: how to robustly fuse heatmaps across views, and how to assess the reliability of heatmaps. For the former, we introduce a novel objective, Multi-viewExpected-OKS Maximization (MEOM), that locates a 3D joint where the views agree in probability mass. For the latter, we adopt highest-density-region (HDR) calibration as a diagnostic of that mass, independently of distance-based metrics. The proposed framework covers two settings, with and without 3D supervision. Without 3D supervision, we optimize 3D poses from pretrained heatmap predictors by maximizing MEOM, achieving comparable performance with state-of-the-art methods that rely on larger backbones, temporal fusion, and simulated 3D data. On ambiguous Human3.6M (H36MA) and occluded CMU Panoptic frames, the advantage is substantial. When 3D labels are available, we train the model end-to-end with a combined MEOM and MSE loss, achieving 19.11 mm absolute MPJPE on Human3.6M outperforming the state-of-the-art volumetric approach on absolute MPJPE at half the inference cost.","authors":["Ziliang Xiong","Henglin Shi","Per-Erik Forssen"],"published":"2026-08-31T09:54:05Z","updated":"2026-08-31T09:54:05Z","abstract_url":"https://arxiv.org/abs/2608.30521v1","html_url":"https://arxiv.org/html/2608.30521v1","pdf_url":"https://arxiv.org/pdf/2608.30521v1.pdf","matched_keywords":["3d","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30510v1","title":"Lot Machine: Multimodal Lot Extraction from Auction Catalogs","abstract":"For provenance research and art market studies, auction catalogs are an essential resource to trace specific objects over time and space. While historical auction catalogs follow established domain conventions, their internal formatting remains highly variable, and their large-scale analysis is currently restricted by the lack of machine-readable representations of the auction lots. We propose a pipeline to automatically extract structured lot-level metadata from German Sales, a large database of historical auction and sales catalogs from the 19th and 20th centuries. Using a manually annotated test set of representative catalog pages, we evaluate Vision-Language Models (VLMs) under varying prompt strategies and constrained decoding frameworks. To reflect the practical constraints faced by cultural heritage institutions, including budget, compute resources, and data privacy requirements, we benchmark the methods across different deployment modes ranging from commercial providers to locally hosted, quantized models. We find that commercial endpoints establish the performance ceiling, while institutional gateways offer a viable, privacy-preserving alternative. Local deployments remain feasible, but strictly require enforcing the output structure during generation to guarantee a valid JSON format. While varying degrees of human-in-the-loop correction are still necessary, this work demonstrates that a VLM-based pipeline can successfully unlock historical auction catalogs for large-scale automated analysis.","authors":["Mathias Zinnen","Alisha Mund","Sabine Lang","Lukas Hüttner","Thomas Gorges","Vincent Christlein"],"published":"2026-08-31T09:44:15Z","updated":"2026-08-31T09:44:15Z","abstract_url":"https://arxiv.org/abs/2608.30510v1","html_url":"https://arxiv.org/html/2608.30510v1","pdf_url":"https://arxiv.org/pdf/2608.30510v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30467v1","title":"Beyond Accuracy: Quantifying Pulmonary Attribution in Anatomy-Guided Chest X-Ray Classification Under Domain Shift","abstract":"Deep-learning models can achieve strong chest X-ray (CXR) classification performance without establishing whether their predictions predominantly rely on pulmonary image content. This study evaluates pulmonary attribution containment as an anatomy-related reliability property distinct from diagnostic performance. We propose DBCA-SegNet-MGAP, a multi-task anatomy-guided CNN-Transformer framework that combines complementary feature representations through bidirectional cross-backbone attention, predicts a soft lung mask, and incorporates this anatomical prior directly into classification through Mask-Guided Adaptive Global Average Pooling (MGAP). Pulmonary attribution containment is quantified using the Anatomical Local Energy Ratio (ALR) and high-intensity cumulative ALR (cALR@0.9). Experiments were repeated across three training seeds using the COVID-19 Radiography Database for four-class internal testing and a locked Shenzhen-to-Montgomery protocol for zero-shot external tuberculosis testing. On COVID-19, the proposed model achieved a weighted F1 of $0.9615 \\pm 0.0015$ and macro ROC-AUC of $0.9906 \\pm 0.0007$. In an architecture-matched dual-bridge comparison, replacing conventional GAP with MGAP increased ALR from $0.3878 \\pm 0.0098$ to $0.7086 \\pm 0.0104$ and cALR@0.9 from $0.5265 \\pm 0.0101$ to $0.9905 \\pm 0.0018$, while weighted F1 remained essentially unchanged ($0.9618 \\pm 0.0015$ vs. $0.9615 \\pm 0.0015$). Under locked external transfer to Montgomery, ROC-AUC remained $0.9080 \\pm 0.0043$ and pulmonary ALR remained $0.6466 \\pm 0.0081$, whereas weighted F1 decreased to $0.7528 \\pm 0.0080$ and ECE increased to $0.1683 \\pm 0.0055$. These findings show that diagnostic discrimination, calibration, and pulmonary attribution containment are distinct model properties and support their joint evaluation under internal testing and external domain shift.","authors":["Abdullah Al Mamun","Md. Nasif Osman Khansur","Md Ashraful Hossen Akash","Md. Kishor Morol","Tze Hui Liew"],"published":"2026-08-31T08:54:44Z","updated":"2026-08-31T08:54:44Z","abstract_url":"https://arxiv.org/abs/2608.30467v1","html_url":"https://arxiv.org/html/2608.30467v1","pdf_url":"https://arxiv.org/pdf/2608.30467v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30451v1","title":"SeqAlign3DVG: A Sequence-Aligned Benchmark and Voxel Reasoning Framework for 3D Visual Grounding","abstract":"Image-based 3D visual grounding is critical for embodied agents, yet existing benchmarks suffer from loose text-observation alignment and neglect temporal ordering. We introduce SeqAlign3DVG, a novel benchmark dedicated to temporally ordered and strictly observation-aligned image-based 3D visual grounding. Unlike prior works using order-agnostic views or global point clouds, SeqAlign3DVG ensures all expressions are human-verified and strictly grounded in the provided RGB observations (single frames or ordered observation sequences). It comprises 9,622 single-view and 14,493 sequence samples featuring rich descriptions, complex relations, and multi-instance ambiguities. To tackle this benchmark, we propose a unified voxel-based pipeline featuring Relevance-Ordered Voxel Memory (ROVM) and Progressive Language-Voxel Fusion (PLVF). ROVM dynamically ranks and aggregates multi-view evidence via a conservative memory to mitigate noisy observations, while PLVF performs coarse-to-fine spatial-linguistic reasoning for precise disambiguation. Our approach achieves state-of-the-art performance under the depth-free protocol, significantly improving localization for targets defined by complex relations and appearance cues.","authors":["Yi Zhang","Yi Wang","Yueting Wu","Kaiyue Yang","Yuejiao Su","Lap-Pui Chau"],"published":"2026-08-31T08:38:29Z","updated":"2026-08-31T08:38:29Z","abstract_url":"https://arxiv.org/abs/2608.30451v1","html_url":"https://arxiv.org/html/2608.30451v1","pdf_url":"https://arxiv.org/pdf/2608.30451v1.pdf","matched_keywords":["3d","agent","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30450v1","title":"FlowVVTON: Flow-Guided Mask-Free Video Virtual Try-On","abstract":"Video virtual try-on aims to transfer a target garment onto a moving person across video frames. Current methods rely on human parsing masks or pose keypoints that frequently fail under large motions and occlusions, causing boundary artifacts and temporal inconsistency. A further limitation is that most approaches rely solely on attention mechanisms for temporal modeling, providing no explicit motion supervision. We propose FlowVVTON, a mask-free framework that eliminates parsing mask dependency entirely. Optical flow is used solely as a training-time supervision signal: a flow-warped latent loss, applied across all layers of the generation model, enforces multi-scale temporal consistency by aligning adjacent-frame features under explicit physical motion constraints. A two-stage training strategy establishes mask-free spatial alignment before introducing flow-guided temporal supervision. Experiments on TikTokDress show that FlowVVTON outperforms baselines by substantial margins, particularly in temporal consistency (5.7$\\times$ VFID-R improvement over SwiftTry), while requiring no segmentation masks, pose keypoints, or region annotations at any stage.","authors":["Shengyao Chen","Xianbing Sun","Liqing Zhang","Jianfu Zhang"],"published":"2026-08-31T08:37:47Z","updated":"2026-08-31T08:37:47Z","abstract_url":"https://arxiv.org/abs/2608.30450v1","html_url":"https://arxiv.org/html/2608.30450v1","pdf_url":"https://arxiv.org/pdf/2608.30450v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30428v1","title":"Lies We Can See: Joint Verbal and Non-Verbal Deception by VLM Agents in Embodied Social Interactions","abstract":"Strategic deception by LLM and VLM agents has emerged as a central AI alignment and safety concern. Social-deduction games (where each player holds a hidden role and communicates with others to deduce identities) serve as the canonical testbed, particularly in multi-agent settings. Existing testbeds, however, are text-only and run on a single fixed agent configuration, missing the non-verbal sensorimotor channels treated as core by deception taxonomies and leaving it ambiguous whether an observed behavior reflects the underlying model or the surrounding harness. We introduce MineAmongUs, a 3D multimodal Among Us sandbox where imposter agents must deceive crewmates through joint verbal and non-verbal action. We also propose ARIA, a configurable VLM-agent harness that exposes five cognitive-component ablation axes; and an atom- and arc-level annotation scheme grounded in deception taxonomies and operationalized at scale by an LLM-as-a-Judge reaching near-human atom-labeling agreement. Empirical results show that VLM agents pursue imposter wins through joint verbal and non-verbal deception, with non-verbal channels emerging as the more decisive winning contributors across both harness ablation and cross-VLM evaluation. Taken together, our work opens a new path for embodied VLM-agent alignment research.","authors":["Jaewoo Ahn","Junseo Kim","Hyunseo Kim","Heeseung Yun","Jaehyeon Son","Zsolt Kira","Gunhee Kim"],"published":"2026-08-31T08:24:29Z","updated":"2026-08-31T08:24:29Z","abstract_url":"https://arxiv.org/abs/2608.30428v1","html_url":"https://arxiv.org/html/2608.30428v1","pdf_url":"https://arxiv.org/pdf/2608.30428v1.pdf","matched_keywords":["3d","agent","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30423v1","title":"ObjectSplat: Improving Mesh Fidelity and Interactivity for 3D Scenes via Object-Level Mesh Splatting","abstract":"Splatting-based algorithms reconstruct photorealistic, real-time-renderable, and mesh-exportable 3D scenes from regular images, but they represent a scene as a single monolithic field. Therefore, the reconstruction has no object-level structure, leaving it infeasible for downstream editing or interaction. Moreover, regions that are never directly observed in the input scans are contaminated by the surrounding texture and left uncorrected, capping both mesh fidelity and novel-view synthesis. We propose a decompose-before-reconstruct approach: we segment the instances out of every frame, consider the remaining as background and inpaint it, reconstruct each instance and the background independently with mesh splatting, and compose them into a single scene. Our method significantly improves mesh fidelity (over a 5\\% gain in F-score) and novel-view synthesis, while supporting object-wise modifiability and interactivity. The code will be made publicly available.","authors":["Minhas Kamal","Hiranya Garbha Kumar","Mahedi Kamal","Balakrishnan Prabhakaran"],"published":"2026-08-31T08:20:53Z","updated":"2026-08-31T08:20:53Z","abstract_url":"https://arxiv.org/abs/2608.30423v1","html_url":"https://arxiv.org/html/2608.30423v1","pdf_url":"https://arxiv.org/pdf/2608.30423v1.pdf","matched_keywords":["3d","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30388v1","title":"PRISM: Predictive Recomposition via Semantic Latent Decomposition for View-invariant Video Representation Learning","abstract":"Cross-view video representation learning aims to capture viewpoint-invariant action semantics despite substantial appearance changes across egocentric and exocentric videos. However, existing methods encode each video as a unified embedding, where view-invariant and view-variant semantics inevitably entangle under co-occurrences - a failure mode we show persists even in cross-view methods explicitly trained for view-invariance. Our key insight is that a view-invariant feature is truly disentangled when it can be sufficiently recomposed with an arbitrary view-variant feature while preserving their independent semantics. Building on this, we propose PRISM, that decomposes video into view-invariant and view-variant latents and recompose them under language supervision encouraging clean decomposition of the two streams. PRISM achieves state-of-the-art results on EgoExo4D, EgoExoLearn, AE2, even surpassing in-domain models under zero-shot setting. Code is available at https://github.com/litcoderr/prism.","authors":["Youngchae Chee","Hosu Lee","Sungjune Park","Junho Kim","Yong Man Ro"],"published":"2026-08-31T07:43:02Z","updated":"2026-08-31T07:43:02Z","abstract_url":"https://arxiv.org/abs/2608.30388v1","html_url":"https://arxiv.org/html/2608.30388v1","pdf_url":"https://arxiv.org/pdf/2608.30388v1.pdf","matched_keywords":["video","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30371v1","title":"MCSeg: Pre-training and Fine-tuning Volumetric Pyramid Transformer for Multi-modal Cardiac Image Segmentation","abstract":"Automatic cardiac image segmentation is pivotal for diagnosing and treating cardiac diseases. In this work, we introduce MCSeg, a volumetric transformer-based network tailored for multi-modal cardiac segmentation. To overcome the architectural mismatch inherent in existing hybrid networks, we propose a novel Scaling Feature Pyramid (SFP). Unlike conventional skip connections, the SFP effectively bridges the single-scale 3D Vision Transformer (ViT) encoder and the multi-scale CNN decoder by transforming the ViT's output into a hierarchical feature pyramid, ensuring that global contextual information is effectively leveraged. For the training paradigm, the ViT encoder first undergoes self-supervised pre-training via masked image modeling. Subsequently, the network is fine-tuned on downstream tasks, during which a regional mutual information (RMI) loss is integrated to improve boundary segmentation accuracy. In experiments, MCSeg consistently outperforms eleven SOTA methods on CT dataset ImageCHD, multi-modal dataset MM-WHS, MRI dataset HVSMR-2.0 and MSD Heart, highlighting the effectiveness of our MCSeg for multi-modal cardiac segmentation tasks. Furthermore, MCSeg's superior performance in few-shot experiment showcases its significant potential in adapting to limited data scenarios. Codes and pre-trained ViT-B weights are open-sourced at https://openi.pcl.ac.cn/OpenMedIA/MCSeg","authors":["Zhiyu Ye","Hairong Zheng","Tong Zhang"],"published":"2026-08-31T07:27:10Z","updated":"2026-08-31T07:27:10Z","abstract_url":"https://arxiv.org/abs/2608.30371v1","html_url":"https://arxiv.org/html/2608.30371v1","pdf_url":"https://arxiv.org/pdf/2608.30371v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30344v1","title":"Proximity3D: Shape from Capacitive Proximity on Sensing Manifold","abstract":"Most shape reconstruction methods assume measurements defined over planar sensing domains, such as RGB images or depth maps. In this paper, we use a curved capacitive textile as a shape sensor, treating its surface as a non-planar sensing manifold. Each scan is represented as a capacitive proximity field on this manifold, induced by the interaction between the curved electrode layout and nearby object geometry. We introduce a multi-view feedforward reconstruction model that aggregates these fields across known sensor views and recovers the observed object shape. Simulated and physical experiments demonstrate robust reconstruction from capacitive proximity signals acquired on curved sensing surfaces, pointing toward a new route to robotic near-field geometric awareness via embodied sensing.","authors":["Hao Chen","Chenming Wu","Chun Ping Lam","Xiangjia Chen","Guoxin Fang","Charlie C. L. Wang","Yeung Yam","Juncong Lin","Chengkai Dai"],"published":"2026-08-31T07:00:19Z","updated":"2026-08-31T07:00:19Z","abstract_url":"https://arxiv.org/abs/2608.30344v1","html_url":"https://arxiv.org/html/2608.30344v1","pdf_url":"https://arxiv.org/pdf/2608.30344v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30342v1","title":"CapFrame: Text-Instructed Viewpoint Grounding in 3D Gaussian Scenes via Geometric Pseudo Labels","abstract":"3D Gaussian Splatting (3DGS) enables photorealistic real-time novel view synthesis, yet placing a virtual camera to capture a desired frame remains largely manual. Existing language-guided approaches in 3D scenes mainly focus on object-centric grounding, determining what to observe but rarely controlling how it should appear in a single frame, such as subject orientation or frame layout. To address this limitation, we introduce a new task, Text-Instructed Viewpoint Grounding (TIVG), which aims to identify a 6-DoF camera pose in a 3D Gaussian scene whose rendered frame aligns with a text instruction. To solve this task, we propose CapFrame, a partially differentiable framework that converts language into geometric pseudo labels for camera pose optimization. CapFrame follows a Retrieve-Translate-Refine pipeline: it retrieves relevant views and ranks them through a Question-Evaluation process with MLLMs, translates the instruction into orientation and layout pseudo labels, and refines the camera pose via differentiable optimization with layout and orientation losses in 3DGS. Experiments on 38 real-world scenes with 135 instructions indicate that CapFrame produces viewpoints better aligned with texts than heuristic viewpoint search and adapted trajectory generation baselines, validated by VLM metrics, MLLM judges, and user studies. Code is available at: https://github.com/jirongli/CapFrame","authors":["Jirong Li","Satoshi Ikehata","Shuhei Kurita","Ikuro Sato"],"published":"2026-08-31T06:56:32Z","updated":"2026-08-31T06:56:32Z","abstract_url":"https://arxiv.org/abs/2608.30342v1","html_url":"https://arxiv.org/html/2608.30342v1","pdf_url":"https://arxiv.org/pdf/2608.30342v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30307v1","title":"ScenePilot: Grow-and-Repair Policy for Text-Driven 3D Indoor Scene Generation","abstract":"Text-driven 3D indoor scene generation has advanced from dataset-bound layout modeling to open-vocabulary synthesis with large language and vision-language models. Yet existing methods remain limited: one-pass generators often yield geometrically invalid layouts, heavy post-hoc optimization is costly and unstable, and prompt-only planners lack reusable layout priors for functional grouping and object relations. We propose \\textbf{ScenePilot}, a retrieval-augmented \\textbf{Grow-and-Repair} framework that formulates scene generation as prior-guided incremental growth with learned rectification. Given a prompt, the Hierarchical Retrieval-Augmented Planning (HRAP) module retrieves room-, group-, and anchor-level layout priors to support functional group planning. A text-driven base generator then inserts object groups sequentially, while the Reinforcement Multimodal Repair (RMR) module performs lightweight local correction after each insertion and a final global repair after completion. To train this policy, we construct \\textbf{SceneReverse-17k}, a repair-trajectory dataset built by perturbing high-quality 3D scenes in position, rotation, and scale, then using inverse operations as executable rectification targets. The policy predicts structured \\emph{move--rotate--scale} actions from rendered views, scene state, retrieved priors, and edit history. By combining HRAP with RMR, ScenePilot offers an efficient alternative to one-shot generation and heavy full-scene optimization, improving physical plausibility, functional coherence, and controllability while preserving diversity.","authors":["Jiawei Zhang","Hongsong Wang","Pan Zhou"],"published":"2026-08-31T06:22:11Z","updated":"2026-08-31T06:22:11Z","abstract_url":"https://arxiv.org/abs/2608.30307v1","html_url":"https://arxiv.org/html/2608.30307v1","pdf_url":"https://arxiv.org/pdf/2608.30307v1.pdf","matched_keywords":["retrieval","3d","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30294v1","title":"Dynamic Hub-and-Spoke Memory for Streaming Video Understanding","abstract":"Streaming video understanding requires answering questions at arbitrary times over a continuously growing visual stream. The central challenge is to compactly remember long-range history while effectively retrieving question-relevant evidence. We propose Dynamic Hub-and-Spoke Memory (D-HSM), a training-free framework that represents distant history as structured textual memory while preserving the recent frames as visual tokens for fine-grained perception. Specifically, D-HSM turns selected historical video chunks into typed textual observations and stores them in an entity-centered hub-and-spoke memory, with entities as hubs and related evidence as spokes. When answering a question, D-HSM dynamically retrieves a compact question-aware memory subset, expands it through hub-and-spoke links, and combines it with the recent visual window for frozen-VLM answer prediction. Extensive experiments on both streaming and long video benchmarks show that D-HSM consistently and substantially improves VLM backbones and outperforms other state-of-the-art online and offline video understanding baselines.","authors":["Xinru Jiang","Lin Zhao","Xi Xiao","Yunbei Zhang","Janet Wang","Chenrui Ma","Haolin Li","Yanzhi Wang","Yifan Gong","Octavia Camps"],"published":"2026-08-31T06:02:28Z","updated":"2026-08-31T06:02:28Z","abstract_url":"https://arxiv.org/abs/2608.30294v1","html_url":"https://arxiv.org/html/2608.30294v1","pdf_url":"https://arxiv.org/pdf/2608.30294v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30281v1","title":"SELECT: SELEctive Context Transfer for Class-Incremental Semantic Segmentation","abstract":"Class-Incremental Semantic Segmentation (CISS) is fundamentally challenged by catastrophic forgetting and background shift, where learning new concepts degrades performance on previously seen classes. While existing methods attempt to balance stability (retaining old knowledge) and plasticity (learning new knowledge), they often fail to leverage prior knowledge effectively. These approaches typically rely on indiscriminate knowledge transfer or ambiguous initializations, which can dilute crucial semantic information. To overcome this limitation, we propose SELECT, a novel approach for Selective Context Transfer, which instead grounds each new class in a small set of semantically similar past classes. Its core is a Context Transfer Attention mechanism that aggregates the learned tokens from similar classes into a structured initialization for the new class. To ensure this transfer does not corrupt the borrowed representations, we add a controlled noise perturbation and a margin-based context-transfer loss that enforces separation between the new class token and its source tokens. Extensive experiments on Pascal VOC and ADE20K show that SELECT consistently outperforms prior work, achieving mIoU of 2.2% on VOC and 2.8% on ADE, providing an effective handle on the stability-plasticity dilemma. Code is available at https://github.com/avigupta2798/SELECT.","authors":["Avi Gupta","Saurabh Yadav","Koteswar Rao Jerripothula","Tammam Tillo"],"published":"2026-08-31T05:50:10Z","updated":"2026-08-31T05:50:10Z","abstract_url":"https://arxiv.org/abs/2608.30281v1","html_url":"https://arxiv.org/html/2608.30281v1","pdf_url":"https://arxiv.org/pdf/2608.30281v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30279v1","title":"Motion-Saliency Complementary Masked Modeling for Point Cloud Video Understanding","abstract":"Point cloud video representation learning is crucial for 3D dynamic scene understanding. In this paper, we propose MoSaiC, a novel Motion-Saliency Complementary masked modeling framework for self-supervised point cloud video representation learning. MoSaiC couples three components: Curriculum Motion-Saliency Masking (CMSM), which guides the masking process toward motion-salient tokens under a curriculum schedule; Normal-Flow Motion (NFM) modeling, which supervises the local rigid rotation of each token in the Lie algebra so(3) as an explicit geometric motion target; and Cross-view Token Consistency Prediction (CTCP), which enforces consistency between two complementary masked views at the token level. Together, these components allow MoSaiC to effectively capture both appearance and motion dynamics. Extensive experiments on multiple downstream tasks, including action recognition, temporal action segmentation, and point-level semantic segmentation, demonstrate the effectiveness of our approach.","authors":["Wei Wang","Yiding Sun","Yuyan Wang","Zhuoyue Zhang","Zhengqiao Li","Dongfu Yin","Chen Li"],"published":"2026-08-31T05:48:33Z","updated":"2026-08-31T05:48:33Z","abstract_url":"https://arxiv.org/abs/2608.30279v1","html_url":"https://arxiv.org/html/2608.30279v1","pdf_url":"https://arxiv.org/pdf/2608.30279v1.pdf","matched_keywords":["video","3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30263v1","title":"Centering before Pruning: Lightweight Geometry Correction for Diversity-Based Visual Token Pruning in LVLMs","abstract":"Large vision-language models (LVLMs) incur substantial inference costs due to their long and highly redundant visual-token sequences. Diversity-based pruning mitigates this cost by selecting token subsets based on pairwise cosine similarity. We find, however, that similarities between raw visual tokens are strongly concentrated in the positive range, limiting their ability to distinguish non-redundant tokens. A natural way to improve this resolution is to center token features before computing cosine similarity. Centering indeed reveals a substantially richer pairwise structure, yet unexpectedly degrades pruning performance when used alone. We show that this apparent contradiction arises because the raw geometry does more than represent pairwise diversity: it also implicitly favors globally distinctive tokens, which tend to contain semantically informative content. Centering better resolves subset diversity but loses this useful token-wise preference, revealing that diversity and distinctiveness are entangled in the raw geometry. Based on this analysis, we propose the \\textbf{Cen}tered Geometry \\textbf{Prune}r (Cen-Prune), which measures subset diversity using centered cosine similarity while retaining raw-space distinctiveness as a complementary token-wise preference. This lightweight, plug-and-play correction leaves the underlying selection mechanism unchanged and incurs negligible computational overhead. Extensive experiments across multiple image- and video-understanding benchmarks and LVLM architectures demonstrate that Cen-Prune provides robust improvements in overall performance across existing diversity-based pruners.","authors":["Shunjie Wen","Jaeyeon Lee","Dong-Wan Choi"],"published":"2026-08-31T05:13:29Z","updated":"2026-08-31T05:13:29Z","abstract_url":"https://arxiv.org/abs/2608.30263v1","html_url":"https://arxiv.org/html/2608.30263v1","pdf_url":"https://arxiv.org/pdf/2608.30263v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30247v1","title":"OPUS: A Simple yet Effective Unified Framework for Open-Vocabulary Detection","abstract":"Recent unified open-vocabulary detection (OVD) supports heterogeneous prompts, including text queries, visual exemplars, and their combinations, but often rely on increasingly complex designs such as heavy cross-modal fusion, staged training, and iterative annotation pipelines. We revisit whether such complexity is necessary in the era of stronger foundation models. Our finding is that unified OVD can be made substantially simpler with semantic-rich visual representations and scalable grounding supervision. We present OPUS (\\textbf{O}pen-vocabulary, \\textbf{P}rompt-\\textbf{U}nified, \\textbf{S}imple), a unified detector supporting text, interactive visual, generic visual, and mixed prompting within one framework. OPUS adopts a simple three-part design. Its model architecture combines a semantic-rich visual encoder, built on a DINOv3-ConvNeXt-B backbone with efficient hybrid encoding, with a prompt-aware decoder that avoids prompt-specific branches for unified prompt reasoning. OPUS is trained with a one-stage text-visual training strategy with Instance-level Contrastive Alignment (ICA), and is supported by a SAM3-based single-pass data engine for heterogeneous grounding supervision. Experiments on COCO, LVIS-minival, and ODinW35 show that OPUS achieves state-of-the-art Visual-I performance, reaching 68.1/69.2/54.7 AP, while maintaining balanced Text and Visual-G accuracy. OPUS also turns mixed prompting from interference into complementarity, improving over text or visual prompt alone. These results show that simplicity and strong unified prompting capability can be achieved together.","authors":["Xiaoyan Wei","Zhimin Yao","Ruilin Yang","Wei Zhang","Yong Dai","Yi Zhang","Wei Ge"],"published":"2026-08-31T04:57:12Z","updated":"2026-08-31T04:57:12Z","abstract_url":"https://arxiv.org/abs/2608.30247v1","html_url":"https://arxiv.org/html/2608.30247v1","pdf_url":"https://arxiv.org/pdf/2608.30247v1.pdf","matched_keywords":["representation","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30241v1","title":"PaperBanana-Interact: Scientific Diagram Refinement with Multi-Turn Human Feedback","abstract":"Recent efforts have aimed to automate scientific diagram generation from paper content (Lin et al., 2026; Zhu et al., 2026a). However, fully satisfying an author's visual and communicative preferences in a single turn is challenging: in our formative user study (N = 14), all participants requested further revisions after viewing an initial draft, and 86% of them rated the refined diagrams as more satisfactory. Despite the clear demand, the multi-turn workflow remains largely underexplored. To bridge this gap, we present MTPaperBananaBench, a benchmark for multi-turn diagram generation containing 292 images annotated with 3,518 user requirements. To reduce expensive human studies and enable scalable benchmarking, we construct a user simulator that, at each turn, identifies unsatisfied requirements and converts k of them into natural language feedback. Evaluating both requirement satisfaction and overall diagram quality reveals two key failure modes shared across baseline multiturn systems: (1) quality drift, where diagram quality progressively declines over turns, and (2) forgetting, where previously implemented features are lost in subsequent turns. To address these issues, we introduce PaperBanana-Interact, a multi-agent system that refines diagrams via an internal critique-and-refine loop. PaperBanana-Interact consistently improves rather than degrades diagram quality across turns, outperforming baselines by 11.9-18.6 points in quality score and reducing forgetting by 3.7-6.2 points.","authors":["Xueqing Wu","Ashwin Balasubramanian","Bingxuan Li","Dawei Zhu","Kai-Wei Chang","Yale Song","Yiwen Song","Rui Meng","Tomas Pfister","Nanyun Peng"],"published":"2026-08-31T04:52:32Z","updated":"2026-08-31T04:52:32Z","abstract_url":"https://arxiv.org/abs/2608.30241v1","html_url":"https://arxiv.org/html/2608.30241v1","pdf_url":"https://arxiv.org/pdf/2608.30241v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30237v1","title":"Motus2: A Self-Evolving General World Model for Dexterous Manipulation","abstract":"General embodied agents should perceive, predict, act, evaluate, and improve within a unified system. World models have shown great promise in building such agents, yet existing models typically append an action output head to a world simulator, without coupling them into a closed decision-and-learning loop for policy improvement. We present Motus2, a self-evolving general world model for dexterous manipulation. Motus2 advances world modeling through model scaling and data scaling. For model scaling, a single model with shared weights exposes three control interfaces: a policy (world-action model), a simulator (action-conditioned world model), and an evaluator (value model). The policy proposes candidate action chunks, the simulator predicts their visual consequences, and the evaluator assesses the predicted outcomes. Their coupling forms a closed decision-and-learning loop for policy improvement. This formulation uses curated expert demonstrations for action learning, while failed and suboptimal interactions provide valuable evidence for dynamics modeling and value learning. For data scaling, Motus2 progresses from large-scale monocular egocentric data to synchronized stereo egocentric data, followed by robot-domain adaptation with robot trajectories and supplementary human-robot alignment data. Motus2 further studies global-autoregressive and hybrid-memory extensions of its sliding-window context, adds tactile feedback for contact-aware control, and is instantiated on a fully biomimetic platform with stereo vision, dual arms, dual dexterous hands, and tactile sensing. Together, egocentric data scaling and closed-loop general world model scaling provide a general path toward self-evolving dexterous manipulation.","authors":["Hongzhe Bi","Zihao Zhou","Yihang Tang","Jingrui Pang","Shuhe Huang","Haitian Liu","Runqing Wang","Shuai Huang","Yichen Wang","Yiming Cheng","Ruowen Zhao","Zhenghua Li","Hengkai Tan","Xiaolong Liu","Jinhui Wan","Jiabao Liu","Min Zhao","Fan Bao","Jun Zhu"],"published":"2026-08-31T04:44:33Z","updated":"2026-08-31T04:44:33Z","abstract_url":"https://arxiv.org/abs/2608.30237v1","html_url":"https://arxiv.org/html/2608.30237v1","pdf_url":"https://arxiv.org/pdf/2608.30237v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30233v1","title":"Semantic-Spatial Discriminability Enhancement for Generalized Visual Grounding","abstract":"Generalized Visual Grounding (GVG) task aims to localize targets in an image based on referring expressions, extends the classical visual grounding paradigm by integrating multi-target and non-target scenarios. Previous methods typically rely on global semantic matching or coarse-grained region interactions for localization, where the discriminative cues are primarily derived from sentence-level semantics or regional context. In complex multi-target scenarios, such approaches tend to confuse visually similar targets, making it difficult to establish stable instance-level decision boundaries. To address these limitations, this paper proposes a novel Semantic-Spatial Discriminability Enhancement (SSDE) framework for generalized visual grounding, which aims to enhance the discriminative ability on fine-grained semantics and spatial localization, improving both cross-modal understanding and instance-level grounding. Specifically, to enhance the semantic discriminability of query representations at the fine-grained level, we propose a Semantic Discriminability Enhancement (SeDE) module, which leverages spatially guided cross-attention to disentangle fine-grained target-relevant visual attributes and integrates them with the textual subject semantics. Furthermore, to strengthen the spatial discriminability of the referred targets, we introduce a Spatial Discriminability Enhancement (SpDE) module, which models an instance center density map to characterize the spatial distribution of targets, and explicitly constructs instance separation structures in the spatial domain by employing them as an auxiliary supervision signal. Extensive experiments show that SSDE achieves superior performance on ten datasets across both classic and generalized visual grounding tasks.","authors":["Kaiyan Lei","Xu-Yao Zhang"],"published":"2026-08-31T04:37:36Z","updated":"2026-08-31T04:37:36Z","abstract_url":"https://arxiv.org/abs/2608.30233v1","html_url":"https://arxiv.org/html/2608.30233v1","pdf_url":"https://arxiv.org/pdf/2608.30233v1.pdf","matched_keywords":["representation","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30218v1","title":"Amortized Anchor Refinement for Deployable Continuous-Time 4D Gaussian Reconstruction","abstract":"Continuous-time 4D reconstruction remains impractical on standalone XR headsets. Per-scene optimization demands deployment-infeasible compute, and lower budgets cause collapse rather than degrade gradually. Feed-forward prediction is fast, but struggle to recover scene-specific detail. We present Amortized Anchor Refinement, which uses a frozen backbone to predict an initial Gaussian representation and a short optimization to specialize it under a fixed compute budget, with a capacity floor preserving representational density. A training-free stage then applies a persistent-homology constraint to prune unstable Gaussians while preserving topologically persistent structures, and streams the resulting trajectories directly as scene flow. On the Stage-Capture benchmark, Amortized Anchor Refinement achieves 24.31$\\pm$2.22dB, while our deployment experiments demonstrate reconstruction within the target budget on a single consumer GPU and playback on a standalone XR headset.","authors":["Jingong Chen","Qingwen Zhang","Sanghyeon Jun","Chulwoo Pack","Kyle Gao","Kwanghee Won"],"published":"2026-08-31T04:04:04Z","updated":"2026-08-31T04:04:04Z","abstract_url":"https://arxiv.org/abs/2608.30218v1","html_url":"https://arxiv.org/html/2608.30218v1","pdf_url":"https://arxiv.org/pdf/2608.30218v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30213v1","title":"Towards a Joint Khmer Text Recognition and Word Segmentation","abstract":"Text recognition, or extracting electronic text from document images, has been indispensable for knowledge retrieval tasks, such as retrieval-augmented generation (RAG). For Khmer, extracted text is subject to an extra word segmentation step, as Khmer does not use any visible word delimiters to denote word boundaries. Thus, a recognition-then-segmentation pipeline for Khmer requires two separate sequential models; this is not only error-prone but also adds significant latency for large-scale document processing. This paper proposes a novel joint Khmer text recognition and word segmentation framework in a unified model. The proposed model, using a connectionist-temporal-classification (CTC) decoder for fast, parallel decoding, can be instructed to recognize Khmer text with ($b=1$) and without ($b=0$) word segmentation. Experimental results on different benchmark datasets of different document modalities (document, scene, and handwritten images) show that the proposed model can not only recognize characters in document images but also locate word boundaries, removing the need for an extra word segmentation step in a conventional sequential pipeline.","authors":["Marry Kong","Rina Buoy","Sovisal Chenda","Nguonly Taing","Masakazu Iwamura","Koichi Kise"],"published":"2026-08-31T03:53:25Z","updated":"2026-08-31T03:53:25Z","abstract_url":"https://arxiv.org/abs/2608.30213v1","html_url":"https://arxiv.org/html/2608.30213v1","pdf_url":"https://arxiv.org/pdf/2608.30213v1.pdf","matched_keywords":["retrieval"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"}],"favorites":[],"latest":{"generated_at_utc":"2026-09-01T05:58:30+00:00","category":"cs.CV","keywords":["video","retrieval","3d","agent","representation","instance","multimodal","diffusion"],"fetch_window_hours":72,"daily_window_hours":30,"match_count":73,"new_or_recent_papers":[{"id":"2608.31159v1","title":"BRF-GS: Hyperspectral Bidirectional Reflectance Factor Modeling and Image Generation Based on 3D Gaussian Splatting","abstract":"The bidirectional reflectance factor (BRF) characterizes the directional radiative properties of terrestrial surfaces. However, existing three-dimensional (3D) radiative transfer models require complex scene construction and computationally intensive radiative transfer solvers, limiting efficient generation of multi-angle hyperspectral reflectance imagery. 3D Gaussian Splatting (3DGS) offers an efficient framework for neural scene representation and novel view synthesis, but its low-order spherical harmonics representation is insufficient for complex directional reflectance, while the high dimensionality and inter-band quality differences of hyperspectral data introduce additional challenges. To address these challenges, we propose BRF-GS, a 3DGS-based framework for BRF modeling and hyperspectral reflectance image generation. BRF-GS introduces a hybrid BRDF-driven kernel to represent complex directional reflectance, selects geometry-reliable spectral bands for robust 3D scene initialization, and adopts a two-stage training strategy that decouples geometry optimization from spectral modeling. We further construct the AIR-BRF dataset, a multi-angle hyperspectral directional reflectance dataset comprising three scenes with diverse natural and artificial targets. Experiments demonstrate that BRF-GS achieves superior spatial and spectral fidelity and accurately reproduces characteristic view-dependent BRF responses. The proposed framework provides an efficient data-driven approach for BRF modeling and multi-angle hyperspectral reflectance image generation in remote sensing scenes.","authors":["Yiling Yao","Wenjuan Zhang","Bowen Wang","Bocheng Li","Wentao Song","Bing Zhang"],"published":"2026-08-31T17:56:57Z","updated":"2026-08-31T17:56:57Z","abstract_url":"https://arxiv.org/abs/2608.31159v1","html_url":"https://arxiv.org/html/2608.31159v1","pdf_url":"https://arxiv.org/pdf/2608.31159v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":1719,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d, representation 相关；摘要显示其主要贡献为：The bidirectional reflectance factor (BRF) characterizes the directional radiative properties of terrestrial surfaces. However, existing three-dimensional (3D) radiative transfer models require complex scene construction and computationally intensive radiativ...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"abstract","created_at":"2026-09-01T05:58:31+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.31113v1","title":"BLARM: Animating 3D Objects from Video via Blending Latent Rigid Motion Primitives","abstract":"We introduce BLARM, a feed-forward method for video-driven 3D mesh animation. Given a monocular video and a static object mesh, BLARM predicts a temporally coherent animated mesh whose motion follows the video. Rather than relying on explicit rigs or directly regressing high-dimensional vertex motion, we represent animation using a compact set of learned, time-varying rigid motion components and time-invariant vertex-to-component skinning weights. This yields a low-dimensional deformation space without requiring skeletons, cages, skinning weights, or rig annotations. Our architecture conditions geometry-derived deformation latents on video features through factorized spatial-temporal attention, then decodes rigid transformations blended by predicted skinning weights. Trained with trajectory reconstruction, entropy regularization, and motion-aware contrastive learning, BLARM produces accurate and temporally stable animations while recovering compact, interpretable motion structure from monocular video.","authors":["Pradyumn Goyal","Yizhak Ben-Shabat","Hsueh-Ti Derek Liu","Haomiao Jiang","Snehasish Mukherjee","Kyle Spence","Mark Stauber","Evangelos Kalogerakis","Yunze Zeng"],"published":"2026-08-31T17:21:54Z","updated":"2026-08-31T17:21:54Z","abstract_url":"https://arxiv.org/abs/2608.31113v1","html_url":"https://arxiv.org/html/2608.31113v1","pdf_url":"https://arxiv.org/pdf/2608.31113v1.pdf","matched_keywords":["video","3d"],"source_used":"html","source_text_chars":74879,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d 相关；摘要显示其主要贡献为：We introduce BLARM, a feed-forward method for video-driven 3D mesh animation. Given a monocular video and a static object mesh, BLARM predicts a temporally coherent animated mesh whose motion follows the video. Rather than relying on explicit rigs or directly...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:31+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.31107v1","title":"VeriCam: A Verification Baseline for the Classification of Unknown Data","abstract":"The advent of foundation models have enabled a new era in zero-shot classification. Yet, key challenges persist. Despite their impressive generalization power that leverages the immense pre-training knowledge, both foundation models for image and text as well as vision-text hybrids lack the representational power needed for fine-grained, minutiae-based class separation that some real-world tasks require. To address the current gaps in the literature, we propose VeriCam, a pipeline designed to learn highly specialized features that enable classification of unknown classes in unseen data. VeriCam works by leveraging the representation power of image models trained for the verification task, where the model develops an intricate feature space that incorporates fine-grained details. By training a model to discriminate between pairs of images from the same and different classes, a relational graph is constructed, representing the class relationships between data points. We then present two approaches for graph clustering: a naive algorithm and a specific setup for the Leiden graph clustering algorithm. The pipeline is validated on the LPLCv2 dataset, which comprises real-world traffic surveillance images. We show that the dataset carries an inherent capture device bias that is posed as a generalization challenge for downstream License Plate recognition tasks such as OCR. As such, we dynamically identify capture devices with a label-agnostic approach, enabling the construction of a fair and unbiased benchmark. In the cross-device scenario, our pipeline reaches an F1-Score of 93.45 in the verification baseline and a V-Measure score of 80.13 in the clustering step. All code is publicly available at https://github.com/lmlwojcik/VeriCam","authors":["Lucas Wojcik","Gabriel E. Lima","Sergio M. Silva","Eduil Nascimento","David Menotti"],"published":"2026-08-31T17:12:59Z","updated":"2026-08-31T17:12:59Z","abstract_url":"https://arxiv.org/abs/2608.31107v1","html_url":"https://arxiv.org/html/2608.31107v1","pdf_url":"https://arxiv.org/pdf/2608.31107v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":34861,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：The advent of foundation models have enabled a new era in zero-shot classification. Yet, key challenges persist. Despite their impressive generalization power that leverages the immense pre-training knowledge, both foundation models for image and text as well...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:31+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.31106v1","title":"DreamX-Creator: Democratizing Native Audio-Video Generation at 2K Resolution","abstract":"Recent video generators often omit audio or synthesize it in a separate stage, limiting reciprocal modeling of visual dynamics and acoustic events. We present DreamX-Creator 1.0, a compact native joint audio-video generation system centered on a 7B generator. Conditioned on a first frame and a text prompt, the generator jointly denoises modality-specialized audio and video streams. The streams are processed independently in the first half of the network and coupled in the latter half through Gated Cross-Modal Attention, whose token- and head-wise output gates modulate each active cross-modal attention-head output. A unified Audio-Video Data System constructs and filters temporally coherent clips, produces structured multimodal annotations, and organizes clips into capability-oriented data pools. Progressive Joint Training comprises two audio-video pre-training stages followed by High-Quality Finetuning. Audio-Video Reinforcement Learning further post-trains the generator with Modality-Aware Multimodal Feedback that routes video-, audio-, and cross-modal feedback to the corresponding streams. For high-resolution output, our Autoregressive 1-Step 2K Refinement pipeline adapts a bidirectional multi-step teacher into an autoregressive multi-step refiner and distills it into a student requiring one denoising evaluation per temporal chunk. Overall, DreamX-Creator 1.0 achieves native, synchronized audio-video generation with performance competitive with state-of-the-art open-source systems. By releasing our compact 7B generator and 2K Refiner, we seek to democratize native audio-video generation and provide an accessible foundation for future research in unified audio-video generative modeling.","authors":["Jiashu Zhu","Yanhao Zheng","Ruitian Tian","Rujing Dang","Shen Zhang","Bingze Song","Jiachen Lei","Ruimin Lin","Jiahong Wu","Xiangxiang Chu"],"published":"2026-08-31T17:11:05Z","updated":"2026-08-31T17:11:05Z","abstract_url":"https://arxiv.org/abs/2608.31106v1","html_url":"https://arxiv.org/html/2608.31106v1","pdf_url":"https://arxiv.org/pdf/2608.31106v1.pdf","matched_keywords":["video","multimodal"],"source_used":"html","source_text_chars":85869,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, multimodal 相关；摘要显示其主要贡献为：Recent video generators often omit audio or synthesize it in a separate stage, limiting reciprocal modeling of visual dynamics and acoustic events. We present DreamX-Creator 1.0, a compact native joint audio-video generation system centered on a 7B generator....","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:31+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.31096v1","title":"One Adapter, Many Tasks: Task-Conditioned Feature Transformations for Continual Learning","abstract":"Class-incremental learning (CIL) requires a model to incrementally learn tasks that contain new classes without accessing earlier training data while preserving the ability to recognize all seen classes. Recently, pretrained-model-based approaches have become prevalent by adapting a frozen backbone with additional lightweight trainable modules. Existing methods, however, exhibit limitations: task-specific adapters learn explicit per-task representations but are parameter- and computation-inefficient, while LoRA-based merging methods combine per-task LoRA parameters into a single model whose static aggregated weights cause representation interference during inference. To address these problems, we present \\textbf{FACET}: task-conditioned \\textbf{F}e\\textbf{A}ture transformation with \\textbf{C}ondition\\textbf{E}d feature consis\\textbf{T}ency, achieving excellent parameter efficiency while producing highly discriminative features during inference. When continually trained on a task sequence, FACET learns a single shared adapter that employs a dynamic task-conditioned feature transformation, shaping the overall feature distribution of the adapter into a mixture of overlap-reduced task-specific components. On the other hand, we propose an efficient replay-free task-conditioned feature consistency loss, aiming to mitigate catastrophic forgetting of the learned mixture distribution in the adapter's feature space. Even when maintaining only a single adapter, FACET demonstrates robust scalability. On both very long task sequences (e.g., 200 tasks) and standard short task sequences (e.g., 20 tasks), our method achieves superior performance while using significantly fewer trainable parameters and GFLOPs. The code will be made open source upon acceptance.","authors":["Yunxiang Fu","Meng Lou","Yizhou Yu"],"published":"2026-08-31T17:03:45Z","updated":"2026-08-31T17:03:45Z","abstract_url":"https://arxiv.org/abs/2608.31096v1","html_url":"https://arxiv.org/html/2608.31096v1","pdf_url":"https://arxiv.org/pdf/2608.31096v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":74787,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：Class-incremental learning (CIL) requires a model to incrementally learn tasks that contain new classes without accessing earlier training data while preserving the ability to recognize all seen classes. Recently, pretrained-model-based approaches have become...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:31+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.31094v1","title":"Robust retinal biometrics for patient identity verification and retrieval across age and imaging devices","abstract":"Patient identity errors can compromise longitudinal medical records, research databases, and downstream clinical decisions. We present a retinal biometric system for verifying claimed identities and retrieving the correct identity from color fundus images. We trained a 512-dimensional metric-learning encoder combining a ConvNeXtV2 backbone with ArcFace and triplet losses on 227,004 images from 21,851 patient-eye identities in the Rotterdam Study, spanning multiple imaging devices and up to 32.6 years of follow-up. The system was evaluated on held-out Rotterdam Study data and externally on the UK Biobank and Age-Related Eye Disease Study (AREDS). Before evaluation, we used the model to screen for identity inconsistencies and manually adjudicated flagged images, identifying incorrect assignments in 0.588% of Rotterdam Study images, 0.259% of UK Biobank images, and 0.164% of AREDS images. In retrospective-only verification after removing near-duplicate images, the system achieved AUROCs of 0.9998, 0.9997, and 0.9998 in the Rotterdam Study, UK Biobank, and AREDS, respectively. For identity retrieval using only previously acquired images, Recall@1 was 99.7%, 97.2%, and 97.6%, respectively, from galleries averaging 4436-8510 identities; the correct identity appeared among the top five results in at least 98.6% of cases. Performance remained robust across imaging devices and long follow-up intervals, while lower image quality and inconsistent retinal fields accounted for most failures. These findings establish retinal anatomy as a durable biometric signal, useful for safeguarding the integrity of longitudinal imaging records.","authors":["Jose D. Vargas-Quiros","Dennis Bontempi","Jeroen Vermeulen","Bart Liefers","Sven Bergmann","Caroline C. W. Klaver"],"published":"2026-08-31T17:02:39Z","updated":"2026-08-31T17:02:39Z","abstract_url":"https://arxiv.org/abs/2608.31094v1","html_url":"https://arxiv.org/html/2608.31094v1","pdf_url":"https://arxiv.org/pdf/2608.31094v1.pdf","matched_keywords":["retrieval"],"source_used":"abstract","source_text_chars":1752,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 retrieval 相关；摘要显示其主要贡献为：Patient identity errors can compromise longitudinal medical records, research databases, and downstream clinical decisions. We present a retinal biometric system for verifying claimed identities and retrieving the correct identity from color fundus images. We...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"abstract","created_at":"2026-09-01T05:58:31+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.31074v1","title":"Real-Time Video Anomaly Detection Using YOLO Pose Estimation and CLIP-Based Semantic Scoring","abstract":"We propose a lightweight two-stage framework for real-time video anomaly detection. The first stage employs YOLO v11n-pose to detect persons and extract seventeen skeletal keypoints in a single forward pass. The second stage encodes each cropped person region through CLIP ViT-B/32 and computes cosine similarity against predefined textual descriptions of anomalous behaviors. This architecture eliminates the need for optical flow, standalone pose estimators, and density-based scoring modules. Experiments on CUHK Avenue, ShanghaiTech Campus, and a custom indoor dataset collected at Chulalongkorn University demonstrate an end-to-end throughput of approximately 51 FPS on an NVIDIA Titan XP GPU, a 3.36x speedup over the multi-feature baseline, while maintaining frame-level AUROC values of 89.26%, 70.26%, and 84.13%, respectively.","authors":["Vanodhya G. Warnasooriya","Amir Hajian","Watchara Ruangsang","Supavadee Aramvith"],"published":"2026-08-31T16:47:29Z","updated":"2026-08-31T16:47:29Z","abstract_url":"https://arxiv.org/abs/2608.31074v1","html_url":"https://arxiv.org/html/2608.31074v1","pdf_url":"https://arxiv.org/pdf/2608.31074v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":26069,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：We propose a lightweight two-stage framework for real-time video anomaly detection. The first stage employs YOLO v11n-pose to detect persons and extract seventeen skeletal keypoints in a single forward pass. The second stage encodes each cropped person region...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:31+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.31065v1","title":"Multimodal Shared Latent Representation of Narration, Microscope and iOCT Images for Phase Recognition in Vitreoretinal Surgery","abstract":"Surgical phase recognition is key to context-aware computer-assisted feedback in vitreoretinal procedures, yet the scarcity of synchronized multimodal intraoperative data, particularly microscope views and intraoperative OCT, limits approaches that aim to replicate the multimodal integration surgeons perform naturally. Surgical narration, by contrast, is abundantly available online and offers rich semantic supervision. Prior work has mainly explored pairwise contrastive learning (e.g., intraoperative OCT-microscope or microscope-narration), leaving the joint modeling of all three modalities largely unexplored. We introduce a framework that uses microscope views as a shared anchor to bridge surgical narrations and intraoperative OCT (iOCT) without requiring a fully synchronized tri-modal dataset, leveraging real microscope-narration videos and a synthetic dataset of synchronized microscope video and tool-aligned iOCT pairs. Contrastive alignment transfers structural priors from the synthetic domain to real videos lacking iOCT, and a dual-head MS-TCN++ integrates the resulting embeddings for joint macro- and micro-phase prediction. Evaluated on real vitreoretinal surgeries, our framework improves macro-phase recognition over a zero-shot baseline (mean F1 0.38 to 0.53) and provides an exploratory route to estimating fine-grained instrument-tissue measurements that are not directly observable in real microscope video alone; these micro-phase estimates are validated quantitatively on synthetic data and shown only qualitatively on real surgery. To our knowledge, this is the first work to unify microscope view, iOCT B-scans, and surgical narrations in a shared latent space for surgical phase recognition.","authors":["Onur Izmitlioglu","Shervin Dehghani","Tarek Ghannoum","Benedikt Schworm","Nassir Navab"],"published":"2026-08-31T16:41:07Z","updated":"2026-08-31T16:41:07Z","abstract_url":"https://arxiv.org/abs/2608.31065v1","html_url":"https://arxiv.org/html/2608.31065v1","pdf_url":"https://arxiv.org/pdf/2608.31065v1.pdf","matched_keywords":["video","representation","multimodal"],"source_used":"html","source_text_chars":34775,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, representation, multimodal 相关；摘要显示其主要贡献为：Surgical phase recognition is key to context-aware computer-assisted feedback in vitreoretinal procedures, yet the scarcity of synchronized multimodal intraoperative data, particularly microscope views and intraoperative OCT, limits approaches that aim to rep...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:31+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.31053v1","title":"Identity-Conditioned Latent Consistency Distillation for Face Synthesis","abstract":"Diffusion models have achieved strong results in high-fidelity image synthesis, but their iterative sampling process makes large-scale generation computationally expensive. This limitation is especially relevant when generating synthetic face datasets for face recognition, where a large number of subjects with many samples in different poses, expressions, ages, etc., are required. In this work, we show that identity-conditioned face synthesis can be performed at a substantially lower computational cost by a latent Consistency Model with few iterations, without compromising image quality. For training, we distill knowledge from the foundation Diffusion Model Arc2Face (teacher) by adapting its original text-to-image pipeline to an embedding-to-face setting, replacing textual prompts with ArcFace identity embeddings. Our distilled model (student) generates identity-conditioned face images with an average inference time of 0.4819 seconds per image, compared with 2.102 seconds for Arc2Face, resulting in a 4.36$\\times$ speed-up. Quantitative results, based on FID scores, show that the distilled model remains competitive with Arc2Face across all evaluation protocols. On 100k generated images, it achieves near-parity on CelebA (13.921 vs. 12.928) and outperforms the teacher on WebFace42M (9.317 vs. 9.802). Further evaluations on Synth-500 and AgeDB show a moderate performance gap for the former but comparable results for the latter. These results indicate that Arc2Face can be accelerated through task-specific latent consistency distillation while preserving high image quality for large-scale synthetic face generation. Our proposal is publicly available at https://github.com/UFPR-IPASP-PR/FaceRec-IdentityConsistency.","authors":["Tiago Kienen Chaves","Bernardo Biesseck","David Menotti"],"published":"2026-08-31T16:32:40Z","updated":"2026-08-31T16:32:40Z","abstract_url":"https://arxiv.org/abs/2608.31053v1","html_url":"https://arxiv.org/html/2608.31053v1","pdf_url":"https://arxiv.org/pdf/2608.31053v1.pdf","matched_keywords":["diffusion"],"source_used":"html","source_text_chars":37566,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 diffusion 相关；摘要显示其主要贡献为：Diffusion models have achieved strong results in high-fidelity image synthesis, but their iterative sampling process makes large-scale generation computationally expensive. This limitation is especially relevant when generating synthetic face datasets for fac...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:31+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.31033v1","title":"FaceSnap: Real-Time Personalized Lightstage Facial Performance Capture","abstract":"Lightstage facial capture produces production-quality digital humans, but it is resource and labor-intensive. Multi-camera setups, hours of computation, and massive data storage create bottlenecks that hinder iterative workflows. This paper introduces FaceSnap, an end-to-end framework that streamlines capture via a two-stage approach. First, a one-time multi-view optimization from a range-of-motion sequence builds a personalized model encoding both geometry and expression-dependent appearance. This model then enables high-fidelity real-time facial performance capture from a single monocular lightstage camera, with no further multi-view capture required. FaceSnap jointly estimates geometry and dynamic 4K texture at 83 fps. The 4K texture is produced by a novel personalized residual upscaler that recovers subject-specific high-frequency detail, which generic upscalers fail to capture. FaceSnap achieves geometric accuracy competitive with full per-frame multi-view optimization while outperforming feed-forward methods trained on production-quality 3D data, all from a single camera view. Finally, we introduce Multi4D, a public benchmark for evaluating 4D facial reconstruction methods in lightstage environments, enabling topology-invariant geometric comparison across methods.","authors":["Rukhshanda Hussain","Noé Artru","Emeline Got","Luiz Gustavo Hafemann","Alexandre Messier","Brandon Dearlove","Rafael M. O. Cruz","Abdallah Dib","Eric Granger"],"published":"2026-08-31T16:14:21Z","updated":"2026-08-31T16:14:21Z","abstract_url":"https://arxiv.org/abs/2608.31033v1","html_url":"https://arxiv.org/html/2608.31033v1","pdf_url":"https://arxiv.org/pdf/2608.31033v1.pdf","matched_keywords":["3d"],"source_used":"html","source_text_chars":78045,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d 相关；摘要显示其主要贡献为：Lightstage facial capture produces production-quality digital humans, but it is resource and labor-intensive. Multi-camera setups, hours of computation, and massive data storage create bottlenecks that hinder iterative workflows. This paper introduces FaceSna...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:31+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.31025v1","title":"Analytic Dynamics: Learning Physics-Grounded Representation for Fast Intrinsic Dynamics Inference from Monocular Videos","abstract":"Inferring object dynamics from visual observations is essential for intelligent agents to reason about and interact with the physical world, yet remains challenging due to the fundamental gap between visual evidence and intrinsic dynamics. Existing methods either rely on costly per-scene optimization, limiting efficiency and scalability, or directly map visual evidence to intrinsic dynamics without intermediate physical abstractions, making them prone to appearance and geometry shortcuts. To bridge this gap, we propose Analytic Dynamics, a feed-forward dynamics inference framework that introduces an intermediate physics-grounded dynamics representation between visual observations and intrinsic dynamics. Specifically, we leverage privileged physical states, including position, displacement, and deformation gradient fields, which are available in simulation, to learn a structured dynamics representation that is difficult to discover from visual observations alone. By aligning visual representations with this space, we equip visual models with a physics-grounded inductive bias, guiding them to capture dynamics-relevant patterns for material model classification and parameter regression. To facilitate this research, we develop a dynamics data generation pipeline and benchmark containing paired physical state trajectories, rendered videos, and ground-truth material models and parameters. Extensive experiments demonstrate that Analytic Dynamics achieves efficient, accurate, and generalizable dynamics inference from monocular videos.","authors":["Jailing Lin","Jikuan Zhang","Jianhua Sun"],"published":"2026-08-31T16:08:04Z","updated":"2026-08-31T16:08:04Z","abstract_url":"https://arxiv.org/abs/2608.31025v1","html_url":"https://arxiv.org/html/2608.31025v1","pdf_url":"https://arxiv.org/pdf/2608.31025v1.pdf","matched_keywords":["video","agent","representation"],"source_used":"html","source_text_chars":78137,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, agent, representation 相关；摘要显示其主要贡献为：Inferring object dynamics from visual observations is essential for intelligent agents to reason about and interact with the physical world, yet remains challenging due to the fundamental gap between visual evidence and intrinsic dynamics. Existing methods ei...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:31+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.31023v1","title":"SMG: Semantic Motion Graph for Monocular Dynamic Gaussian Splatting","abstract":"We study dynamic Gaussian Splatting from monocular videos. While recent advancements in dynamic Gaussian splatting offer a promising foundation for modeling dynamic scenes, they often overfit to the training views and fail under occlusion or complex scene motion due to the lack of reliable regularization signals in under-constrained regions. We propose Semantic Motion Graph (SMG), a novel approach models the Gaussian motion as the low-rank semantic motion. Our key insight is that the real-world scene motion is often structured by semantic coherence: regions that are spatially close and semantically related tend to exhibit consistent dynamics. To leverage this prior, we construct SMG to model structured motion of the scene. The Gaussian motion is driven by the motion of SMG nodes. We further observe that the uncertainty of Gaussian motion arises from both unreliable off-the-shelf priors and weakly constrained regions during optimization. SMG addresses this by using reliable graph nodes to guide the motion of nearby unreliable nodes. To evaluate dynamic Gaussian splatting under challenging real-world scenarios, we introduce a new multiview dataset collected under an ego-exo setup. Extensive experiments demonstrate that SMG achieves state-of-the-art performance on monocular dynamic Gaussian splatting across challenging real-world benchmarks. Project page: https://smg-gaussian.github.io/.","authors":["Haozheng Yu","Xinyu Yang","Rundong Luo","Jennifer J. Sun","Bharath Hariharan"],"published":"2026-08-31T16:06:18Z","updated":"2026-08-31T16:06:18Z","abstract_url":"https://arxiv.org/abs/2608.31023v1","html_url":"https://arxiv.org/html/2608.31023v1","pdf_url":"https://arxiv.org/pdf/2608.31023v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":61466,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：We study dynamic Gaussian Splatting from monocular videos. While recent advancements in dynamic Gaussian splatting offer a promising foundation for modeling dynamic scenes, they often overfit to the training views and fail under occlusion or complex scene mot...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:31+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.31022v1","title":"MNIST-PRO: MNIST is Back as a Partially Observable World for AI Agents","abstract":"AI agents in partially observable environments need to coordinate active sensing with working memory to maintain an evolving perceptual state. However, existing benchmarks struggle to isolate this perceptual-state construction and interpretation capability because they introduce physical and control complexities. We address this with MNIST-PRO, a benchmark that isolates agentic perception by converting MNIST digit recognition into a sequential, glimpse-based search task with lookback constraints. We evaluate ten multimodal models across four memory representations, including raw visual history, textual states, structured metric grid maps, and a consolidated visual canvas. While models excel under full observability, partial observability exposes a clear performance gap. We identify three distinct bottlenecks. First, perceptual-state construction and interpretation present a challenge, as agents struggle to integrate fragmented glimpses. Second, agents often stop exploring before they see the full sequence. Third, models often fail to revise early, incorrect beliefs even when faced with subsequent contradictory evidence. These results show that simply acquiring visual evidence is not enough. Agents must also be able to build and update a reliable perceptual state.","authors":["Vernon Toh","Navonil Majumder","Zhengyuan Liu","Nancy F. Chen","Soujanya Poria"],"published":"2026-08-31T16:05:39Z","updated":"2026-08-31T16:05:39Z","abstract_url":"https://arxiv.org/abs/2608.31022v1","html_url":"https://arxiv.org/html/2608.31022v1","pdf_url":"https://arxiv.org/pdf/2608.31022v1.pdf","matched_keywords":["agent","representation","multimodal"],"source_used":"html","source_text_chars":102541,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 agent, representation, multimodal 相关；摘要显示其主要贡献为：AI agents in partially observable environments need to coordinate active sensing with working memory to maintain an evolving perceptual state. However, existing benchmarks struggle to isolate this perceptual-state construction and interpretation capability be...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:31+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.31013v1","title":"TSPFN: A Temporal Tabular Foundation Model for Physiological Time Series Classification","abstract":"Designing models that generalize effectively in low- to medium-data regimes remains a primary challenge in medical machine learning, particularly for physiological time-series classification. While tabular foundation models such as TabPFN offer an attractive alternative to conventional fine-tuning through in-context learning, they are not designed to capture the temporal dependencies inherent to physiological signals. ~In this paper, we introduce TSPFN, a foundation model that redesigns TabPFN's architecture for time series data. TSPFN integrates structured temporal representations and positional embeddings to capture intra-sample temporal and channel dependencies. To fully leverage its spatio-temporal design, the model is pretrained on 140,000 real-world physiological time series across multiple medical domains. This yields a unified, generalizable framework capable of learning the specificities of medical time series. Experiments across diverse physiological benchmarks demonstrate that TSPFN consistently outperforms standard tabular baselines and TabPFN, and achieves superior cross-domain generalization compared to specialized deep time-series models. All our experiments, ablation studies, and pre-processing scheme are publicly available at https://github.com/Jeremstym/TSPFN","authors":["Jérémie Stym-Popper","Clément Rambour","Federica Granese","Nicolas Thome","Olivier Bernard"],"published":"2026-08-31T15:58:22Z","updated":"2026-08-31T15:58:22Z","abstract_url":"https://arxiv.org/abs/2608.31013v1","html_url":"https://arxiv.org/html/2608.31013v1","pdf_url":"https://arxiv.org/pdf/2608.31013v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":37053,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：Designing models that generalize effectively in low- to medium-data regimes remains a primary challenge in medical machine learning, particularly for physiological time-series classification. While tabular foundation models such as TabPFN offer an attractive...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:32+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.31005v1","title":"From Intent to Evidence: Policy-Steered Multi-Strategy Retrieval for Long-Video Agents","abstract":"Existing long-video agents acquire evidence through one uniform behavior, ignoring whether the required evidence is concentrated, requires broad occurrence coverage, or must discriminate competing hypotheses---which can cause failure before substantive reasoning begins. Prescribing a fine-grained solution procedure for every question is not a satisfactory remedy, as it restricts autonomous exploration. We propose VESTA, a training-free long-video agent organized as a route-conditioned acquire--verify--consolidate loop. Before exploration, an intent router infers an evidence-acquisition policy---focused, recall, or contrastive retrieval over a shared visual--speech scene index---together with an evidence-accounting policy that configures the evidence view maintained during exploration. Policy-steered retrieval yields provisional references that multimodal evidence operations convert into observations, while the Reasoner remains free to verify them, re-query using intermediate findings, or inspect regions outside the retrieved set. A temporal evidence ledger consolidates observations into an adaptive, compressed view of temporal location, provenance, coverage, conflicts, verification outcomes, and hypothesis support, exposing missing and unresolved evidence to guide subsequent acquisition; finalization prioritizes verified observations. On Video-MME-v2, VESTA improves average accuracy by 2.7 points over VideoARM and gains across all six reported metrics. On LongVideoBench, EgoSchema, and LVBench under shared query-time models, it improves by 6.9 points on the LongVideoBench long subset and 1.5 on LVBench, and matches VideoARM on EgoSchema.","authors":["Can Zhang","Baofeng Zhang","Xiaotian Han","Junyuan Shang","Yuchen Ding","Shuohuan Wang","Dianhai Yu","Ruirui Li"],"published":"2026-08-31T15:55:48Z","updated":"2026-08-31T15:55:48Z","abstract_url":"https://arxiv.org/abs/2608.31005v1","html_url":"https://arxiv.org/html/2608.31005v1","pdf_url":"https://arxiv.org/pdf/2608.31005v1.pdf","matched_keywords":["video","retrieval","agent","multimodal"],"source_used":"html","source_text_chars":78847,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, retrieval, agent, multimodal 相关；摘要显示其主要贡献为：Existing long-video agents acquire evidence through one uniform behavior, ignoring whether the required evidence is concentrated, requires broad occurrence coverage, or must discriminate competing hypotheses---which can cause failure before substantive reason...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:32+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.31002v1","title":"DARP: A Calibrated Dual-Arm RGB-D-IR Dataset for Multi-View Robotic Perception","abstract":"Robotic perception from a single viewpoint is often limited by self-occlusion and incomplete surface visibility. This paper presents DARP(Dual-Arm Robotic Perception) https://doi.org/10.21227/rmv3-be47, a calibrated dual-arm RGB-D-IR dataset for object-centered robotic perception using two independently moving eye-in-hand manipulators positioned on opposite sides of a shared tabletop workspace. Each arm carries an Intel RealSense sensor that continuously records RGB, depth, and stereo infrared data while synchronized robot joint states are logged for pose recovery. Objects are placed without fixed poses or marked locations, and the acquisition procedure performs automatic localization, cross-arm confirmation, adaptive viewpoint generation, and continuous multimodal recording. DARP contains ten unique tabletop objects and preserves the original sensor recordings, robot-state logs, object-level metadata, and calibration information required to reconstruct camera trajectories in a shared metric frame. To evaluate the geometric consistency of the acquisition, we implement a deterministic multi-view fusion pipeline that converts calibrated RGB-D observations into complementary partial point clouds and measured surface meshes without using learned or generative completion methods. Evaluation on 224 held-out RGB-D keyframes comprising 1,563,466 three-dimensional query points yields a median point-to-mesh distance of 2.13~mm and an RMSE of 4.04~mm, with 96.56\\% of points within 10~mm of the measured-surface mesh. DARP is intended as a reusable resource for multi-view reconstruction, collaborative robotic perception, multimodal fusion, active perception, and future learning-based reasoning over partial object observations.","authors":["Manish Kansana","Mohammed Yusuf Mujawar","Sudip Mittal","Shahram Rahimi","Noorbakhsh Amiri Golilarz"],"published":"2026-08-31T15:53:41Z","updated":"2026-08-31T15:53:41Z","abstract_url":"https://arxiv.org/abs/2608.31002v1","html_url":"https://arxiv.org/html/2608.31002v1","pdf_url":"https://arxiv.org/pdf/2608.31002v1.pdf","matched_keywords":["multimodal"],"source_used":"html","source_text_chars":50256,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 multimodal 相关；摘要显示其主要贡献为：Robotic perception from a single viewpoint is often limited by self-occlusion and incomplete surface visibility. This paper presents DARP(Dual-Arm Robotic Perception) https://doi.org/10.21227/rmv3-be47, a calibrated dual-arm RGB-D-IR dataset for object-center...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:32+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30975v1","title":"MR-JEPA: A General Purpose Video Foundation Model for Cardiac MRI","abstract":"Cardiac magnetic resonance imaging (CMR) produces rich sequential data such as temporal cine videos and spatial LGE/mapping stacks, yet most deep learning approaches process individual 2D slices, discarding this context. We present MR-JEPA, a self-supervised video foundation model for CMR that extends LeJEPA to 3D spatiotemporal inputs through tubelet tokenization, spatiotemporal masking augmentation, and initialization from a 2D CMR foundation model. Unlike prior CMR video models limited to cine data, MR-JEPA is pretrained on multi-sequence data (cine, LGE, mapping) from 10,505 patients across two centers without annotations. We evaluate the frozen encoder on six downstream tasks using a unified multi-view gated attention architecture: LV ejection fraction, RV ejection fraction, three myocardial strains (GLS, GCS, GRS), and four-class disease detection. MR-JEPA outperforms other compared methods on all five regression tasks, including both a domain-specific CMR model pretrained on more data with text supervision and a natural-video foundation model, achieving an LV EF MAE of 4.79% (r =0.764) and a GLS MAE of 1.87 (r=0.805), with 21-27% MAE reductions over baselines on strain tasks. For disease detection, MR-JEPA achieved a macro AUG of 0.868, remaining competitive with the domain-specific baseline despite using a fully self-supervised pretraining objective. These results demonstrate the potential of a unified video encoder for robust, multi-view utilization of diverse CMR sequences in clinical cardiac quantification and diagnosis.","authors":["Athira J. Jacob","Puneet Sharma","Dorin Comaniciu","Daniel Rueckert"],"published":"2026-08-31T15:36:24Z","updated":"2026-08-31T15:36:24Z","abstract_url":"https://arxiv.org/abs/2608.30975v1","html_url":"https://arxiv.org/html/2608.30975v1","pdf_url":"https://arxiv.org/pdf/2608.30975v1.pdf","matched_keywords":["video","3d"],"source_used":"abstract","source_text_chars":1624,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d 相关；摘要显示其主要贡献为：Cardiac magnetic resonance imaging (CMR) produces rich sequential data such as temporal cine videos and spatial LGE/mapping stacks, yet most deep learning approaches process individual 2D slices, discarding this context. We present MR-JEPA, a self-supervised...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"abstract","created_at":"2026-09-01T05:58:32+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30964v1","title":"Vision Models Predict Urban Scene Appraisal with Limited Neural Alignment","abstract":"Pretrained vision embeddings are increasingly used as general-purpose representations for modelling how people appraise urban scenes, and are validated almost entirely by how well they predict human ratings. High predictive accuracy does not establish that these embeddings organise scenes as human perception does. We test the two properties separately against brain data. Using openly released EEG from 63 adults who viewed and rated 56 Berlin street scenes, we estimate the representational geometry of the scenes over time, the proportion of that geometry that is explainable at all, and its correspondence with seventeen feature spaces spanning language-supervised, self-supervised, category-supervised and dense-prediction training, two orders of magnitude of scale, and interpretable controls. Correspondence is low throughout: the best representation, DINOv2 ViT-B, reaches 29.6% of the lower bound of the noise ceiling, the panel spans 11.0% to 29.6%, and a Gabor energy descriptor is indistinguishable from the best model while outperforming every language-supervised model tested. Within a model, deeper layers still match later neural responses, so the hierarchical correspondence found for object recognition survives even at this low overall level. The same embeddings predict held-out appraisal ratings well, up to r = 0.87, and the two measures do not track each other across models; reweighting features towards the neural geometry lowers appraisal prediction for every model tested, against a control of matched dimensionality. Predicting how a street is appraised is therefore weak evidence that a model represents the street as the brain does. The benchmark uses only public data and requires no training, so evaluating a new representation needs only its embeddings for 55 images.","authors":["Kaizhen Tan","Yuantao Deng"],"published":"2026-08-31T15:28:39Z","updated":"2026-08-31T15:28:39Z","abstract_url":"https://arxiv.org/abs/2608.30964v1","html_url":"https://arxiv.org/html/2608.30964v1","pdf_url":"https://arxiv.org/pdf/2608.30964v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":61727,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：Pretrained vision embeddings are increasingly used as general-purpose representations for modelling how people appraise urban scenes, and are validated almost entirely by how well they predict human ratings. High predictive accuracy does not establish that th...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:32+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30959v1","title":"LOCI: A Locator-Critic with Refinement Loop","abstract":"Vision-Language Models (VLMs) still struggle on tasks requiring complex visual understanding. We argue that the core issue is not high-level reasoning, but instead failing to locate critical details in the image. Due to this shortcoming, VLMs generate often plausible but incorrect reasoning based on flawed perceptual grounding. To address this, we propose Locator-Critic (LOCI), a training-free framework that decouples visual search from evidence verification. LOCI employs a Locator agent to propose candidate visual evidence and a separate Critic agent to evaluate its relevance and sufficiency. These agents engage in an iterative refinement loop, progressively improving the evidence until it is adequate to answer the given question. This decoupled, self-correcting process yields substantial performance gains, achieving state-of-the-art results on multiple complex visual benchmarks. LOCI improves accuracy for both open-weight models like Qwen3-VL (+12.1 on V*, +5.8 on HR-Bench and +11.2 on VisualProbe-Hard) and proprietary models like Gemini 2.5 Pro (+8.9 on V*, +4.3 on HR-Bench, +4.8 on VisualProbe-Hard).","authors":["Walid Bousselham","Mathilde Caron","Arsha Nagrani","Cordelia Schmid"],"published":"2026-08-31T15:26:00Z","updated":"2026-08-31T15:26:00Z","abstract_url":"https://arxiv.org/abs/2608.30959v1","html_url":"https://arxiv.org/html/2608.30959v1","pdf_url":"https://arxiv.org/pdf/2608.30959v1.pdf","matched_keywords":["agent"],"source_used":"html","source_text_chars":82084,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 agent 相关；摘要显示其主要贡献为：Vision-Language Models (VLMs) still struggle on tasks requiring complex visual understanding. We argue that the core issue is not high-level reasoning, but instead failing to locate critical details in the image. Due to this shortcoming, VLMs generate often p...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:32+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30951v1","title":"Audio-Driven Adversarial Defense for 3D Talking Face Generation with totally Visual Fidelity Preservation","abstract":"The rapid development of generative portrait models has raised growing concerns about privacy leakage and identity misuse. In particular, audio-driven 3D talking face generation can reconstruct a reusable 3D portrait of a target person from a monocular video and animate it with arbitrary speech, making realistic identity impersonation alarmingly practical. Existing proactive defenses mainly operate in the visual domain by injecting subtle perturbations into acial regions to disrupt identity acquisition. However, such perturbations often compromise visual quality due to the strong structural priors and social sensitivity of human faces, and are easily weakened by common real-world transformations such as resizing. To overcome these limitations, we propose an imperceptible audio defense for audio-driven 3D talking face generation by shifting protection from the visual modality to the audio modality. Specifically,we exploit psychoacoustic masking to hide protective perturbations within perceptually masked frequency regions of the speech signal, thereby reducing perceptual distortion while suppressing reliable facial animation. Extensive experiments demonstrate that the proposed method effectively degrades 3D talking face generation while preserving favorable perceptual quality. These findings highlight psychoacoustically guided audio perturbations as a practical and promising direction for privacy-preserving portrait protection.","authors":["Rui-Qing Sun","Chen-Hao Cui","Hui-Yang Zhao","Tian Lan","Zhijing Wu","Xian-Ling Mao"],"published":"2026-08-31T15:22:05Z","updated":"2026-08-31T15:22:05Z","abstract_url":"https://arxiv.org/abs/2608.30951v1","html_url":"https://arxiv.org/html/2608.30951v1","pdf_url":"https://arxiv.org/pdf/2608.30951v1.pdf","matched_keywords":["video","3d"],"source_used":"html","source_text_chars":57381,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d 相关；摘要显示其主要贡献为：The rapid development of generative portrait models has raised growing concerns about privacy leakage and identity misuse. In particular, audio-driven 3D talking face generation can reconstruct a reusable 3D portrait of a target person from a monocular video...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-01T05:58:32+00:00","status":"fallback"},"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30899v1","title":"Uncertainty-Aware Trajectory Forecasting from Imperfect Tracking","abstract":"Most trajectory forecasting models are trained on clean annotated histories, and are often evaluated under the same idealized assumption, although practical deployments rely on trajectories produced by imperfect multi-object trackers. The real-world observations exhibit localization jitter, missed or unstable detections, and data-association ambiguity, which are usually either ignored or removed through denoising. This paper instead treats tracking-derived reliability cues as an informative signal to be propagated to the predictor. We propose a plug-in uncertainty-aware formulation in which each observed state is encoded as an uncertain state representation, modeled by a Gaussian distribution whose covariance combines detection-level localization uncertainty and association-level ambiguity through the law of total variance. Existing backbones are adapted with minimal architectural changes: input trajectories are represented as Gaussian observations, and predicted trajectories are produced as Gaussian forecasts rather than deterministic coordinates. To train predictors that remain robust under structured observation noise, we combine temporally correlated Ornstein-Uhlenbeck perturbations with response-based knowledge distillation from a teacher trained on clean trajectories. Experiments on Oxford Town Centre and VIRAT using real tracker outputs, together with a complementary ETH/UCY pseudo-detection protocol, show that the proposed formulation improves displacement accuracy and the reliability-sharpness trade-off of probabilistic forecasts.","authors":["Stephane Da Silva Martins","Victor Petrovic","Emanuel Aldea","Sylvie Le Hégarat-Mascle"],"published":"2026-08-31T14:50:38Z","updated":"2026-08-31T14:50:38Z","abstract_url":"https://arxiv.org/abs/2608.30899v1","html_url":"https://arxiv.org/html/2608.30899v1","pdf_url":"https://arxiv.org/pdf/2608.30899v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30872v1","title":"SurgSkill-Bench: A Benchmark for Multimodal Surgical Skill Assessment","abstract":"Objective assessment of surgical technical skill is important for surgical training and structured feedback, but current workflows remain dependent on labor-intensive expert review. Existing automated approaches primarily focus on visual inputs and provide limited support for jointly studying operative performance, structured skill scores, and evaluator feedback. We introduce SurgSkill-Bench, an initial video-score-text benchmark-style dataset containing 214 surgical training simulation videos, six-dimensional OSATS scores, and expert free-text comments. We define two evaluation settings: video-only OSATS prediction for automated assessment and post hoc expert-comment-assisted prediction, where evaluator comments are available as auxiliary information. We provide controlled baseline experiments using representative frozen visual backbones, content-adaptive key-frame sampling, and a simple video-text co-attention fusion module. Under internal video-level validation, content-adaptive sampling improves video-only performance in this dataset, while evaluator comments provide additional score-related signal in the assisted setting. The best mean AUROC reaches 0.88 under dataset-specific median dichotomization. We further discuss evaluation constraints related to dataset scale, metadata completeness, and the interpretation of comment-assisted prediction. Code will be released publicly at a later date.","authors":["Chaohui Dang","Zheheng Jiang","James Glasbey","David Luke","Theodoros Arvanitis","Le Zhang"],"published":"2026-08-31T14:32:45Z","updated":"2026-08-31T14:32:45Z","abstract_url":"https://arxiv.org/abs/2608.30872v1","html_url":"https://arxiv.org/html/2608.30872v1","pdf_url":"https://arxiv.org/pdf/2608.30872v1.pdf","matched_keywords":["video","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30870v1","title":"VCAR: Training-Free 3DGS Segmentation via View Completeness and Axis-Aware Boundary Refinement","abstract":"Semantic segmentation in 3D Gaussian Splatting (3DGS) is crucial for advancing 3D scene understanding. Existing methods predominantly rely on feature distillation, which incurs substantial per-scene training overhead and often yields blurred segmentation boundaries. We identify that these boundary artifacts are driven in part by insufficient viewpoint coverage and boundary overflow of anisotropic Gaussian primitives. To address these challenges, we propose VCAR, a training-free coarse-to-fine segmentation strategy based on View Completeness and Axis-aware Boundary Refinement. In the coarse stage, a visibility-based weighted multi-view voting scheme rapidly localizes the target. In the fine stage, an object-centric sphere derived from the coarse result generates supplementary viewpoints via Spherical Spiral Sampling (SSS), allowing multi-view voting on the augmented views to precisely refine object boundaries and suppress irrelevant 3D Gaussians. Moreover, we introduce Axis-aware Boundary Refinement (ABR) to mitigate artifacts from anisotropic primitives. By decomposing the projected 2D covariance into per-axis contributions, ABR identifies the dominant axis responsible for boundary leakage and applies targeted anisotropic compression exclusively along that axis. Extensive experiments on NVOS and LERF demonstrate that VCAR achieves state-of-the-art segmentation accuracy and efficiency without training. Our code is available at https://github.com/DDKK0526/VCAR.","authors":["Kun Cao","Di Wang","Haibin Zhu","Haozhi Huang","Xu Wang","Zheng Shi","Guanghua Yang"],"published":"2026-08-31T14:32:26Z","updated":"2026-08-31T14:32:26Z","abstract_url":"https://arxiv.org/abs/2608.30870v1","html_url":"https://arxiv.org/html/2608.30870v1","pdf_url":"https://arxiv.org/pdf/2608.30870v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30858v1","title":"GAFT: Geo-Anchored Fine-Tuning for Hazard Identification from Rare Failures","abstract":"Off-road navigation can fail when physical structures induce irrecoverable states such as high-centering or entrapment, requiring human interventions. Identifying these structures is crucial, yet challenging. Such failure events are rare and costly to collect, resulting in limited training data. Moreover, the collected data associate frames with outcomes, but do not indicate the visual cues responsible for the failure. Learning directly from these data can therefore exploit scenario-specific visual cues, leading to poor generalization. We propose \\textbf{Geo-Anchored Fine-Tuning (GAFT)}, a parameter-efficient method that adapts a vision foundation model with a geometry-derived prior. It guides LoRA adaptation by aligning a spatial attention-rollout map with the geometry prior, while preserving pretrained representations. On an intervention-verified forest hazard benchmark, across ten independently trained adaptations, GAFT consistently outperforms frozen DINOv2 and supervised PEFT baselines, improving the repeated leave-one-scenario-out mean $F_2$ from 0.0607 to 0.3757 with statistical significance under paired analysis. Within these independently trained models, the best-performing GAFT model achieves a repeated-LOSO $F_2$ of 0.570. Code and benchmark: https://github.com/Xu-Yanran/geo_anchored_fine_tuning","authors":["Yanran Xu","Chuanhang Qiu","Yue Wang","Wenbo Wu","Zhaoxing Li"],"published":"2026-08-31T14:20:59Z","updated":"2026-08-31T14:20:59Z","abstract_url":"https://arxiv.org/abs/2608.30858v1","html_url":"https://arxiv.org/html/2608.30858v1","pdf_url":"https://arxiv.org/pdf/2608.30858v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30857v1","title":"TAMI: Temporally Aligned, Missingness-Aware, and Interpretable Multimodal Fusion for Mental Health Assessment in Older Adults with Mild Cognitive Impairment","abstract":"Depression and anxiety in older adults with Mild Cognitive Impairment (MCI) are frequently underdiagnosed due to limited access to care. Multimodal analysis of remote clinical interviews is a scalable screening approach, but existing methods have three limitations. First, they do not correct temporal misalignment across multimodal features extracted at different resolutions, inducing spurious cross-modal associations. Second, remote recordings exhibit uneven modality dropout, but missing values are often zero-filled, making them indistinguishable from valid near-zero measurements. Finally, they do not jointly attribute predictions to modalities, questions, and interview moments, limiting fine-grained clinical interpretation. We propose a Temporally-Aligned, Missingness-Aware, Interpretable (TAMI) multimodal fusion framework. TAMI aligns speech, language, facial, and physiological features within question-answer segments on a shared timeline, encodes modality-level missingness over time, and conditions fusion on question context. In interviews with 49 older adults with MCI, TAMI achieved area under the receiver operating characteristic curve (AUROC) scores of 0.68 (depression) and 0.69 (anxiety). Fine-grained temporal alignment of multimodal features produced the largest performance gain ($Δ{\\geq}0.1$). Multi-level interpretability analysis revealed that depression classification relied on eyegaze and open-ended questions, while anxiety classification depended on eyegaze and head pose, with attribution uniformly distributed across questions. Using only responses to the open-ended questions (5.1min), the depression model achieved an AUROC score of 0.67, which was not significantly different from using the full interview (19min) ($p>0.05$). Our findings support designing interview protocols centered on open-ended questions for depression screening in older adults with MCI.","authors":["Merna Bibars","Bolaji Omofojoye","Allan I. Levey","Rachel Hershenberg","Gari D. Clifford","Hyeokhyen Kwon"],"published":"2026-08-31T14:19:32Z","updated":"2026-08-31T14:19:32Z","abstract_url":"https://arxiv.org/abs/2608.30857v1","html_url":"https://arxiv.org/html/2608.30857v1","pdf_url":"https://arxiv.org/pdf/2608.30857v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30844v1","title":"Pretrained, Curriculum-Tuned, and Ensembled: A Tracer-Aware Interactive Segmentation Pipeline for AutoPET V","abstract":"Interactive lesion segmentation in whole-body PET/CT requires a model to provide a strong initial prediction while also responding efficiently to sparse corrective scribbles during inference. This setting is particularly challenging because tracer distributions, physiological uptake patterns, lesion appearance, and acquisition characteristics differ substantially between FDG and PSMA studies. We present TRIAGE, Tracer-aware Refinement via Interactive Anatomy-Guided sEgmentation. The core backbone is a 3D STU-Net initialized through masked autoencoding pre-training with an asynchronous masking strategy, aiming to learn transferable anatomical and cross-modal representations before task-specific fine-tuning. In parallel, we train an auxiliary organ segmentation model whose predictions provide explicit anatomical context and help distinguish physiological uptake from malignant lesions. A dedicated tracer classifier first routes each study to an FDG- or PSMA-specific branch. Within each branch, a first-stage segmentation model consumes CT, PET, and organ context to generate an initial lesion mask. The initial prediction is then combined with cumulative foreground/background scribbles and refined by a second interactive segmentation network. The FDG and PSMA branches share the same overall processing pipeline but are trained independently to account for tracer-specific appearance and error modes. We additionally employ curriculum-style training and model ensembling to improve robustness across interaction steps and heterogeneous cohorts. Experiments are conducted using the official AutoPET V data and ten-fold split; quantitative results, ablations, and final test-set performance are left as placeholders to be completed after the challenge evaluation. Code: https://github.com/Liiiii2101/AUTOPET2026-MEDAI.","authors":["Xinglong Liang","Chunyao Lu","Tianyu Zhang","Jiaju Huang","Tao Tan","Yunchao Yin","Lishan Cai"],"published":"2026-08-31T14:13:09Z","updated":"2026-08-31T14:13:09Z","abstract_url":"https://arxiv.org/abs/2608.30844v1","html_url":"https://arxiv.org/html/2608.30844v1","pdf_url":"https://arxiv.org/pdf/2608.30844v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30839v1","title":"Physical Adversarial Examples for Person Detectors in Thermal Images Based on 3D Modeling","abstract":"Thermal Infrared detection is widely used in autonomous driving, medical AI, etc., but its security has only attracted attention recently. We propose infrared adversarial clothing designed to evade thermal person detectors in real-world scenarios. The design of the adversarial clothing is based on 3D modeling, which makes it easier to simulate multiangle scenes near the real world compared to 2D modeling. We optimized the black patch layout pattern of 3D clothing based on the adversarial example technique and made physical adversarial clothing using the aerogel. The idea is to paste a set of square aerogel patches, which display black squares in thermal images, in the inner side of clothing at specific locations with specific orientations. To enhance realism, we propose a method to build infrared 3D models with real infrared photos and develop texture maps for 3D models to simulate varied infrared characteristics over time and location. In physical attacks, we achieved an attack success rate of 80.11\\% indoors and 76.85\\% outdoors against YOLOv9. In contrast, randomly placed patches yielded much lower success rates (26.53\\% indoors and 23.03\\% outdoors). The adversarial clothing also showed good transferability to unknown detectors with an ensemble attack method, demonstrating the effectiveness of our approach.","authors":["Xiaopei Zhu","Siyuan Huang","Zhanhao Hu","Jianmin Li","Jun Zhu","Xiaolin Hu"],"published":"2026-08-31T14:09:41Z","updated":"2026-08-31T14:09:41Z","abstract_url":"https://arxiv.org/abs/2608.30839v1","html_url":"https://arxiv.org/html/2608.30839v1","pdf_url":"https://arxiv.org/pdf/2608.30839v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30835v1","title":"Reliable Benchmarking of Artifact Detection in Computational Pathology: A Reproducibility and Uncertainty Analysis","abstract":"Background and Objective: Quality control is a prerequisite for whole-slide image analysis, yet the benchmarks on which quality-control methods are compared share four properties that make their reported differences hard to interpret: few independent slides, annotation concentrated in a minority of them, pooled ratio metrics with no closed-form standard error, and a single inherited train/test partition. We propose a reliability protocol for such benchmarks. Methods: The protocol quantifies four sources of variability - test-set sampling, training stochasticity, partition composition, and undocumented preprocessing - a claim is reportable only if it survives all four; three of the four cost minutes of compute. We apply it to an independent reconstruction of a published diffusion-based artifact detector, evaluated on the original 24-slide partition and against a supervised baseline. Results: The method's central mechanism reproduces: the auxiliary contrastive term improves pooled F1 from 0.673 to 0.688 and replicates under a second seed (+0.0156, p = 0.031; +0.0190, p = 0.005), although it acts on pen marking rather than the artifact types cited to motivate it. Its comparative claims do not: differences between design variants, and against the supervised baseline, fall inside the uncertainty of the evaluation. Four of 24 slides carry 70% of scored annotated pixels, giving an effective sample size of 6.2, and the inherited partition sits at the 7th percentile. An unreported tissue-restriction step excludes 41.4% of out-of-focus annotation against 2.6% of air bubble; such a gate is confounded with blur by construction. Conclusions: Small-cohort benchmarks support far weaker conclusions than current reporting implies. The four checks are cheap enough to accompany any evaluation on such a resource and separate reproducible effects from differences the evaluation cannot resolve.","authors":["Konstantinos Moutselos","Ilias Maglogiannis"],"published":"2026-08-31T14:07:15Z","updated":"2026-08-31T14:07:15Z","abstract_url":"https://arxiv.org/abs/2608.30835v1","html_url":"https://arxiv.org/html/2608.30835v1","pdf_url":"https://arxiv.org/pdf/2608.30835v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30824v1","title":"Whole-Body MRI Classification via Prompt-Based Clinical Conditioning","abstract":"Combining whole-body magnetic resonance imaging (WB-MRI) with clinical variables has the potential to improve systemic disease diagnosis by leveraging complementary sources of patient information. However, structured clinical variables are often incomplete or missing, limiting the applicability of conventional multimodal fusion methods that assume fixed inputs. In this work, we propose TACTIC (Tabular-Attribute Conditioned Transformer for Image Classification), a prompt-based multimodal framework that integrates WB-MRI and structured clinical data through conditional visual feature learning. By encoding clinical attributes as prompts, TACTIC supports an arbitrary number of tabular inputs and naturally handles missing data without requiring imputation or fixed input structures. We evaluate TACTIC on five WB-MRI classification tasks spanning systemic and oncologic applications, including diabetes, chronic obstructive pulmonary disease (COPD), breast cancer, prostate cancer, and metastasis diagnosis. Across all tasks, TACTIC consistently improves performance over image-only baselines when clinical information is available while maintaining strong predictive capability under incomplete tabular inputs. Our results demonstrate the effectiveness of prompt-based models as a flexible approach for improving WB-MRI analysis using clinical context. The model weights and code are available at https://github.com/lauradaza/TACTIC","authors":["Laura Daza","Marta Hasny","Cristina González","Julia A. Schnabel"],"published":"2026-08-31T14:03:41Z","updated":"2026-08-31T14:03:41Z","abstract_url":"https://arxiv.org/abs/2608.30824v1","html_url":"https://arxiv.org/html/2608.30824v1","pdf_url":"https://arxiv.org/pdf/2608.30824v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30821v1","title":"Lucida: Parse, Generate, and Place for Composable Real-to-Sim Scene Modeling","abstract":"Composable scene modeling aims to recover a real indoor scene as complete, editable object assets arranged as observed, giving robot simulation and embodied AI a simulation-ready replica of the real environment whose objects can be manipulated individually. Existing pipelines decompose the task into three steps---parse the observations into instances, generate an asset for each, and place each asset back---but every step presumes an input that a cluttered capture rarely provides: accurate instance geometry, unoccluded views, and assets that accurately match the observations. We propose Lucida, which keeps this order but redistributes the requirements, so each step consumes only what a real capture reliably provides and precision is reached at the end of the pipeline rather than demanded at its start. Lucida parses the video into a scene graph whose nodes carry per-instance multi-view evidence, generates a complete asset for each instance from its evidence, and places assets with GizmoAct, a VLM policy that casts placement as multi-turn GUI interaction, manipulating the object's gizmo in a closed loop and deciding itself when alignment is reached. Across scene-level 3D object detection, object pose estimation, and scene reconstruction, Lucida improves mAP over Boxer by 69% on R2S-Scene, raises ADD-SB@0.05 from 57.8% to 83.4% on CA-1M, and increases scene F-Score from 0.794 for SAM3D to 0.924.","authors":["Minghan Qin","Yuang Wang","Xiuyu Yang","Yushi Long","Yujian Zhang","Ruihuan Wang","Kai Ye","Yangang Zhang","Hang Li"],"published":"2026-08-31T14:03:20Z","updated":"2026-08-31T14:03:20Z","abstract_url":"https://arxiv.org/abs/2608.30821v1","html_url":"https://arxiv.org/html/2608.30821v1","pdf_url":"https://arxiv.org/pdf/2608.30821v1.pdf","matched_keywords":["video","3d","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30817v1","title":"A Composition-Aware Pretraining Framework for Geospatial Foundation Models","abstract":"Geospatial foundation models have emerged as state-of-the-art methods for downstream Earth observation tasks. However, existing pretraining methodologies process imagery through a single-concept lens, failing to capture the highly compositional nature of complex satellite scenes. We propose a composition-aware pretraining framework that explicitly encodes fractional land-cover mixtures. Each satellite image cell is mapped to a histogram representing its fractional land-cover distribution, which we term the \"composition target\". These targets serve as the primary prediction objective and are distilled into the backbone using Earth Mover's Distance. Experimental evaluation shows that composition-aware pretraining yields substantial gains on region-level understanding tasks requiring semantic similarity judgment, including zero-shot image retrieval and scene classification, while remaining competitive on tasks requiring fine-grained spatial precision, such as segmentation and object detection. With a 36.8M-parameter backbone, our framework outperforms SatMAE and Prithvi-EO-2.0, which contain 303M and 600M parameters, respectively, in most retrieval and scene classification settings. On the fine-grained ForestNet-12 dataset, a rigorous testbed for compositional discrimination, our method boosts baseline mAP@10 from 0.279 to 0.434, a 55.6% relative improvement, providing direct evidence for the effectiveness of explicit composition modeling. The code implementation can be found at https://github.com/05kashyap/GFM_Composition_Pretraining","authors":["Aryan Kashyap Naveen","Abhishek Srinivas","Pranav Moothedath","Shrutilipi Bhattacharjee"],"published":"2026-08-31T14:00:12Z","updated":"2026-08-31T14:00:12Z","abstract_url":"https://arxiv.org/abs/2608.30817v1","html_url":"https://arxiv.org/html/2608.30817v1","pdf_url":"https://arxiv.org/pdf/2608.30817v1.pdf","matched_keywords":["retrieval"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30758v1","title":"CheXGround: Anatomical Region Tokens for Grounded Longitudinal Chest X-ray Interpretation","abstract":"Recent radiology multi-modal language models have made substantial progress in chest X-ray report generation, visual question answering, and temporal reasoning. While longitudinal chest X-ray interpretation compares sequential examinations to describe change, visual grounding aims to connect clinical language with localized image evidence. Although longitudinal modeling and visual grounding have each advanced radiology language models, how localized visual evidence can support longitudinal interpretation remains under-explored. We introduce CheXGround, a region-grounded longitudinal chest X-ray language model that represents paired studies through corresponding anatomical regions. CheXGround extracts anatomical regions from current and prior radiographs, encodes them as temporally enhanced Region-of-Interest (ROI) tokens, and combines them with global temporal image context during generation. To connect these region tokens with clinical text, we propose Temporal Region--Phrase Alignment, a pretraining objective that aligns temporal anatomical representations with localized report phrases. We evaluate CheXGround on single-study and longitudinal Visual Question Answering (VQA), longitudinal findings generation, temporal grounded VQA, and anatomical grounding. Across these tasks, CheXGround improves clinical language quality, temporal reasoning, and localization accuracy over recent baselines. Our results suggest that organizing longitudinal evidence at the anatomical level is a strong representation for grounded radiology language modeling. Project page: https://adonaydem.github.io/chexground-website","authors":["Adonay Demewez Gebremedhin","Wessam Shehieb","Sara Alansari","Mohamad Alansari","Muzammal Naseer","Sajid Javed","Naoufel Werghi"],"published":"2026-08-31T13:25:40Z","updated":"2026-08-31T13:25:40Z","abstract_url":"https://arxiv.org/abs/2608.30758v1","html_url":"https://arxiv.org/html/2608.30758v1","pdf_url":"https://arxiv.org/pdf/2608.30758v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30751v1","title":"Autoregressive Mosaics: Probing 2D Spatial Reasoning in Text-Only Language Models","abstract":"Large language models (LLMs) trained only on text and code can sometimes generate programs that draw recognizable images. However, it is unclear whether this reflects an internal representation of 2D spatial layout or simply the ability to translate spatial descriptions into code. We introduce Autoregressive Mosaics (AM-Bench), a benchmark that separates these factors: First, a translation task gives a model a fully specified geometry of a picture in words as a prompt and asks for the code that produces it. Second, a layout task requires the model to compose an image from an underspecified prompt. Across eight open-weight text-and-code-only models, all models reliably translate specified geometry into code, but their open-ended layout performance differs substantially, indicating that these differences are not explained by code-generation ability alone. An output-medium ablation further shows that the interface or medium of expression that the model uses matters: replacing procedural code with raw SVG improves layout scores across all models. Finally, probing model activations shows that a coarse layout plan is present before generation, but reflects only the layout implied by the prompt. During generation, models track the evolving geometric state instead of executing an initially fixed plan. Overall, these results show that 2D spatial performance in text-only LLMs depends on both the model and the output medium, and is not explained by code-generation ability alone.","authors":["Ashwin Nedungadi","Stefan Oehmcke","Stefan Lüdtke"],"published":"2026-08-31T13:18:03Z","updated":"2026-08-31T13:18:03Z","abstract_url":"https://arxiv.org/abs/2608.30751v1","html_url":"https://arxiv.org/html/2608.30751v1","pdf_url":"https://arxiv.org/pdf/2608.30751v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30727v1","title":"RailGen: Improving Railway Intrusion Detection via Agent-Guided Small-Scale Foreign Object Generation","abstract":"Small-object detection under long-tailed data distributions is a fundamental yet challenging problem in multimedia. Railway Foreign Object Detection (RFOD) epitomizes this challenge with easily confused small intrusions and scarce samples. To address these issues, we propose a generative-augmented detection paradigm that leverages multimodal image generation to enrich the feature space of rare and small objects. We first construct RailGen, a multimodal image generation agent based on large models. Under semantic constraints, RailGen automatically invokes tools to generate railway scenes, calibrate intrusion positions, extract foreign objects, and fuse them into realistic intrusion effects. This process produces high-quality synthetic samples that effectively densify the feature representations of tail classes and complete the small-object feature space. Within this paradigm, we further propose FocalDEIM, a detection framework designed to enhance training with generated data. FocalDEIM improves dense matching with Focal Modulation for better small-object discrimination and adopts Focal Loss to emphasize hard samples, thereby alleviating blurred inter-class boundaries in complex railway scenes. Experimental results demonstrate that RailGen can generate high-quality small-scale foreign objects, reducing the object pixel area by up to 58x and 13.85x on average. Equipped with these challenging samples, our paradigm surpasses the baseline DEIM by 5.6% and 7.5% in mAP@50 and mAP@(50-95), respectively, and outperforms existing state-of-the-art methods. Ablation studies verify RailGen's feature-space enrichment and FocalDEIM's boundary discrimination. The paradigm provides an effective multimodal generative solution for long-tailed small-object detection in safety-critical applications.","authors":["Quan Hao","Ziyang Tao","Chenxi Zhang","Yudong Wang","Rui Shi","Liguo Zhang"],"published":"2026-08-31T13:01:12Z","updated":"2026-08-31T13:01:12Z","abstract_url":"https://arxiv.org/abs/2608.30727v1","html_url":"https://arxiv.org/html/2608.30727v1","pdf_url":"https://arxiv.org/pdf/2608.30727v1.pdf","matched_keywords":["agent","representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30716v1","title":"SocialReasonBench: A Video-QA Benchmark for Social Reasoning with Counterfactual Narrative Videos","abstract":"Recent advances in Large Multimodal Models (LMMs) have greatly improved video understanding, yet their ability to reason about human-centered social situations remains limited. Existing benchmarks typically rely on videos with a single observed trajectory, making it difficult to determine whether models truly understand social dynamics or merely exploit recurring narrative patterns. We introduce SocialReasonBench, a video multiple-choice QA benchmark for evaluating socially grounded reasoning in scenarios derived from interactive narratives. Built from gameplay videos of Detroit: Become Human, the benchmark leverages branching storylines where player decisions lead to alternative social outcomes that can be checked against the game's own script, flowchart, and recorded branches. We develop a multi-agent curation pipeline that localizes socially meaningful clips, grounds answer labels in game-state signals, and generates theory-guided questions with diagnostic distractors. SocialReasonBench covers seven reasoning dimensions, including intent recognition, emotional empathy, moral dilemma, counterfactual reasoning, and causal antecedent. Experiments on contemporary LMMs show that models perform reasonably well on basic social understanding but struggle with counterfactual and causal reasoning. Further ablation and diagnostic error analyses reveal that models often depend on incomplete modality cues and fall into reasoning traps such as visual shortcuts, highlighting a gap between observable event recognition and deeper reasoning over latent social states.","authors":["Zheyu Huang","Zijing Shi","Haozhe Luo","Huadong Tang","Mingyu Liu","Meng Fang","Ling Chen"],"published":"2026-08-31T12:55:52Z","updated":"2026-08-31T12:55:52Z","abstract_url":"https://arxiv.org/abs/2608.30716v1","html_url":"https://arxiv.org/html/2608.30716v1","pdf_url":"https://arxiv.org/pdf/2608.30716v1.pdf","matched_keywords":["video","agent","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30709v1","title":"RailSyn: Diagnosis-Guided Image Generation for Traceable Data Completion in Railway Foreign Object Detection","abstract":"Railway foreign object detection (RFOD) is critical to safe railway operation, yet scarce real positive samples incompletely represent task-relevant variations in object scale, intrusion relation, railway scene, illumination, and adverse weather. Existing synthetic augmentation can improve RFOD detection, but its gains lack an explicit account of the task-relevant deficiencies complemented by the generated data. We therefore introduce RailSyn, a diagnosis-guided framework comprising a real-referenced Inspector and a requirement-aligned Generator. The Inspector constructs a variable-radius empirical cover from finite real observations to localize candidate completion regions and profile synthetic pools. The resulting audit identifies railway-context, intrusion-semantic, and visual-consistency requirements; the Generator addresses them through domain adaptation, agent-planned placement and physical contact relations, and plan-consistent conditional refinement. Using the Inspector, we further trace representation-space changes across generation variants; the complete system attains a local-shell occupation of $C_{gap}$ to 13.64%, which measures generated coverage of real-derived completion regions. Extensive experiments show AP50--95 gains of up to 4.9 points and consistent improvements across nine mainstream detectors, demonstrating broad cross-architecture utility.","authors":["Quan Hao","Chenxi Zhang","Ziyang Tao","Yuyuan Zhou","Yudong Wang","Rui Shi","Lechuan Xu","Changhao Liu","Liguo Zhang"],"published":"2026-08-31T12:47:28Z","updated":"2026-08-31T12:47:28Z","abstract_url":"https://arxiv.org/abs/2608.30709v1","html_url":"https://arxiv.org/html/2608.30709v1","pdf_url":"https://arxiv.org/pdf/2608.30709v1.pdf","matched_keywords":["agent","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30705v1","title":"VisLens: Single-Pass Interpretable Visual Search for Multimodal LLMs","abstract":"Multimodal large language models (MLLMs) struggle with fine-grained Visual Search, the task of locating small or rare objects in high-resolution images. Existing remedies fall into two families: (1) Training-free methods based on attention or confidence scores are accurate but slow, since they require multiple MLLM queries per example. (2) Reinforcement Learning (RL) trained tool-use models are faster at inference but opaque, since their tool calls remain uncontrollable and hard to interpret. To overcome this, we propose \\emph{VisLens} (Visual Focus via Logit Lens), a Visual Search method built on the logit lens, which decodes the semantics held in a hidden state by projecting it through the LLM head. VisLens further uses a lightweight tuned-lens that maps early hidden states into the final hidden state space, so visual tokens can be read out from early layers. These tokens are matched to target words in the query to generate a crop of the relevant region, which is fed back in alongside the original image to produce the final answer. The whole process, from decoding to the final answer, completes in a single forward pass without repeated queries. VisLens matches or exceeds prior baselines while delivering a substantial latency advantage, running $8.5$--$9.9\\times$ faster than Thyme and up to $22.2\\times$ faster than training-free multi-pass search methods.","authors":["Jingyi He","Sanghwan Kim","Zeynep Akata"],"published":"2026-08-31T12:43:42Z","updated":"2026-08-31T12:43:42Z","abstract_url":"https://arxiv.org/abs/2608.30705v1","html_url":"https://arxiv.org/html/2608.30705v1","pdf_url":"https://arxiv.org/pdf/2608.30705v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30704v1","title":"TUE-Detector: A Tool-Using Expert MLLM-Based Detector for AI-Generated Videos","abstract":"AI-generated video detection, which aims to distinguish AI-generated videos from real ones, has recently received increasing research attention. To perform this task reliably, a key challenge lies in accurately identifying subtle-yet-measurable unnatural artifacts. In this work, we address this challenge from a novel perspective of tool-mediated evidence discovery and propose Tool-Using Expert MLLM-based AI-generated Video Detector (TUE-Detector), a novel framework for AI-generated video detection. TUE-Detector trains a general MLLM into a task-tailored tool-using expert detector that learns to invoke suitable tools, collect concrete evidence of unnaturalness, and reason over the evidence for reliable detection. Meanwhile, TUE-Detector further introduces novel designs to equip the expert detector with high-quality and suitable tools. Extensive experiments demonstrate the effectiveness of our framework.","authors":["Yichen Wu","Haoxuan Qu","Yongxing Dai","Yan Bai","Yihang Lou","Yuqi Lin","Hossein Rahmani","Jun Liu"],"published":"2026-08-31T12:42:38Z","updated":"2026-08-31T12:42:38Z","abstract_url":"https://arxiv.org/abs/2608.30704v1","html_url":"https://arxiv.org/html/2608.30704v1","pdf_url":"https://arxiv.org/pdf/2608.30704v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30692v1","title":"Can Video World Models Track Unobserved World States?","abstract":"Video world models are increasingly used as simulators, yet visual fidelity alone does not show that a model maintains the hidden state of the world. We examine this gap with an action-conditioned video Shell Game, a visual analog of $S_5$ state tracking that decouples visual rendering from compositing the hidden state underneath. Bidirectional and autoregressive Transformers, Mamba, and linear attention restricted to nonnegative transition eigenvalues all fit the training horizon of 5 swaps and then fall toward chance on longer swap chains (extrapolation) while still rendering plausible video with additional denoising steps providing no benefit. The pixel-based diffusion target never supervises the unseen hidden state, so the generated frames cannot carry it and the state has to live inside the architecture rather than in the tokens. For a Transformer, that architectural state is only an append-only KV cache, so the model has to re-derive the hidden arrangement from the whole history at every chunk. We find two mechanisms that do extrapolate, and both carry a state across chunks and revise it in place. Linear attention succeeds once its transition eigenvalues may be negative, and TTT with a nonlinear fast weight succeeds by updating the feature map through which it reads its own state. We further examine harder cases in dynamic world exploration tasks, and discuss the broader implications for building stateful video world models.","authors":["Joonghyuk Shin","Yicong Hong","Jaesik Park","Xun Huang"],"published":"2026-08-31T12:29:24Z","updated":"2026-08-31T12:29:24Z","abstract_url":"https://arxiv.org/abs/2608.30692v1","html_url":"https://arxiv.org/html/2608.30692v1","pdf_url":"https://arxiv.org/pdf/2608.30692v1.pdf","matched_keywords":["video","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30688v1","title":"UFPR-PEs: A Brazilian Face Recognition Benchmark with Self-Declared Race/Color Labels","abstract":"While face recognition systems are widely deployed, ensuring their demographic reliability and robustness under uncontrolled visual conditions remains a critical challenge. To bridge this gap, we present UFPR-PEs, a benchmark for face recognition bias evaluation using public videos of elected Brazilian politicians annotated with official self-declared race/color categories. The dataset adopts the Brazilian census taxonomy, including the parda category, which has no direct equivalent in the U.S.- or Europe-centric schemas commonly used in prior benchmarks. Our benchmark is built from compressed public video and preserves difficult samples so that performance can be analyzed under realistic conditions. We describe the construction pipeline, report dataset statistics, and evaluate face recognition performance across verification and (closed- and open-set) identification settings, including subgroup analysis by race/color and difficulty level. The results show that recognition performance varies substantially with image quality, and that subgroup gaps must be interpreted jointly with visual difficulty rather than in isolation. Overall, UFPR-PEs provides a reproducible and demographically grounded setting for studying face recognition bias under challenging public video conditions.","authors":["Alexandre Diano","Bernardo Biesseck","Gabriel Polo","Vinicius Gregorio","Laura Lopes","Diego Addan","David Menotti"],"published":"2026-08-31T12:27:15Z","updated":"2026-08-31T12:27:15Z","abstract_url":"https://arxiv.org/abs/2608.30688v1","html_url":"https://arxiv.org/html/2608.30688v1","pdf_url":"https://arxiv.org/pdf/2608.30688v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30657v1","title":"InfraOcc: An Infrastructure Occupancy Benchmark with Static-to-Dynamic Reasoning","abstract":"Fixed-viewpoint infrastructure sensors repeatedly observe the same traffic space, making roadside 3D occupancy structurally different from ego-vehicle perception: a near-persistent static scaffold is overlaid with sparse, short-lived dynamic events. Existing occupancy benchmarks and methods, however, are built around moving ego vehicles and neither measure nor exploit this structure, instead treating occupancy as flat one-shot voxel classification. We address this gap from both data and model perspectives. We build InfraOcc, to our knowledge, the first real-world infrastructure-side semantic occupancy benchmark, with dense voxel annotations for 290 multi-modal sequences in a fixed roadside frame, a static-dynamic decoupled annotation pipeline, unified camera-only, LiDAR-only, and multi-modal evaluation, and diagnostics for static and dynamic occupancy. InfraOcc shows that static infrastructure fills 97.3% of occupied voxels and persists across frames, whereas dynamic participants have a median occupied-frame ratio of only 1.8% per location, revealing a structural static-dynamic asymmetry beyond semantic long-tailedness. We further propose ProSD-Occ, which reformulates occupancy as progressive static-to-dynamic evidence reasoning: it explains persistent layout, exposes residual dynamic evidence under static-confidence guidance, and recomposes static, dynamic, and free-space evidence into a unified field. ProSD-Occ ranks first in overall, dynamic, static, and geometric occupancy on every track, e.g., a 23.5% relative camera-only dynamic-mIoU gain over the strongest baseline and 65.87 multi-modal overall mIoU, establishing fixed-viewpoint roadside occupancy as a distinct problem with its own reasoning paradigm. The benchmark and code will be publicly available at https://github.com/yanglei18/InfraOcc","authors":["Lei Yang","Xiaokai Bai","Boqi Li","Chunmian Lin","Li Wang","Ziying Song","Jiahuan Zhang","Enhui Ma","Haibao Yu","Jiaqi Ma","Kaicheng Yu"],"published":"2026-08-31T11:56:50Z","updated":"2026-08-31T11:56:50Z","abstract_url":"https://arxiv.org/abs/2608.30657v1","html_url":"https://arxiv.org/html/2608.30657v1","pdf_url":"https://arxiv.org/pdf/2608.30657v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30656v1","title":"APT: Anchor-aligned Perturbations for Tamper Localization in Fully Regenerated Images","abstract":"Proactive tamper localization embeds an imperceptible signal into an image prior to distribution, enabling pixel-level manipulation detection. Existing methods assume a spliced (SP) setting, where synthesized regions are composited onto the original background, leaving embedded signals intact. However, real-world diffusion-based inpainting operates in a fully regenerated (FR) setting, where the entire image undergoes denoising, disrupting background signals and rendering existing frameworks ineffective. We propose APT, a semi-fragile latent-space perturbation that embeds a dense, vector-wise localization signal. By aligning each spatial feature vector toward a fixed anchor direction, APT localizes tampering via the alignment disparity between synthesized foreground and anchor-aligned background features after inpainting. The proposed hard negative mining loss and noisy perturbation branch further enforce uniform alignment. Experiments on COCO demonstrate that APT achieves an FR IoU of 0.92, outperforming the strongest baseline (WAM, 0.84), while existing methods collapse to near-random performance (AUC 0.5), establishing APT as a practical forensic framework generalizable across tampering types unknown at test time.","authors":["Suhyeon Ha","Woo Jae Kim","Joonsung Jeon","Sooel Son","Sung-eui Yoon"],"published":"2026-08-31T11:56:39Z","updated":"2026-08-31T11:56:39Z","abstract_url":"https://arxiv.org/abs/2608.30656v1","html_url":"https://arxiv.org/html/2608.30656v1","pdf_url":"https://arxiv.org/pdf/2608.30656v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30653v1","title":"Fine-Grained Multi Image Object Hallucination Benchmark","abstract":"Multimodal Large Language Models (MLLMs) are increasingly deployed in multi-image scenarios requiring complex reasoning across visual contexts. However, current MLLMs remain fundamentally limited by object hallucination-generating plausible yet factually inconsistent descriptions about objects. Existing benchmarks, designed primarily for single-image settings or providing only high-level multi-image assessments, cannot systematically diagnose how visual complexity and reasoning demands trigger hallucination. To address this gap, we introduce MIOH, a fine-grained multi-image object hallucination benchmark that systematically evaluates object hallucination across four foundational tasks (existence, counting, attribute, position) through three multi-image reasoning patterns (comprehensive, comparative, selective) under three controlled adversarial pressures (visual context scale, perceptual difficulty, contextual bias). Through evaluation of 29 models, we reveal that even state-of-the-art systems like GPT-5 and Gemini-2.5-Pro exhibit distinct failure patterns across different reasoning patterns and tasks. Our evaluation reveals that hallucination stems not merely from perceptual failures but from integration-stage limitations when maintaining object representations across multiple images. MIOH provides a controlled framework for analyzing multi-image object hallucination and serves as a critical evaluation tool for developing more reliable multimodal AI systems.","authors":["Joonki Min","Chaeyun Kim","Hyungwook Choi","Yejin Kim","Kihyun Kim","Yohan Jo","Joonseok Lee"],"published":"2026-08-31T11:53:03Z","updated":"2026-08-31T11:53:03Z","abstract_url":"https://arxiv.org/abs/2608.30653v1","html_url":"https://arxiv.org/html/2608.30653v1","pdf_url":"https://arxiv.org/pdf/2608.30653v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30649v1","title":"Where Identity Lives: Localized, Retain-Free Identity Unlearning in Multimodal Large Language Models","abstract":"Removing a specific individual's information from multimodal large language models (MLLMs) is often needed after deployment, but existing methods rely on a retain set, which is hardest to obtain at that point, and rebuilding it recreates the privacy exposure that unlearning aims to remove. Forgetting from the forget set alone instead damages the shared visual-language computation, harming perception. We cast retain-free unlearning as a localization problem: causal tracing, weight transplant, and Fisher overlap all point to early-to-mid decoder MLPs as the layers where identity information is stored and, unlike other module families, can be modified without substantially disrupting vision. We turn this into Pathway-Aware Visual-attribute Anchoring (PAVA), which confines updates to these layers and pairs a forget loss with a visual-attribute anchor that preserves image-grounded behavior by distilling the model's own pre-unlearning answers from the forget images alone. On MLLMU-Bench and ReMem, PAVA gives the strongest forget-retain trade-off among forget-set-only methods and remains competitive with retain-based baselines.","authors":["Kangwook Ko","Jaehyuk Jang","Wonjun Lee","Hee-Seon Kim","Changick Kim"],"published":"2026-08-31T11:51:05Z","updated":"2026-08-31T11:51:05Z","abstract_url":"https://arxiv.org/abs/2608.30649v1","html_url":"https://arxiv.org/html/2608.30649v1","pdf_url":"https://arxiv.org/pdf/2608.30649v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30633v1","title":"Quantum-Grassmann-Plucker Token Mixing for Deep Learning-Based Post-Disaster Damage Assessment","abstract":"Timely post-disaster building damage assessment from satellite imagery is a critical engineering decision support task, yet it remains constrained by class imbalance, ambiguous intermediate damage states, and limited cross-event transferability. This study presents, to our knowledge, the first application of Grassmann-Plucker (GP) token mixing to computer vision and introduces two extensions for image classification: the Quantum-inspired Grassmann-Plucker (QGP) head and the Hybrid Quantum Machine Learning Grassmann-Plucker (HQML-GP) head. The GP head represents multiscale relationships among image patch tokens by encoding subspaces formed by token pairs with Plucker coordinates; QGP enriches these coordinates with amplitude-derived probability features, whereas HQML-GP incorporates expectation values generated by a simulated quantum circuit into the geometric token representation. Paired pre- and post-event image patches from the xBD tornado dataset were processed using a frozen six-channel Vision Transformer base encoder with 16 x 16-pixel patches. The three GP-based heads were compared with multilayer perceptron and Transformer baselines under identical training, checkpoint selection, and evaluation protocols. Joplin and Moore tornado samples were used for model development and seen-event testing, while Tuscaloosa was reserved for unseen-event evaluation. QGP led both test sets in accuracy and macro-F1: 83.46% and 64.50% for the seen events, and 66.45% and 52.70% for the unseen event. Although HQML-GP obtained the highest validation macro-F1 of 65.63%, it did not surpass QGP on either test set and required substantially more training time per epoch. These results establish GP token mixing as a competitive attention-free alternative to conventional Transformer-based token mixing for paired satellite image damage classification.","authors":["Kooroush Farahkhah","Umut Lagap","Taha Rezaei","Saman Ghaffarian"],"published":"2026-08-31T11:42:27Z","updated":"2026-08-31T11:42:27Z","abstract_url":"https://arxiv.org/abs/2608.30633v1","html_url":"https://arxiv.org/html/2608.30633v1","pdf_url":"https://arxiv.org/pdf/2608.30633v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30618v1","title":"AQ3D: Adaptive Query Transformer for 3D Instance Segmentation","abstract":"Transformer-based decoders for 3D instance segmentation typically commit to a fixed number of queries and positional modeling calibrated on the training distribution rather than on the scene at hand. Indoor scans vary widely in spatial extent and object count, so a fixed query set over-initializes small scenes and under-initializes large ones, while learned absolute and relative encodings are bound to the training scenes' extents and can saturate. We present AQ3D, which is designed to handle scenes of various sizes during training and inference. Queries are instantiated at a fixed ratio of the scene's superpoints, forming an overcomplete set whose background rejection is entirely left to the decoder. Positional information is encoded using 3D RoPE over quantized metric coordinates, replacing learned bounded lookup tables of prior decoders. Further, we improve the decoder itself by using attribution-based superpoint pooling, a mask refinement branch, and a cosine classifier for background rejection. Experiments show our method sets a new state-of-the-art on validation and hidden test splits across the datasets ScanNetV2, ScanNet200, and ScanNet++V2 among decoder methods trained without additional data augmentation. Code is available at \\href{https://github.com/kenomo/aq3d}{github.com/kenomo/aq3d}.","authors":["Keno Moenck","Thorsten Schüppstuhl"],"published":"2026-08-31T11:27:42Z","updated":"2026-08-31T11:27:42Z","abstract_url":"https://arxiv.org/abs/2608.30618v1","html_url":"https://arxiv.org/html/2608.30618v1","pdf_url":"https://arxiv.org/pdf/2608.30618v1.pdf","matched_keywords":["3d","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30617v1","title":"RealCAD: Towards Real-World Image-to-CAD Reconstruction under Domain Shift and Parameter Bias","abstract":"Reconstructing editable Computer-Aided Design (CAD) models from images is essential for downstream modification, manufacturing, and design reuse. However, existing image-to-CAD methods are developed predominantly on synthetic renderings and face two coupled obstacles: a substantial appearance domain gap between synthetic and real images, and a previously overlooked parameter bias in widely used CAD data. We show that the local normalization adopted by DeepCAD concentrates several geometric parameters around a few discrete values while encoding substantial information in a single scale factor. Consequently, a model can achieve deceptively high parameter accuracy by exploiting these frequent values rather than inferring geometry from the input image. In this paper, we propose RealCAD, a unified framework that addresses these limitations at the representation, image, and feature levels. At the representation level, we redistribute scale information to the corresponding geometric parameters, producing less concentrated parameter distributions in a shared scale space. At the image level, geometry-constrained translation converts synthetic renderings toward the real-image domain while conditioning on object contours. At the feature level, a multi-positive contrastive objective aligns representations of the same CAD model across viewpoints and image domains, enabling CAD sequence prediction from each individual view. We further introduce OpenRealCAD, comprising four-view photographs of 392 3D-printed objects paired with ground-truth command sequences. Experiments show that the revised representation substantially reduces the accuracy attainable from parameter-frequency priors, making parameter accuracy a more reliable measure of image-conditioned geometric inference. RealCAD further improves real-domain command and parameter accuracy, while retaining competitive synthetic-domain performance.","authors":["Yihe Sun","Ziyu Lu","Kaihua Tang","Xian-Sheng Hua"],"published":"2026-08-31T11:27:22Z","updated":"2026-08-31T11:27:22Z","abstract_url":"https://arxiv.org/abs/2608.30617v1","html_url":"https://arxiv.org/html/2608.30617v1","pdf_url":"https://arxiv.org/pdf/2608.30617v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30603v1","title":"DiffSAC: Diffusion-guided Sampling for Consensus-based Robust Estimation","abstract":"Robust estimation is a core computer vision task frequently tackled using sample consensus. However, traditional methods suffer from inefficient sampling as they struggle to identify effective minimum sets before hypothesis evaluation. To address these challenges, we propose a novel Diffusion-guided Sampling for Consensus-based Robust Estimation (DiffSAC) framework. DiffSAC introduces a diffusion model to learn the distribution of effective minimum sets. It refines the confidence for each data point, indicating whether it belongs to a good minimum set, rather than ranking the data points as in previous work. This significantly reduces the need to process numerous bad sets. To constrain the refinement direction, geometric features are incorporated as conditions within our diffusion model. Consequently, DiffSAC outputs a small number of high-quality minimum sets, enabling identification of the best hypothesis via consensus evaluation. Notably, compared to previous works requiring evaluating over ten thousand hypotheses, DiffSAC achieves state-of-the-art performance with only dozens, significantly boosting efficiency. Extensive experiments across five classic computer vision tasks demonstrate the superiority of DiffSAC. The diffusion model's sampling accelerators enable real-time operation, and DiffSAC can be used as a plug-and-play module to improve existing sample consensus methods.","authors":["Chang Nie","Guangming Wang","Zhe Liu","Hesheng Wang"],"published":"2026-08-31T11:15:11Z","updated":"2026-08-31T11:15:11Z","abstract_url":"https://arxiv.org/abs/2608.30603v1","html_url":"https://arxiv.org/html/2608.30603v1","pdf_url":"https://arxiv.org/pdf/2608.30603v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30584v1","title":"Learning Compositional Spatio-Temporal Video Grounding with Synthetic Curriculum","abstract":"Despite the impressive progress of recent MLLMs on spatio-temporal video grounding (STVG), existing evaluations and training data focus primarily on simple queries. They largely overlook the compositional queries prevalent in real-world scenarios, where a target must be disambiguated by jointly reasoning about its attributes and relations to other entities. To bridge this gap, we propose Compositional Spatio-Temporal Video Grounding (CompSTVG), a task that requires models to process complex textual queries where every intertwined attribute and relational cue is essential for disambiguation. To facilitate this task at scale, we build a synthetic data engine that leverages a spatio-temporal scene graph as a difficulty measure and casts difficulty-controlled query synthesis as a constraint programming problem, producing difficulty-graded data for both evaluation and training. Built on this engine, we introduce STVG-CompBench, a benchmark stratified by explicit difficulty levels that jointly capture temporal complexity and spatial interference. Evaluating 11 representative STVG models on STVG-CompBench reveals that current models perform poorly on compositional queries, exhibiting a sharp performance drop that is typically obscured by overall dataset-level averages. We further construct synthetic training data and propose CurrSTVG, a curriculum reinforcement learning framework that delivers consistent gains, with the largest improvements observed on the most challenging compositional queries.","authors":["Xingjian Wang","Shijian Wang","Yibo Wang","Zihao Yu","Runhao Fu","Xuelian Cheng","Zongyuan Ge"],"published":"2026-08-31T11:01:31Z","updated":"2026-08-31T11:01:31Z","abstract_url":"https://arxiv.org/abs/2608.30584v1","html_url":"https://arxiv.org/html/2608.30584v1","pdf_url":"https://arxiv.org/pdf/2608.30584v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30563v1","title":"Modality Disentangled Learning for Incomplete Multimodal Emotion Recognition: A Primitive Memory Distillation Perspective","abstract":"Multimodal Emotion Recognition (MER) systems often suffer from missing modalities in real-world scenarios. Existing methods usually generate, align, or distill missing modalities as a whole, overlooking the heterogeneous nature of the information carried by each modality. Such holistic treatment mixes inferable shared semantics with uncertain modality-specific details, yielding unstable representations and degrading robustness. To address this issue, we propose the Primitive Memory Distillation (PriMD) framework. Unlike existing methods, PriMD takes an intra-modal perspective and focuses on how different types of information within a modality differ in recoverability within each modality. PriMD first disentangles cross-modal shared semantics from modality-specific representations, and then discretizes the latter into learnable semantic primitives to construct modality-specific memory banks. When modalities are missing, PriMD is a teacher-student framework that the student model uses the shared semantics of available modalities as queries to dynamically retrieve primitives. It compensates for missing modality-specific information within a constrained memory space and aligns with the teacher model. Extensive experiments on IEMOCAP, CMU-MOSI, and CMU-MOSEI demonstrate that PriMD achieves state-of-the-art performance and consistently stronger robustness across a wide range of missing-modality settings, while mitigating the instability caused by holistic feature inference. Our code and project website are available at https://github.com/JiaqiZhang-Sengoku/PriMD and https://jiaqizhang-sengoku.github.io/PriMD/, respectively.","authors":["Jiaqi Zhang","Zheng Pang","Mengting Li","Yiqi Wang","Guangyuan Dong","Chao Xue","Yusen Wu","Zihao Li","Huy Phan","Sicheng Zhao","Björn W. Schuller","Jiachen Luo"],"published":"2026-08-31T10:38:47Z","updated":"2026-08-31T10:38:47Z","abstract_url":"https://arxiv.org/abs/2608.30563v1","html_url":"https://arxiv.org/html/2608.30563v1","pdf_url":"https://arxiv.org/pdf/2608.30563v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30550v1","title":"GarmentWeaver: Schema-Aware Structured Synthesis for Multimodal Sewing Patterns","abstract":"Multimodal Sewing pattern generation aims to infer executable sewing patterns from design cues such as sketches and textual descriptions. As an interpretable and simulation-compatible representation, sewing patterns are particularly valuable for digital garment creation. However, existing methods often model garment specifications as flat long sequences, which entangles garment structure with detailed parameters and leads to redundant components, inaccurate local details, and poor simulation compatibility. In this paper, we present GarmentWeaver, a schema-aware framework for multimodal Sewing pattern generation. GarmentWeaver constructs compact hierarchical targets by activating garment-relevant structural branches and predicts executable Sewing patterns in a structured manner. Specifically, we introduce a schema-aware target construction strategy, build the generator on top of a pretrained vision-language model for multimodal garment understanding, and impose feasibility-aware regularization to encourage structurally valid and simulation-compatible outputs. Extensive experiments show that GarmentWeaver produces more accurate and more executable sewing patterns than strong baselines, while also yielding better simulation results. These findings demonstrate the effectiveness of schema-aware structured generation for reliable multimodal Sewing pattern prediction.","authors":["Yinwen Lu","Weihao Luo","Yueqi Zhong"],"published":"2026-08-31T10:25:00Z","updated":"2026-08-31T10:25:00Z","abstract_url":"https://arxiv.org/abs/2608.30550v1","html_url":"https://arxiv.org/html/2608.30550v1","pdf_url":"https://arxiv.org/pdf/2608.30550v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30521v1","title":"MEOM: Multi-View Expected-OKS Maximization for Human Pose Triangulation","abstract":"Conventional algebraic triangulation solves 3D human pose estimation (HPE) from multi-view 2D keypoints. The typical approach, decoding 2D keypoints from predicted heatmaps, is unreliable as heatmaps can be multimodal under occlusion, and collapsing them into single peaks discards their spatial distribution. We seek to use the entire heatmap to estimate 3D poses more accurately, which requires solving two problems: how to robustly fuse heatmaps across views, and how to assess the reliability of heatmaps. For the former, we introduce a novel objective, Multi-viewExpected-OKS Maximization (MEOM), that locates a 3D joint where the views agree in probability mass. For the latter, we adopt highest-density-region (HDR) calibration as a diagnostic of that mass, independently of distance-based metrics. The proposed framework covers two settings, with and without 3D supervision. Without 3D supervision, we optimize 3D poses from pretrained heatmap predictors by maximizing MEOM, achieving comparable performance with state-of-the-art methods that rely on larger backbones, temporal fusion, and simulated 3D data. On ambiguous Human3.6M (H36MA) and occluded CMU Panoptic frames, the advantage is substantial. When 3D labels are available, we train the model end-to-end with a combined MEOM and MSE loss, achieving 19.11 mm absolute MPJPE on Human3.6M outperforming the state-of-the-art volumetric approach on absolute MPJPE at half the inference cost.","authors":["Ziliang Xiong","Henglin Shi","Per-Erik Forssen"],"published":"2026-08-31T09:54:05Z","updated":"2026-08-31T09:54:05Z","abstract_url":"https://arxiv.org/abs/2608.30521v1","html_url":"https://arxiv.org/html/2608.30521v1","pdf_url":"https://arxiv.org/pdf/2608.30521v1.pdf","matched_keywords":["3d","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30510v1","title":"Lot Machine: Multimodal Lot Extraction from Auction Catalogs","abstract":"For provenance research and art market studies, auction catalogs are an essential resource to trace specific objects over time and space. While historical auction catalogs follow established domain conventions, their internal formatting remains highly variable, and their large-scale analysis is currently restricted by the lack of machine-readable representations of the auction lots. We propose a pipeline to automatically extract structured lot-level metadata from German Sales, a large database of historical auction and sales catalogs from the 19th and 20th centuries. Using a manually annotated test set of representative catalog pages, we evaluate Vision-Language Models (VLMs) under varying prompt strategies and constrained decoding frameworks. To reflect the practical constraints faced by cultural heritage institutions, including budget, compute resources, and data privacy requirements, we benchmark the methods across different deployment modes ranging from commercial providers to locally hosted, quantized models. We find that commercial endpoints establish the performance ceiling, while institutional gateways offer a viable, privacy-preserving alternative. Local deployments remain feasible, but strictly require enforcing the output structure during generation to guarantee a valid JSON format. While varying degrees of human-in-the-loop correction are still necessary, this work demonstrates that a VLM-based pipeline can successfully unlock historical auction catalogs for large-scale automated analysis.","authors":["Mathias Zinnen","Alisha Mund","Sabine Lang","Lukas Hüttner","Thomas Gorges","Vincent Christlein"],"published":"2026-08-31T09:44:15Z","updated":"2026-08-31T09:44:15Z","abstract_url":"https://arxiv.org/abs/2608.30510v1","html_url":"https://arxiv.org/html/2608.30510v1","pdf_url":"https://arxiv.org/pdf/2608.30510v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30467v1","title":"Beyond Accuracy: Quantifying Pulmonary Attribution in Anatomy-Guided Chest X-Ray Classification Under Domain Shift","abstract":"Deep-learning models can achieve strong chest X-ray (CXR) classification performance without establishing whether their predictions predominantly rely on pulmonary image content. This study evaluates pulmonary attribution containment as an anatomy-related reliability property distinct from diagnostic performance. We propose DBCA-SegNet-MGAP, a multi-task anatomy-guided CNN-Transformer framework that combines complementary feature representations through bidirectional cross-backbone attention, predicts a soft lung mask, and incorporates this anatomical prior directly into classification through Mask-Guided Adaptive Global Average Pooling (MGAP). Pulmonary attribution containment is quantified using the Anatomical Local Energy Ratio (ALR) and high-intensity cumulative ALR (cALR@0.9). Experiments were repeated across three training seeds using the COVID-19 Radiography Database for four-class internal testing and a locked Shenzhen-to-Montgomery protocol for zero-shot external tuberculosis testing. On COVID-19, the proposed model achieved a weighted F1 of $0.9615 \\pm 0.0015$ and macro ROC-AUC of $0.9906 \\pm 0.0007$. In an architecture-matched dual-bridge comparison, replacing conventional GAP with MGAP increased ALR from $0.3878 \\pm 0.0098$ to $0.7086 \\pm 0.0104$ and cALR@0.9 from $0.5265 \\pm 0.0101$ to $0.9905 \\pm 0.0018$, while weighted F1 remained essentially unchanged ($0.9618 \\pm 0.0015$ vs. $0.9615 \\pm 0.0015$). Under locked external transfer to Montgomery, ROC-AUC remained $0.9080 \\pm 0.0043$ and pulmonary ALR remained $0.6466 \\pm 0.0081$, whereas weighted F1 decreased to $0.7528 \\pm 0.0080$ and ECE increased to $0.1683 \\pm 0.0055$. These findings show that diagnostic discrimination, calibration, and pulmonary attribution containment are distinct model properties and support their joint evaluation under internal testing and external domain shift.","authors":["Abdullah Al Mamun","Md. Nasif Osman Khansur","Md Ashraful Hossen Akash","Md. Kishor Morol","Tze Hui Liew"],"published":"2026-08-31T08:54:44Z","updated":"2026-08-31T08:54:44Z","abstract_url":"https://arxiv.org/abs/2608.30467v1","html_url":"https://arxiv.org/html/2608.30467v1","pdf_url":"https://arxiv.org/pdf/2608.30467v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30451v1","title":"SeqAlign3DVG: A Sequence-Aligned Benchmark and Voxel Reasoning Framework for 3D Visual Grounding","abstract":"Image-based 3D visual grounding is critical for embodied agents, yet existing benchmarks suffer from loose text-observation alignment and neglect temporal ordering. We introduce SeqAlign3DVG, a novel benchmark dedicated to temporally ordered and strictly observation-aligned image-based 3D visual grounding. Unlike prior works using order-agnostic views or global point clouds, SeqAlign3DVG ensures all expressions are human-verified and strictly grounded in the provided RGB observations (single frames or ordered observation sequences). It comprises 9,622 single-view and 14,493 sequence samples featuring rich descriptions, complex relations, and multi-instance ambiguities. To tackle this benchmark, we propose a unified voxel-based pipeline featuring Relevance-Ordered Voxel Memory (ROVM) and Progressive Language-Voxel Fusion (PLVF). ROVM dynamically ranks and aggregates multi-view evidence via a conservative memory to mitigate noisy observations, while PLVF performs coarse-to-fine spatial-linguistic reasoning for precise disambiguation. Our approach achieves state-of-the-art performance under the depth-free protocol, significantly improving localization for targets defined by complex relations and appearance cues.","authors":["Yi Zhang","Yi Wang","Yueting Wu","Kaiyue Yang","Yuejiao Su","Lap-Pui Chau"],"published":"2026-08-31T08:38:29Z","updated":"2026-08-31T08:38:29Z","abstract_url":"https://arxiv.org/abs/2608.30451v1","html_url":"https://arxiv.org/html/2608.30451v1","pdf_url":"https://arxiv.org/pdf/2608.30451v1.pdf","matched_keywords":["3d","agent","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30450v1","title":"FlowVVTON: Flow-Guided Mask-Free Video Virtual Try-On","abstract":"Video virtual try-on aims to transfer a target garment onto a moving person across video frames. Current methods rely on human parsing masks or pose keypoints that frequently fail under large motions and occlusions, causing boundary artifacts and temporal inconsistency. A further limitation is that most approaches rely solely on attention mechanisms for temporal modeling, providing no explicit motion supervision. We propose FlowVVTON, a mask-free framework that eliminates parsing mask dependency entirely. Optical flow is used solely as a training-time supervision signal: a flow-warped latent loss, applied across all layers of the generation model, enforces multi-scale temporal consistency by aligning adjacent-frame features under explicit physical motion constraints. A two-stage training strategy establishes mask-free spatial alignment before introducing flow-guided temporal supervision. Experiments on TikTokDress show that FlowVVTON outperforms baselines by substantial margins, particularly in temporal consistency (5.7$\\times$ VFID-R improvement over SwiftTry), while requiring no segmentation masks, pose keypoints, or region annotations at any stage.","authors":["Shengyao Chen","Xianbing Sun","Liqing Zhang","Jianfu Zhang"],"published":"2026-08-31T08:37:47Z","updated":"2026-08-31T08:37:47Z","abstract_url":"https://arxiv.org/abs/2608.30450v1","html_url":"https://arxiv.org/html/2608.30450v1","pdf_url":"https://arxiv.org/pdf/2608.30450v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30428v1","title":"Lies We Can See: Joint Verbal and Non-Verbal Deception by VLM Agents in Embodied Social Interactions","abstract":"Strategic deception by LLM and VLM agents has emerged as a central AI alignment and safety concern. Social-deduction games (where each player holds a hidden role and communicates with others to deduce identities) serve as the canonical testbed, particularly in multi-agent settings. Existing testbeds, however, are text-only and run on a single fixed agent configuration, missing the non-verbal sensorimotor channels treated as core by deception taxonomies and leaving it ambiguous whether an observed behavior reflects the underlying model or the surrounding harness. We introduce MineAmongUs, a 3D multimodal Among Us sandbox where imposter agents must deceive crewmates through joint verbal and non-verbal action. We also propose ARIA, a configurable VLM-agent harness that exposes five cognitive-component ablation axes; and an atom- and arc-level annotation scheme grounded in deception taxonomies and operationalized at scale by an LLM-as-a-Judge reaching near-human atom-labeling agreement. Empirical results show that VLM agents pursue imposter wins through joint verbal and non-verbal deception, with non-verbal channels emerging as the more decisive winning contributors across both harness ablation and cross-VLM evaluation. Taken together, our work opens a new path for embodied VLM-agent alignment research.","authors":["Jaewoo Ahn","Junseo Kim","Hyunseo Kim","Heeseung Yun","Jaehyeon Son","Zsolt Kira","Gunhee Kim"],"published":"2026-08-31T08:24:29Z","updated":"2026-08-31T08:24:29Z","abstract_url":"https://arxiv.org/abs/2608.30428v1","html_url":"https://arxiv.org/html/2608.30428v1","pdf_url":"https://arxiv.org/pdf/2608.30428v1.pdf","matched_keywords":["3d","agent","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30423v1","title":"ObjectSplat: Improving Mesh Fidelity and Interactivity for 3D Scenes via Object-Level Mesh Splatting","abstract":"Splatting-based algorithms reconstruct photorealistic, real-time-renderable, and mesh-exportable 3D scenes from regular images, but they represent a scene as a single monolithic field. Therefore, the reconstruction has no object-level structure, leaving it infeasible for downstream editing or interaction. Moreover, regions that are never directly observed in the input scans are contaminated by the surrounding texture and left uncorrected, capping both mesh fidelity and novel-view synthesis. We propose a decompose-before-reconstruct approach: we segment the instances out of every frame, consider the remaining as background and inpaint it, reconstruct each instance and the background independently with mesh splatting, and compose them into a single scene. Our method significantly improves mesh fidelity (over a 5\\% gain in F-score) and novel-view synthesis, while supporting object-wise modifiability and interactivity. The code will be made publicly available.","authors":["Minhas Kamal","Hiranya Garbha Kumar","Mahedi Kamal","Balakrishnan Prabhakaran"],"published":"2026-08-31T08:20:53Z","updated":"2026-08-31T08:20:53Z","abstract_url":"https://arxiv.org/abs/2608.30423v1","html_url":"https://arxiv.org/html/2608.30423v1","pdf_url":"https://arxiv.org/pdf/2608.30423v1.pdf","matched_keywords":["3d","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30388v1","title":"PRISM: Predictive Recomposition via Semantic Latent Decomposition for View-invariant Video Representation Learning","abstract":"Cross-view video representation learning aims to capture viewpoint-invariant action semantics despite substantial appearance changes across egocentric and exocentric videos. However, existing methods encode each video as a unified embedding, where view-invariant and view-variant semantics inevitably entangle under co-occurrences - a failure mode we show persists even in cross-view methods explicitly trained for view-invariance. Our key insight is that a view-invariant feature is truly disentangled when it can be sufficiently recomposed with an arbitrary view-variant feature while preserving their independent semantics. Building on this, we propose PRISM, that decomposes video into view-invariant and view-variant latents and recompose them under language supervision encouraging clean decomposition of the two streams. PRISM achieves state-of-the-art results on EgoExo4D, EgoExoLearn, AE2, even surpassing in-domain models under zero-shot setting. Code is available at https://github.com/litcoderr/prism.","authors":["Youngchae Chee","Hosu Lee","Sungjune Park","Junho Kim","Yong Man Ro"],"published":"2026-08-31T07:43:02Z","updated":"2026-08-31T07:43:02Z","abstract_url":"https://arxiv.org/abs/2608.30388v1","html_url":"https://arxiv.org/html/2608.30388v1","pdf_url":"https://arxiv.org/pdf/2608.30388v1.pdf","matched_keywords":["video","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30371v1","title":"MCSeg: Pre-training and Fine-tuning Volumetric Pyramid Transformer for Multi-modal Cardiac Image Segmentation","abstract":"Automatic cardiac image segmentation is pivotal for diagnosing and treating cardiac diseases. In this work, we introduce MCSeg, a volumetric transformer-based network tailored for multi-modal cardiac segmentation. To overcome the architectural mismatch inherent in existing hybrid networks, we propose a novel Scaling Feature Pyramid (SFP). Unlike conventional skip connections, the SFP effectively bridges the single-scale 3D Vision Transformer (ViT) encoder and the multi-scale CNN decoder by transforming the ViT's output into a hierarchical feature pyramid, ensuring that global contextual information is effectively leveraged. For the training paradigm, the ViT encoder first undergoes self-supervised pre-training via masked image modeling. Subsequently, the network is fine-tuned on downstream tasks, during which a regional mutual information (RMI) loss is integrated to improve boundary segmentation accuracy. In experiments, MCSeg consistently outperforms eleven SOTA methods on CT dataset ImageCHD, multi-modal dataset MM-WHS, MRI dataset HVSMR-2.0 and MSD Heart, highlighting the effectiveness of our MCSeg for multi-modal cardiac segmentation tasks. Furthermore, MCSeg's superior performance in few-shot experiment showcases its significant potential in adapting to limited data scenarios. Codes and pre-trained ViT-B weights are open-sourced at https://openi.pcl.ac.cn/OpenMedIA/MCSeg","authors":["Zhiyu Ye","Hairong Zheng","Tong Zhang"],"published":"2026-08-31T07:27:10Z","updated":"2026-08-31T07:27:10Z","abstract_url":"https://arxiv.org/abs/2608.30371v1","html_url":"https://arxiv.org/html/2608.30371v1","pdf_url":"https://arxiv.org/pdf/2608.30371v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30344v1","title":"Proximity3D: Shape from Capacitive Proximity on Sensing Manifold","abstract":"Most shape reconstruction methods assume measurements defined over planar sensing domains, such as RGB images or depth maps. In this paper, we use a curved capacitive textile as a shape sensor, treating its surface as a non-planar sensing manifold. Each scan is represented as a capacitive proximity field on this manifold, induced by the interaction between the curved electrode layout and nearby object geometry. We introduce a multi-view feedforward reconstruction model that aggregates these fields across known sensor views and recovers the observed object shape. Simulated and physical experiments demonstrate robust reconstruction from capacitive proximity signals acquired on curved sensing surfaces, pointing toward a new route to robotic near-field geometric awareness via embodied sensing.","authors":["Hao Chen","Chenming Wu","Chun Ping Lam","Xiangjia Chen","Guoxin Fang","Charlie C. L. Wang","Yeung Yam","Juncong Lin","Chengkai Dai"],"published":"2026-08-31T07:00:19Z","updated":"2026-08-31T07:00:19Z","abstract_url":"https://arxiv.org/abs/2608.30344v1","html_url":"https://arxiv.org/html/2608.30344v1","pdf_url":"https://arxiv.org/pdf/2608.30344v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30342v1","title":"CapFrame: Text-Instructed Viewpoint Grounding in 3D Gaussian Scenes via Geometric Pseudo Labels","abstract":"3D Gaussian Splatting (3DGS) enables photorealistic real-time novel view synthesis, yet placing a virtual camera to capture a desired frame remains largely manual. Existing language-guided approaches in 3D scenes mainly focus on object-centric grounding, determining what to observe but rarely controlling how it should appear in a single frame, such as subject orientation or frame layout. To address this limitation, we introduce a new task, Text-Instructed Viewpoint Grounding (TIVG), which aims to identify a 6-DoF camera pose in a 3D Gaussian scene whose rendered frame aligns with a text instruction. To solve this task, we propose CapFrame, a partially differentiable framework that converts language into geometric pseudo labels for camera pose optimization. CapFrame follows a Retrieve-Translate-Refine pipeline: it retrieves relevant views and ranks them through a Question-Evaluation process with MLLMs, translates the instruction into orientation and layout pseudo labels, and refines the camera pose via differentiable optimization with layout and orientation losses in 3DGS. Experiments on 38 real-world scenes with 135 instructions indicate that CapFrame produces viewpoints better aligned with texts than heuristic viewpoint search and adapted trajectory generation baselines, validated by VLM metrics, MLLM judges, and user studies. Code is available at: https://github.com/jirongli/CapFrame","authors":["Jirong Li","Satoshi Ikehata","Shuhei Kurita","Ikuro Sato"],"published":"2026-08-31T06:56:32Z","updated":"2026-08-31T06:56:32Z","abstract_url":"https://arxiv.org/abs/2608.30342v1","html_url":"https://arxiv.org/html/2608.30342v1","pdf_url":"https://arxiv.org/pdf/2608.30342v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30307v1","title":"ScenePilot: Grow-and-Repair Policy for Text-Driven 3D Indoor Scene Generation","abstract":"Text-driven 3D indoor scene generation has advanced from dataset-bound layout modeling to open-vocabulary synthesis with large language and vision-language models. Yet existing methods remain limited: one-pass generators often yield geometrically invalid layouts, heavy post-hoc optimization is costly and unstable, and prompt-only planners lack reusable layout priors for functional grouping and object relations. We propose \\textbf{ScenePilot}, a retrieval-augmented \\textbf{Grow-and-Repair} framework that formulates scene generation as prior-guided incremental growth with learned rectification. Given a prompt, the Hierarchical Retrieval-Augmented Planning (HRAP) module retrieves room-, group-, and anchor-level layout priors to support functional group planning. A text-driven base generator then inserts object groups sequentially, while the Reinforcement Multimodal Repair (RMR) module performs lightweight local correction after each insertion and a final global repair after completion. To train this policy, we construct \\textbf{SceneReverse-17k}, a repair-trajectory dataset built by perturbing high-quality 3D scenes in position, rotation, and scale, then using inverse operations as executable rectification targets. The policy predicts structured \\emph{move--rotate--scale} actions from rendered views, scene state, retrieved priors, and edit history. By combining HRAP with RMR, ScenePilot offers an efficient alternative to one-shot generation and heavy full-scene optimization, improving physical plausibility, functional coherence, and controllability while preserving diversity.","authors":["Jiawei Zhang","Hongsong Wang","Pan Zhou"],"published":"2026-08-31T06:22:11Z","updated":"2026-08-31T06:22:11Z","abstract_url":"https://arxiv.org/abs/2608.30307v1","html_url":"https://arxiv.org/html/2608.30307v1","pdf_url":"https://arxiv.org/pdf/2608.30307v1.pdf","matched_keywords":["retrieval","3d","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30294v1","title":"Dynamic Hub-and-Spoke Memory for Streaming Video Understanding","abstract":"Streaming video understanding requires answering questions at arbitrary times over a continuously growing visual stream. The central challenge is to compactly remember long-range history while effectively retrieving question-relevant evidence. We propose Dynamic Hub-and-Spoke Memory (D-HSM), a training-free framework that represents distant history as structured textual memory while preserving the recent frames as visual tokens for fine-grained perception. Specifically, D-HSM turns selected historical video chunks into typed textual observations and stores them in an entity-centered hub-and-spoke memory, with entities as hubs and related evidence as spokes. When answering a question, D-HSM dynamically retrieves a compact question-aware memory subset, expands it through hub-and-spoke links, and combines it with the recent visual window for frozen-VLM answer prediction. Extensive experiments on both streaming and long video benchmarks show that D-HSM consistently and substantially improves VLM backbones and outperforms other state-of-the-art online and offline video understanding baselines.","authors":["Xinru Jiang","Lin Zhao","Xi Xiao","Yunbei Zhang","Janet Wang","Chenrui Ma","Haolin Li","Yanzhi Wang","Yifan Gong","Octavia Camps"],"published":"2026-08-31T06:02:28Z","updated":"2026-08-31T06:02:28Z","abstract_url":"https://arxiv.org/abs/2608.30294v1","html_url":"https://arxiv.org/html/2608.30294v1","pdf_url":"https://arxiv.org/pdf/2608.30294v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30281v1","title":"SELECT: SELEctive Context Transfer for Class-Incremental Semantic Segmentation","abstract":"Class-Incremental Semantic Segmentation (CISS) is fundamentally challenged by catastrophic forgetting and background shift, where learning new concepts degrades performance on previously seen classes. While existing methods attempt to balance stability (retaining old knowledge) and plasticity (learning new knowledge), they often fail to leverage prior knowledge effectively. These approaches typically rely on indiscriminate knowledge transfer or ambiguous initializations, which can dilute crucial semantic information. To overcome this limitation, we propose SELECT, a novel approach for Selective Context Transfer, which instead grounds each new class in a small set of semantically similar past classes. Its core is a Context Transfer Attention mechanism that aggregates the learned tokens from similar classes into a structured initialization for the new class. To ensure this transfer does not corrupt the borrowed representations, we add a controlled noise perturbation and a margin-based context-transfer loss that enforces separation between the new class token and its source tokens. Extensive experiments on Pascal VOC and ADE20K show that SELECT consistently outperforms prior work, achieving mIoU of 2.2% on VOC and 2.8% on ADE, providing an effective handle on the stability-plasticity dilemma. Code is available at https://github.com/avigupta2798/SELECT.","authors":["Avi Gupta","Saurabh Yadav","Koteswar Rao Jerripothula","Tammam Tillo"],"published":"2026-08-31T05:50:10Z","updated":"2026-08-31T05:50:10Z","abstract_url":"https://arxiv.org/abs/2608.30281v1","html_url":"https://arxiv.org/html/2608.30281v1","pdf_url":"https://arxiv.org/pdf/2608.30281v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30279v1","title":"Motion-Saliency Complementary Masked Modeling for Point Cloud Video Understanding","abstract":"Point cloud video representation learning is crucial for 3D dynamic scene understanding. In this paper, we propose MoSaiC, a novel Motion-Saliency Complementary masked modeling framework for self-supervised point cloud video representation learning. MoSaiC couples three components: Curriculum Motion-Saliency Masking (CMSM), which guides the masking process toward motion-salient tokens under a curriculum schedule; Normal-Flow Motion (NFM) modeling, which supervises the local rigid rotation of each token in the Lie algebra so(3) as an explicit geometric motion target; and Cross-view Token Consistency Prediction (CTCP), which enforces consistency between two complementary masked views at the token level. Together, these components allow MoSaiC to effectively capture both appearance and motion dynamics. Extensive experiments on multiple downstream tasks, including action recognition, temporal action segmentation, and point-level semantic segmentation, demonstrate the effectiveness of our approach.","authors":["Wei Wang","Yiding Sun","Yuyan Wang","Zhuoyue Zhang","Zhengqiao Li","Dongfu Yin","Chen Li"],"published":"2026-08-31T05:48:33Z","updated":"2026-08-31T05:48:33Z","abstract_url":"https://arxiv.org/abs/2608.30279v1","html_url":"https://arxiv.org/html/2608.30279v1","pdf_url":"https://arxiv.org/pdf/2608.30279v1.pdf","matched_keywords":["video","3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30263v1","title":"Centering before Pruning: Lightweight Geometry Correction for Diversity-Based Visual Token Pruning in LVLMs","abstract":"Large vision-language models (LVLMs) incur substantial inference costs due to their long and highly redundant visual-token sequences. Diversity-based pruning mitigates this cost by selecting token subsets based on pairwise cosine similarity. We find, however, that similarities between raw visual tokens are strongly concentrated in the positive range, limiting their ability to distinguish non-redundant tokens. A natural way to improve this resolution is to center token features before computing cosine similarity. Centering indeed reveals a substantially richer pairwise structure, yet unexpectedly degrades pruning performance when used alone. We show that this apparent contradiction arises because the raw geometry does more than represent pairwise diversity: it also implicitly favors globally distinctive tokens, which tend to contain semantically informative content. Centering better resolves subset diversity but loses this useful token-wise preference, revealing that diversity and distinctiveness are entangled in the raw geometry. Based on this analysis, we propose the \\textbf{Cen}tered Geometry \\textbf{Prune}r (Cen-Prune), which measures subset diversity using centered cosine similarity while retaining raw-space distinctiveness as a complementary token-wise preference. This lightweight, plug-and-play correction leaves the underlying selection mechanism unchanged and incurs negligible computational overhead. Extensive experiments across multiple image- and video-understanding benchmarks and LVLM architectures demonstrate that Cen-Prune provides robust improvements in overall performance across existing diversity-based pruners.","authors":["Shunjie Wen","Jaeyeon Lee","Dong-Wan Choi"],"published":"2026-08-31T05:13:29Z","updated":"2026-08-31T05:13:29Z","abstract_url":"https://arxiv.org/abs/2608.30263v1","html_url":"https://arxiv.org/html/2608.30263v1","pdf_url":"https://arxiv.org/pdf/2608.30263v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30247v1","title":"OPUS: A Simple yet Effective Unified Framework for Open-Vocabulary Detection","abstract":"Recent unified open-vocabulary detection (OVD) supports heterogeneous prompts, including text queries, visual exemplars, and their combinations, but often rely on increasingly complex designs such as heavy cross-modal fusion, staged training, and iterative annotation pipelines. We revisit whether such complexity is necessary in the era of stronger foundation models. Our finding is that unified OVD can be made substantially simpler with semantic-rich visual representations and scalable grounding supervision. We present OPUS (\\textbf{O}pen-vocabulary, \\textbf{P}rompt-\\textbf{U}nified, \\textbf{S}imple), a unified detector supporting text, interactive visual, generic visual, and mixed prompting within one framework. OPUS adopts a simple three-part design. Its model architecture combines a semantic-rich visual encoder, built on a DINOv3-ConvNeXt-B backbone with efficient hybrid encoding, with a prompt-aware decoder that avoids prompt-specific branches for unified prompt reasoning. OPUS is trained with a one-stage text-visual training strategy with Instance-level Contrastive Alignment (ICA), and is supported by a SAM3-based single-pass data engine for heterogeneous grounding supervision. Experiments on COCO, LVIS-minival, and ODinW35 show that OPUS achieves state-of-the-art Visual-I performance, reaching 68.1/69.2/54.7 AP, while maintaining balanced Text and Visual-G accuracy. OPUS also turns mixed prompting from interference into complementarity, improving over text or visual prompt alone. These results show that simplicity and strong unified prompting capability can be achieved together.","authors":["Xiaoyan Wei","Zhimin Yao","Ruilin Yang","Wei Zhang","Yong Dai","Yi Zhang","Wei Ge"],"published":"2026-08-31T04:57:12Z","updated":"2026-08-31T04:57:12Z","abstract_url":"https://arxiv.org/abs/2608.30247v1","html_url":"https://arxiv.org/html/2608.30247v1","pdf_url":"https://arxiv.org/pdf/2608.30247v1.pdf","matched_keywords":["representation","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30241v1","title":"PaperBanana-Interact: Scientific Diagram Refinement with Multi-Turn Human Feedback","abstract":"Recent efforts have aimed to automate scientific diagram generation from paper content (Lin et al., 2026; Zhu et al., 2026a). However, fully satisfying an author's visual and communicative preferences in a single turn is challenging: in our formative user study (N = 14), all participants requested further revisions after viewing an initial draft, and 86% of them rated the refined diagrams as more satisfactory. Despite the clear demand, the multi-turn workflow remains largely underexplored. To bridge this gap, we present MTPaperBananaBench, a benchmark for multi-turn diagram generation containing 292 images annotated with 3,518 user requirements. To reduce expensive human studies and enable scalable benchmarking, we construct a user simulator that, at each turn, identifies unsatisfied requirements and converts k of them into natural language feedback. Evaluating both requirement satisfaction and overall diagram quality reveals two key failure modes shared across baseline multiturn systems: (1) quality drift, where diagram quality progressively declines over turns, and (2) forgetting, where previously implemented features are lost in subsequent turns. To address these issues, we introduce PaperBanana-Interact, a multi-agent system that refines diagrams via an internal critique-and-refine loop. PaperBanana-Interact consistently improves rather than degrades diagram quality across turns, outperforming baselines by 11.9-18.6 points in quality score and reducing forgetting by 3.7-6.2 points.","authors":["Xueqing Wu","Ashwin Balasubramanian","Bingxuan Li","Dawei Zhu","Kai-Wei Chang","Yale Song","Yiwen Song","Rui Meng","Tomas Pfister","Nanyun Peng"],"published":"2026-08-31T04:52:32Z","updated":"2026-08-31T04:52:32Z","abstract_url":"https://arxiv.org/abs/2608.30241v1","html_url":"https://arxiv.org/html/2608.30241v1","pdf_url":"https://arxiv.org/pdf/2608.30241v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30237v1","title":"Motus2: A Self-Evolving General World Model for Dexterous Manipulation","abstract":"General embodied agents should perceive, predict, act, evaluate, and improve within a unified system. World models have shown great promise in building such agents, yet existing models typically append an action output head to a world simulator, without coupling them into a closed decision-and-learning loop for policy improvement. We present Motus2, a self-evolving general world model for dexterous manipulation. Motus2 advances world modeling through model scaling and data scaling. For model scaling, a single model with shared weights exposes three control interfaces: a policy (world-action model), a simulator (action-conditioned world model), and an evaluator (value model). The policy proposes candidate action chunks, the simulator predicts their visual consequences, and the evaluator assesses the predicted outcomes. Their coupling forms a closed decision-and-learning loop for policy improvement. This formulation uses curated expert demonstrations for action learning, while failed and suboptimal interactions provide valuable evidence for dynamics modeling and value learning. For data scaling, Motus2 progresses from large-scale monocular egocentric data to synchronized stereo egocentric data, followed by robot-domain adaptation with robot trajectories and supplementary human-robot alignment data. Motus2 further studies global-autoregressive and hybrid-memory extensions of its sliding-window context, adds tactile feedback for contact-aware control, and is instantiated on a fully biomimetic platform with stereo vision, dual arms, dual dexterous hands, and tactile sensing. Together, egocentric data scaling and closed-loop general world model scaling provide a general path toward self-evolving dexterous manipulation.","authors":["Hongzhe Bi","Zihao Zhou","Yihang Tang","Jingrui Pang","Shuhe Huang","Haitian Liu","Runqing Wang","Shuai Huang","Yichen Wang","Yiming Cheng","Ruowen Zhao","Zhenghua Li","Hengkai Tan","Xiaolong Liu","Jinhui Wan","Jiabao Liu","Min Zhao","Fan Bao","Jun Zhu"],"published":"2026-08-31T04:44:33Z","updated":"2026-08-31T04:44:33Z","abstract_url":"https://arxiv.org/abs/2608.30237v1","html_url":"https://arxiv.org/html/2608.30237v1","pdf_url":"https://arxiv.org/pdf/2608.30237v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30233v1","title":"Semantic-Spatial Discriminability Enhancement for Generalized Visual Grounding","abstract":"Generalized Visual Grounding (GVG) task aims to localize targets in an image based on referring expressions, extends the classical visual grounding paradigm by integrating multi-target and non-target scenarios. Previous methods typically rely on global semantic matching or coarse-grained region interactions for localization, where the discriminative cues are primarily derived from sentence-level semantics or regional context. In complex multi-target scenarios, such approaches tend to confuse visually similar targets, making it difficult to establish stable instance-level decision boundaries. To address these limitations, this paper proposes a novel Semantic-Spatial Discriminability Enhancement (SSDE) framework for generalized visual grounding, which aims to enhance the discriminative ability on fine-grained semantics and spatial localization, improving both cross-modal understanding and instance-level grounding. Specifically, to enhance the semantic discriminability of query representations at the fine-grained level, we propose a Semantic Discriminability Enhancement (SeDE) module, which leverages spatially guided cross-attention to disentangle fine-grained target-relevant visual attributes and integrates them with the textual subject semantics. Furthermore, to strengthen the spatial discriminability of the referred targets, we introduce a Spatial Discriminability Enhancement (SpDE) module, which models an instance center density map to characterize the spatial distribution of targets, and explicitly constructs instance separation structures in the spatial domain by employing them as an auxiliary supervision signal. Extensive experiments show that SSDE achieves superior performance on ten datasets across both classic and generalized visual grounding tasks.","authors":["Kaiyan Lei","Xu-Yao Zhang"],"published":"2026-08-31T04:37:36Z","updated":"2026-08-31T04:37:36Z","abstract_url":"https://arxiv.org/abs/2608.30233v1","html_url":"https://arxiv.org/html/2608.30233v1","pdf_url":"https://arxiv.org/pdf/2608.30233v1.pdf","matched_keywords":["representation","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30218v1","title":"Amortized Anchor Refinement for Deployable Continuous-Time 4D Gaussian Reconstruction","abstract":"Continuous-time 4D reconstruction remains impractical on standalone XR headsets. Per-scene optimization demands deployment-infeasible compute, and lower budgets cause collapse rather than degrade gradually. Feed-forward prediction is fast, but struggle to recover scene-specific detail. We present Amortized Anchor Refinement, which uses a frozen backbone to predict an initial Gaussian representation and a short optimization to specialize it under a fixed compute budget, with a capacity floor preserving representational density. A training-free stage then applies a persistent-homology constraint to prune unstable Gaussians while preserving topologically persistent structures, and streams the resulting trajectories directly as scene flow. On the Stage-Capture benchmark, Amortized Anchor Refinement achieves 24.31$\\pm$2.22dB, while our deployment experiments demonstrate reconstruction within the target budget on a single consumer GPU and playback on a standalone XR headset.","authors":["Jingong Chen","Qingwen Zhang","Sanghyeon Jun","Chulwoo Pack","Kyle Gao","Kwanghee Won"],"published":"2026-08-31T04:04:04Z","updated":"2026-08-31T04:04:04Z","abstract_url":"https://arxiv.org/abs/2608.30218v1","html_url":"https://arxiv.org/html/2608.30218v1","pdf_url":"https://arxiv.org/pdf/2608.30218v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"},{"id":"2608.30213v1","title":"Towards a Joint Khmer Text Recognition and Word Segmentation","abstract":"Text recognition, or extracting electronic text from document images, has been indispensable for knowledge retrieval tasks, such as retrieval-augmented generation (RAG). For Khmer, extracted text is subject to an extra word segmentation step, as Khmer does not use any visible word delimiters to denote word boundaries. Thus, a recognition-then-segmentation pipeline for Khmer requires two separate sequential models; this is not only error-prone but also adds significant latency for large-scale document processing. This paper proposes a novel joint Khmer text recognition and word segmentation framework in a unified model. The proposed model, using a connectionist-temporal-classification (CTC) decoder for fast, parallel decoding, can be instructed to recognize Khmer text with ($b=1$) and without ($b=0$) word segmentation. Experimental results on different benchmark datasets of different document modalities (document, scene, and handwritten images) show that the proposed model can not only recognize characters in document images but also locate word boundaries, removing the need for an extra word segmentation step in a conventional sequential pipeline.","authors":["Marry Kong","Rina Buoy","Sovisal Chenda","Nguonly Taing","Masakazu Iwamura","Koichi Kise"],"published":"2026-08-31T03:53:25Z","updated":"2026-08-31T03:53:25Z","abstract_url":"https://arxiv.org/abs/2608.30213v1","html_url":"https://arxiv.org/html/2608.30213v1","pdf_url":"https://arxiv.org/pdf/2608.30213v1.pdf","matched_keywords":["retrieval"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-01T05:58:30+00:00","last_seen_at":"2026-09-01T05:58:30+00:00"}],"tracked_paper_count":73,"storage_mode":"latest_overwrite"}};
